// ---------------------------------------------------------------------------
// REAL UNOFFICIAL HOLIDAYS — fixed-date observances, one per day.
// These are real holidays from the national-day calendars (National Donut
// Day is the famous exception: it is movable — first Friday in June — and
// is computed in getMovableHoliday() below). Off*Script's own holidays in
// CORE_HOLIDAYS take precedence over this table on their dates.
// Dates here should be spot-checked against a calendar source (e.g.
// timeanddate) — observances occasionally move years.
// ---------------------------------------------------------------------------
type RealHoliday = Omit<KhaosHoliday, "dateKey" | "month" | "day">;

const REAL_HOLIDAYS: Record<string, RealHoliday> = {
  // ---- January ----
  "01-01": { title: "National Hangover Day", tagline: "You earned this couch. Hydrate like it is a job.", meaning: "National Hangover Day. The first day of the year, and the only holiday whose official activity is lying still and drinking water. It means starting the year honestly: yesterday happened, today is for recovery, and no grand reinvention is required before noon.", anchorQuestion: "What does your first day of the year actually need — a plan, or a glass of water?", whoIsThisSoul: ["What did last night teach you about the version of you that shows up at parties?", "If you could start any year over with zero resolutions, what would day one look like?"], adventures: ["Drink a full glass of water before you touch your phone.", "Eat something salty and greasy with zero guilt and zero commentary."] },
  "01-02": { title: "National Science Fiction Day", tagline: "The future called. It wants its weird back.", meaning: "National Science Fiction Day, on Isaac Asimov's birthday. Sci-fi is just permission to ask what if and then live in the answer for a while. It means the future is not something that happens to you — it is something somebody imagined first.", anchorQuestion: "What future are you quietly imagining for yourself?", whoIsThisSoul: ["Which sci-fi world feels more honest than the real one right now?", "What invention do you wish existed for your actual life?"], adventures: ["Watch or read ten minutes of sci-fi you have been meaning to try.", "Write down one piece of future tech you would actually use daily."] },
  "01-03": { title: "Festival of Sleep Day", tagline: "Permission to nap. Not that you needed it.", meaning: "Festival of Sleep Day. A whole holiday dedicated to staying in bed, and somehow the world keeps spinning. It means rest is not the prize for finishing everything — rest is the activity. The festival has one event: sleep.", anchorQuestion: "When did you last sleep like it was the main event?", whoIsThisSoul: ["What keeps you up that would not survive a full night of sleep?", "If sleep were a party, what would you bring?"], adventures: ["Take a nap today and call it celebrating.", "Go to bed thirty minutes earlier than usual, on purpose."] },
  "01-04": { title: "National Spaghetti Day", tagline: "Twirl first, ask questions never.", meaning: "National Spaghetti Day. A noodle so universal it needs no translation and no occasion. It means dinner does not have to be impressive to be right. Sauce on your shirt is not a failure — it is evidence.", anchorQuestion: "What simple meal feels like home to you?", whoIsThisSoul: ["What is your most chaotic spaghetti memory?", "If your life were a pasta shape, which one would it be?"], adventures: ["Eat spaghetti today. Twirl it. No cutting allowed.", "Make the sauce from scratch if you can, jar if you cannot — no judgment either way."] },
  "01-05": { title: "National Bird Day", tagline: "Look up. They have been here the whole time.", meaning: "National Bird Day. Birds do not check the news, do not doomscroll, and still manage to sing at dawn. It means you can look up from your own head for five minutes and watch something that lives entirely in the present.", anchorQuestion: "What is the last wild thing you actually stopped to watch?", whoIsThisSoul: ["If you were a bird, would you migrate or stay put?", "What would your morning sound like if you sang first?"], adventures: ["Watch a bird for two full minutes. That is the whole assignment.", "Learn the name of one bird you see regularly."] },
  "01-06": { title: "National Cuddle Up Day", tagline: "Blanket. Couch. Someone warm. Go.", meaning: "National Cuddle Up Day. January is cold and the news is cold and the whole month feels like a draft. It means warmth is a legitimate plan. Blanket, couch, warm body — human, dog, or heated blanket, no hierarchy.", anchorQuestion: "Who or what is your warmest place?", whoIsThisSoul: ["What does comfort look like when nobody is watching?", "When did you last let yourself be fully cozy without earning it?"], adventures: ["Cuddle something warm for at least ten minutes today.", "Build a blanket fort. Yes, at your age."] },
  "01-07": { title: "National Bobblehead Day", tagline: "Nod along. Everyone else is.", meaning: "National Bobblehead Day. A whole holiday for a toy whose only job is agreeing with you, forever, at a wobble. It means sometimes the most honest thing you can do is nod at your own life and say, yep, that happened.", anchorQuestion: "What have you been nodding along to that you do not actually agree with?", whoIsThisSoul: ["Who in your life is a bobblehead — all nod, no pushback?", "What would you say if your head stopped nodding?"], adventures: ["Nod at everything for five minutes and notice how it feels.", "Find the most ridiculous bobblehead you can and display it proudly."] },
  "01-08": { title: "National Bubble Bath Day", tagline: "Prune fingers are a badge of honor.", meaning: "National Bubble Bath Day. A bath is the only meeting you cannot be productive in, which is exactly why it works. It means soaking is not wasting time — it is the time. The bubbles are doing the work.", anchorQuestion: "When did you last do something with zero productive output on purpose?", whoIsThisSoul: ["What would your bathwater say about your week?", "What are you soaking off today?"], adventures: ["Take a bubble bath today. Bubbles mandatory, phone optional.", "Light a candle in the bathroom even if it feels dramatic. It is dramatic. That is the point."] },
  "01-09": { title: "National Static Electricity Day", tagline: "You are a lightning storm in socks.", meaning: "National Static Electricity Day. Winter air turns every doorknob into a tiny betrayal and every sweater into a spark show. It means the world is literally electric under the surface — you are walking around charged and nobody can see it.", anchorQuestion: "What small shock has this winter already given you?", whoIsThisSoul: ["Where does your static build up — and who gets zapped when it discharges?", "What would you do with a real spark of energy right now?"], adventures: ["Shuffle across carpet in socks and touch a doorknob on purpose.", "Notice every static shock today and keep count."] },
  "01-10": { title: "National Houseplant Appreciation Day", tagline: "They are alive because of you. Mostly.", meaning: "National Houseplant Appreciation Day. Houseplants are the only roommates who never complain, never leave dishes, and quietly clean your air. It means keeping something alive — even a pothos — counts as caregiving. Water them. They have been patient.", anchorQuestion: "What in your life is quietly thriving on your neglect?", whoIsThisSoul: ["Which plant in your house is you, and which one is who you pretend to be?", "What would you grow if failure were impossible?"], adventures: ["Water every plant you own today.", "Name one unnamed plant. It deserved better."] },
  "01-11": { title: "National Step in a Puddle and Splash Your Friends Day", tagline: "The puddle is right there. You know what to do.", meaning: "National Step in a Puddle and Splash Your Friends Day. The most specific holiday ever invented, and somehow the most honest: joy is a puddle and your friends are standing right there. It means being a menace in the smallest possible way is a valid form of love.", anchorQuestion: "When did you last play like a kid on purpose?", whoIsThisSoul: ["Who would you splash first, and what does that say about them?", "What puddle have you been carefully walking around?"], adventures: ["Step in a puddle on purpose. Splash optional, encouraged.", "Text a friend something mischievous just because."] },
  "01-12": { title: "National Kiss a Ginger Day", tagline: "Redheads. Today is their day. Pucker up.", meaning: "National Kiss a Ginger Day. Created because redheads catch grief for the rarest hair on earth, and the holiday decided to flip it into a celebration. It means the thing people teased you for might be the thing worth kissing.", anchorQuestion: "What were you teased for that turned out to be your best feature?", whoIsThisSoul: ["What rare thing about you deserves its own holiday?", "Who in your life has never been properly celebrated?"], adventures: ["Compliment a redhead today. Consent first, obviously.", "Celebrate one rare thing about yourself out loud."] },
  "01-13": { title: "National Sticker Day", tagline: "Stick it everywhere. No surface is safe.", meaning: "National Sticker Day, on the birthday of the man who invented the modern sticker. Stickers are tiny art with commitment issues — they go anywhere and mean everything. It means small decorations are not frivolous. They are how you claim a surface as yours.", anchorQuestion: "What surface in your life needs claiming?", whoIsThisSoul: ["What sticker would you put on your forehead if you had to wear one all day?", "Which label have you outgrown?"], adventures: ["Stick a sticker on something today. Laptop, planner, forehead — your call.", "Design your own sticker in your head and describe it to someone."] },
  "01-14": { title: "National Dress Up Your Pet Day", tagline: "The dog did not consent, but the photo is worth it.", meaning: "National Dress Up Your Pet Day. The one day a year when putting a tiny hat on a dog is not just allowed — it is the assignment. It means joy does not need a reason, and dignity is negotiable when there is a camera.", anchorQuestion: "What would your pet wear if it had a say?", whoIsThisSoul: ["Who in your life tolerates your nonsense the way a dog tolerates a hat?", "What costume would you wear if judgment did not exist?"], adventures: ["Dress up your pet, or admire someone else's dressed-up pet online.", "Put on one ridiculous accessory yourself. Match the pet."] },
  "01-15": { title: "National Hat Day", tagline: "Wear the hat. Be the hat.", meaning: "National Hat Day. Hats are the only accessory that changes your whole silhouette and your whole attitude in one move. It means you can try on a different version of yourself for the price of a hat. The hat is not a costume — it is a decision.", anchorQuestion: "What version of you comes out when you wear a hat?", whoIsThisSoul: ["What are you hiding under your hat today — literally or otherwise?", "If your life had a hat, what would it look like?"], adventures: ["Wear a hat today. Any hat. The weirder, the better.", "Tip your hat to someone. Yes, like that."] },
  "01-16": { title: "National Nothing Day", tagline: "Do nothing. Celebrate nothing. Achieve nothing.", meaning: "National Nothing Day, founded as a protest against a calendar full of made-up holidays. The irony is not lost on anyone. It means one day a year is officially reserved for absolutely nothing — no celebration, no productivity, no meaning. Just nothing.", anchorQuestion: "What would you do with a day that required nothing of you?", whoIsThisSoul: ["How hard is it for you to do nothing? Be honest.", "What does nothing feel like when you stop fearing it?"], adventures: ["Do nothing for fifteen minutes today. Set a timer. Nothing counts.", "Cancel one thing you were doing out of obligation."] },
  "01-17": { title: "National Ditch New Year's Resolutions Day", tagline: "The resolutions were a setup. Ditch them.", meaning: "National Ditch New Year's Resolutions Day. January 17 is statistically when most resolutions die, so the holiday just made it official. It means quitting a resolution is not failure — it is data. The resolution was probably someone else's idea anyway.", anchorQuestion: "Which resolution of yours was never really yours?", whoIsThisSoul: ["What would you do instead of the resolution you just ditched?", "Who were you trying to impress with that goal?"], adventures: ["Ditch one resolution today, out loud, with zero guilt.", "Replace it with something you actually want to do."] },
  "01-18": { title: "National Winnie the Pooh Day", tagline: "A bear of very little brain, and a lot of heart.", meaning: "National Winnie the Pooh Day, on A.A. Milne's birthday. Pooh is the patron saint of doing nothing with great intention and loving snacks unconditionally. It means a bear of very little brain can still be the wisest character in the forest.", anchorQuestion: "What would Pooh say about your current problem?", whoIsThisSoul: ["Are you Pooh, Piglet, Eeyore, or Tigger today?", "What is your honey pot — the thing you love without reason?"], adventures: ["Eat something sweet and simple today, Pooh-style.", "Say one kind, simple thing to someone. Pooh would."] },
  "01-19": { title: "National Popcorn Day", tagline: "Salt. Butter. Zero regrets.", meaning: "National Popcorn Day. Popcorn is the only food that is also an activity — the popping, the shaking, the fishing for the burnt ones at the bottom. It means some snacks are not about hunger. They are about the show.", anchorQuestion: "What is your movie-night snack hierarchy?", whoIsThisSoul: ["What are you really hungry for that is not food?", "If your life were a movie, what genre would the popcorn be for?"], adventures: ["Eat popcorn today. Extra butter if you are feeling brave.", "Watch something — anything — with a bowl of popcorn in your lap."] },
  "01-20": { title: "National Cheese Lovers Day", tagline: "Say cheese. Then eat it.", meaning: "National Cheese Lovers Day. Cheese is milk that refused to be ordinary and got better with age — a career path worth considering. It means loving something deeply and unironically is a personality trait, not a guilty pleasure.", anchorQuestion: "What do you love with the intensity cheese lovers love cheese?", whoIsThisSoul: ["What is your cheese — the thing you will defend to strangers?", "Sharp, soft, stinky, or melted: which one are you today?"], adventures: ["Eat your favorite cheese today. The good stuff, not the sad slice.", "Try a cheese you have never had before."] },
  "01-21": { title: "National Hugging Day", tagline: "Free hugs. No strings. Arms open.", meaning: "National Hugging Day. Started because people in January are cold, lonely, and touch-starved, and a hug is the cheapest medicine on the shelf. It means contact is not a luxury. It is maintenance.", anchorQuestion: "Who do you need a hug from right now?", whoIsThisSoul: ["When did you last hug someone like you meant it?", "What does a hug fix that words cannot?"], adventures: ["Hug someone today. Ask first, then commit.", "Send a hug in text form to someone far away."] },
  "01-22": { title: "National Answer Your Cat's Questions Day", tagline: "The cat has questions. You have answers. Probably.", meaning: "National Answer Your Cat's Questions Day. Your cat has been asking you things all day — mostly about food and why you exist — and today you owe it answers. It means the smallest member of the household has a voice, and today it gets heard.", anchorQuestion: "What is your cat asking you right now?", whoIsThisSoul: ["If your cat could ask one real question, what would it be?", "What are you asking that nobody is answering?"], adventures: ["Talk to your cat today. Full conversation. Out loud.", "If you have no cat, talk to any animal. They are listening."] },
  "01-23": { title: "National Handwriting Day", tagline: "Your handwriting is a fingerprint with ink.", meaning: "National Handwriting Day, on John Hancock's birthday — the man with the biggest signature in American history. Handwriting is the only font that is also a person. It means your messy, slanted, half-cursive scrawl is a document nobody else can forge.", anchorQuestion: "When did you last write something by hand that mattered?", whoIsThisSoul: ["What does your handwriting say about you that typing never could?", "Whose handwriting would you recognize anywhere?"], adventures: ["Write something by hand today — a note, a list, a single sentence.", "Sign your name bigger than necessary. Hancock energy."] },
  "01-24": { title: "National Compliment Day", tagline: "Say the nice thing. Out loud. Today.", meaning: "National Compliment Day. The compliment you are holding back is not modesty — it is a gift you are hoarding. It means the nice thing you noticed about someone only counts if you say it. Today, say it.", anchorQuestion: "What compliment have you been sitting on?", whoIsThisSoul: ["What compliment would you want to hear today?", "Why is it easier to criticize than to compliment?"], adventures: ["Give three real compliments today. Specific ones, not generic.", "Accept a compliment without deflecting. Just say thank you."] },
  "01-25": { title: "National Opposite Day", tagline: "Everything you say is wrong. On purpose.", meaning: "National Opposite Day. The one day where no means yes, up means down, and every sentence is a trap. It means language is a game and today the rules are inverted. Say the opposite of what you mean and watch people figure it out.", anchorQuestion: "What is the opposite of what you actually want today?", whoIsThisSoul: ["If you lived opposite day every day, what would change first?", "What truth would you tell if everyone assumed you meant the opposite?"], adventures: ["Say the opposite of one thing today and see if anyone notices.", "Do one thing backwards — walk a different route, eat dessert first."] },
  "01-26": { title: "National Spouses Day", tagline: "The person you chose. On purpose. Again.", meaning: "National Spouses Day. Not the wedding, not the anniversary — just the ordinary Tuesday of being married. It means the spouse is not a role, it is a person you keep choosing. Today, choose them out loud.", anchorQuestion: "What did you choose about your person that you would choose again?", whoIsThisSoul: ["What does your spouse do that nobody else would put up with — in a good way?", "When did you last tell your spouse the specific thing you love about them?"], adventures: ["Tell your spouse one specific thing you love about them today.", "Do one small thing for your spouse without being asked."] },
  "01-27": { title: "National Chocolate Cake Day", tagline: "Cake for breakfast is a valid life choice.", meaning: "National Chocolate Cake Day. Chocolate cake is not a dessert — it is a coping strategy with frosting. It means some days the answer really is cake, and no amount of productivity advice will beat it.", anchorQuestion: "What problem in your life would chocolate cake actually help?", whoIsThisSoul: ["What is your cake — the comfort you reach for when nothing else works?", "When did you last eat cake without a reason?"], adventures: ["Eat chocolate cake today. Breakfast counts.", "Share a slice with someone. Cake is better split."] },
  "01-28": { title: "National Blueberry Pancake Day", tagline: "Pancakes, but make them fancy.", meaning: "National Blueberry Pancake Day. A pancake is already a celebration; a blueberry in it is a tiny surprise in every bite. It means small upgrades matter. You do not need a new life — you need blueberries in the pancakes you already make.", anchorQuestion: "What small upgrade would make your ordinary day better?", whoIsThisSoul: ["What is your pancake — the ordinary thing you love anyway?", "Where could you add one blueberry to your routine?"], adventures: ["Eat blueberry pancakes today. Frozen blueberries count.", "Add one small upgrade to something ordinary today."] },
  "01-29": { title: "National Puzzle Day", tagline: "One piece at a time. That is the whole trick.", meaning: "National Puzzle Day. A puzzle is the only problem that promises you it has a solution and all the pieces are in the box. It means some problems are worth solving slowly, one piece at a time, with no deadline and no prize.", anchorQuestion: "What puzzle in your life is missing one piece?", whoIsThisSoul: ["Are you the corner piece, the edge, or the weird sky piece nobody can place?", "What would you do with a problem that had no deadline?"], adventures: ["Work on a puzzle today — jigsaw, crossword, or the puzzle of your own day.", "Find the missing piece of one unfinished thing."] },
  "01-30": { title: "National Croissant Day", tagline: "Flaky. Buttery. Worth the mess.", meaning: "National Croissant Day. A croissant is 27 layers of butter and patience, and it falls apart the second you touch it — which is exactly why it is perfect. It means beautiful things are allowed to be messy. Flake everywhere.", anchorQuestion: "What in your life is worth the mess?", whoIsThisSoul: ["Are you a croissant person — layered, buttery, falling apart gracefully?", "What took 27 layers to build in your life?"], adventures: ["Eat a croissant today. A real one, not the sad tube kind.", "Let something be messy today without fixing it immediately."] },
  "01-31": { title: "National Hot Chocolate Day", tagline: "Marshmallows are not optional.", meaning: "National Hot Chocolate Day. Hot chocolate is a hug you can drink, and January 31 is the last day of the longest month — you have earned it. It means the month is over, you survived it, and the reward is chocolate in a mug.", anchorQuestion: "What did January teach you that you are bringing into February?", whoIsThisSoul: ["What is your hot chocolate — the warm thing that gets you through?", "Who would you share a mug with right now?"], adventures: ["Drink hot chocolate today. Marshmallows mandatory.", "Make it from scratch if you can. Packet if you cannot. No shame."] },
  // ---- February ----
  "02-01": { title: "National Serpent Day", tagline: "Snakes. Misunderstood since the Garden.", meaning: "National Serpent Day. Snakes have been the villains of every story since the beginning, and they are still just out here being snakes. It means the thing everyone fears might just be minding its own business. Give the serpent a second look.", anchorQuestion: "What have you been afraid of that turned out to be harmless?", whoIsThisSoul: ["What is your serpent — the thing people misjudge about you?", "If you shed your skin, what would the new one look like?"], adventures: ["Learn one cool fact about snakes today.", "Shed one old skin — a habit, a grudge, a story about yourself."] },
  "02-02": { title: "Groundhog Day", tagline: "Six more weeks, or spring. The groundhog decides.", meaning: "Groundhog Day. A rodent looks at its shadow and decides the weather for a continent, and we all just go along with it. It means some traditions make no sense and we keep them anyway, because they are ours.", anchorQuestion: "What tradition do you keep that makes no sense?", whoIsThisSoul: ["If you saw your shadow today, what would it tell you?", "What would you do with six more weeks of winter?"], adventures: ["Check your shadow today. Report the forecast to someone.", "Watch the movie. You know the one."] },
  "02-03": { title: "National Carrot Cake Day", tagline: "It has vegetables, so it is health food.", meaning: "National Carrot Cake Day. Carrot cake is the only dessert that gets away with calling itself a vegetable, and we all agree to the lie because the cream cheese frosting is worth it. It means you can be two things at once — healthy-ish and dessert.", anchorQuestion: "What lie do you tell yourself that is actually working?", whoIsThisSoul: ["What is your carrot cake — the thing you justify but love anyway?", "When did you last eat dessert without explaining it?"], adventures: ["Eat carrot cake today. The frosting is the point.", "Put a vegetable in a dessert and call it health food."] },
  "02-04": { title: "National Homemade Soup Day", tagline: "Soup is a hug with a spoon.", meaning: "National Homemade Soup Day. Homemade soup is the only food that gets better the longer it sits, which is the opposite of most things in life. It means slow food is not wasted time — it is the whole point. The pot does the work.", anchorQuestion: "What in your life gets better the longer it sits?", whoIsThisSoul: ["What soup are you — hearty, spicy, or the weird one nobody orders?", "Who taught you to cook, and what did they teach you besides recipes?"], adventures: ["Make soup today. From scratch if you can, can if you cannot.", "Share a bowl with someone. Soup is meant to be shared."] },
  "02-05": { title: "World Nutella Day", tagline: "Chocolate you can eat with a spoon. Legally.", meaning: "World Nutella Day. A hazelnut spread that became a global religion, with fans who treat it like a personality. It means joy does not have to be complicated — sometimes it comes in a jar with a spoon.", anchorQuestion: "What simple pleasure do you treat like a religion?", whoIsThisSoul: ["What is your Nutella — the thing you would eat straight from the jar?", "When did you last enjoy something without optimizing it?"], adventures: ["Eat Nutella today. Spoon optional, encouraged.", "Put it on something unexpected. Crepe, toast, finger — all valid."] },
  "02-06": { title: "National Chopsticks Day", tagline: "Two sticks. Infinite food. Zero forks.", meaning: "National Chopsticks Day. Two sticks have fed billions of people for thousands of years, and most of us still cannot use them without dropping everything. It means skill is just practice wearing a fancy outfit. Keep dropping the sushi.", anchorQuestion: "What skill do you still fumble that everyone else makes look easy?", whoIsThisSoul: ["What would you eat with chopsticks that you normally eat with a fork?", "When did you last feel clumsy in public and survive it?"], adventures: ["Eat a meal with chopsticks today. Dropping food is part of the holiday.", "Learn one chopstick fact and tell someone."] },
  "02-07": { title: "National Send a Card to a Friend Day", tagline: "A card in the mail beats a text in the void.", meaning: "National Send a Card to a Friend Day. A physical card is the only message that cannot be swiped away, muted, or lost in a notification pile. It means someone sat down, picked a card, wrote in it, and mailed it — to you. That is a whole love language.", anchorQuestion: "Who would light up at getting a card from you?", whoIsThisSoul: ["What would you write in a card if you knew it would be kept forever?", "When did you last get real mail that was not a bill?"], adventures: ["Send a card to a friend today. Handwritten beats perfect.", "If you cannot mail one, hand-deliver it. The awkwardness is the charm."] },
  "02-08": { title: "National Kite Flying Day", tagline: "A kite is just a dream on a string.", meaning: "National Kite Flying Day. A kite is a piece of paper and string that argues with gravity and wins — as long as you keep running. It means some things only fly if you keep moving. Stop running and the kite falls.", anchorQuestion: "What in your life only flies if you keep moving?", whoIsThisSoul: ["What string are you still holding onto?", "When did you last feel the wind catch something you made?"], adventures: ["Fly a kite today, or watch one fly.", "If there is no wind, make a paper kite and hang it where you can see it."] },
  "02-09": { title: "National Pizza Day", tagline: "Pizza is the answer. What was the question?", meaning: "National Pizza Day. Pizza is the only food that ends arguments, starts parties, and shows up at every major life event. It means some things are universally loved for a reason — and the reason is cheese, crust, and zero pretension.", anchorQuestion: "What is your pizza order, and what does it say about you?", whoIsThisSoul: ["What is your pizza — the thing everyone loves that you secretly think is overrated?", "When did pizza save a bad day?"], adventures: ["Eat pizza today. Your usual order, no experimenting required.", "Try one topping you have never had. Pineapple counts."] },
  "02-10": { title: "National Umbrella Day", tagline: "Rain happens. Be the person with the umbrella.", meaning: "National Umbrella Day. An umbrella is the only invention that lets you walk through a storm and stay dry while doing it. It means preparation is not pessimism — it is kindness to your future self. Check the forecast. Bring the umbrella.", anchorQuestion: "What storm are you walking through without an umbrella?", whoIsThisSoul: ["Who has been your umbrella — the person who kept you dry?", "What would you do if you knew it was going to rain and you were ready?"], adventures: ["Check the weather today, even if you do not go outside.", "Be someone's umbrella — cover for a friend, literally or otherwise."] },
  "02-11": { title: "National Make a Friend Day", tagline: "Say hi to a stranger. It might stick.", meaning: "National Make a Friend Day. Adult friendship is weird — you cannot just walk up to someone on a playground and declare them your best friend anymore. Or can you? It means the rules for making friends as an adult are mostly imaginary. Say hi.", anchorQuestion: "Who would you befriend if the rules were playground rules?", whoIsThisSoul: ["When did you last make a new friend as an adult?", "What is stopping you from saying hi?"], adventures: ["Say hi to someone new today. One sentence counts.", "Message someone you have been meaning to reconnect with."] },
  "02-12": { title: "National Plum Pudding Day", tagline: "A pudding with a plot twist.", meaning: "National Plum Pudding Day. Plum pudding has no plums, is not really a pudding by modern standards, and is traditionally set on fire — which is the most honest description of British dessert ever. It means names lie, traditions are weird, and fire makes everything better.", anchorQuestion: "What in your life is misnamed?", whoIsThisSoul: ["What tradition of yours would look insane to an outsider?", "If you set one thing on fire today (safely), what would it be?"], adventures: ["Eat a steamed pudding today, or any dessert you have never tried.", "Look up how plum pudding is made. The fire part is real."] },
  "02-13": { title: "National Galentine's Day", tagline: "Ladies celebrating ladies. Waffles mandatory.", meaning: "National Galentine's Day. Invented by a TV show, adopted by every woman who ever needed a day that was about her friends instead of her relationship status. It means female friendship is not the consolation prize — it is the main event. Waffles are the official food.", anchorQuestion: "Who are your galentines — the women who hold you up?", whoIsThisSoul: ["What does your female friendship look like when nobody is performing?", "When did your friends last get the celebration instead of a partner?"], adventures: ["Celebrate a woman friend today. Text, call, or waffles.", "Tell a woman in your life one specific thing you admire about her."] },
  "02-14": { title: "Valentine's Day", tagline: "Love, but make it loud.", meaning: "Valentine's Day. The most commercialized love day on the calendar, and still — underneath the candy hearts — it is a day that says love out loud. It means saying the thing matters more than the gift. The card is the point.", anchorQuestion: "Who do you love that has not heard it lately?", whoIsThisSoul: ["What does love look like when it is not performing for a holiday?", "What would you say if Valentine's Day did not exist?"], adventures: ["Tell someone you love them today. Specifics beat generics.", "Do one loving thing that costs nothing."] },
  "02-15": { title: "National Singles Awareness Day", tagline: "Single, aware, and unbothered.", meaning: "National Singles Awareness Day. The day after Valentine's, for everyone who watched the couples' parade and thought: good for them, now where is my table for one? It means being single is not a waiting room. It is a life.", anchorQuestion: "What does your single life give you that coupled life never could?", whoIsThisSoul: ["What part of being single do you actually love?", "Who told you single was a problem to solve?"], adventures: ["Take yourself out today. Table for one, best seat in the house.", "Do one thing alone that couples usually do together. Enjoy it more."] },
  "02-16": { title: "National Do a Grouch a Favor Day", tagline: "Be nice to the grumpiest person you know.", meaning: "National Do a Grouch a Favor Day. Everybody knows a grouch, and every grouch is one unexpected kindness away from melting — or at least grumbling slightly less. It means the grumpiest people are often the ones who need a favor most.", anchorQuestion: "Who is the grouch in your life, and what do they actually need?", whoIsThisSoul: ["When are you the grouch, and what favor would fix it?", "What would it take for someone to melt your grump?"], adventures: ["Do a favor for a grouch today. Do not expect thanks.", "If you are the grouch, let someone do a favor for you."] },
  "02-17": { title: "National Random Acts of Kindness Day", tagline: "Be kind. No reason. No receipt.", meaning: "National Random Acts of Kindness Day. Kindness without a reason is the only kind that counts, because the second it has a reason it is strategy. It means one small, anonymous good deed can reroute a stranger's whole day.", anchorQuestion: "What kindness could you do today that nobody would ever know about?", whoIsThisSoul: ["When did a stranger's kindness change your day?", "What would you do if kindness were the only currency?"], adventures: ["Do one random act of kindness today. Do not tell anyone.", "Pay for a stranger's coffee, hold a door, leave a kind note."] },
  "02-18": { title: "National Drink Wine Day", tagline: "It is wine o'clock somewhere. Probably here.", meaning: "National Drink Wine Day. Wine is grapes that went through a transformation and came out better — a career path, honestly. It means some days the answer is a glass, a porch, and no agenda. Sip slowly.", anchorQuestion: "What are you celebrating that does not need a reason?", whoIsThisSoul: ["What is your wine — the thing that gets better with age?", "When did you last sip something slowly on purpose?"], adventures: ["Drink wine today, if you drink. Grape juice counts. No judgment either way.", "Pair it with something good — cheese, chocolate, or a long conversation."] },
  "02-19": { title: "National Chocolate Mint Day", tagline: "Mint plus chocolate. The debate ends here.", meaning: "National Chocolate Mint Day. Chocolate and mint are the most divisive duo in candy — people either love the combo or think it tastes like toothpaste. It means some flavors, like some people, are polarizing on purpose. Pick a side.", anchorQuestion: "Chocolate mint: genius or toothpaste? Defend your answer.", whoIsThisSoul: ["What do you love that other people think is weird?", "When did you last change your mind about a flavor — or a person?"], adventures: ["Eat something chocolate-mint today. Commit to an opinion.", "Argue about it with someone. Friendly argument only."] },
  "02-20": { title: "National Love Your Pet Day", tagline: "They love you more. It is not close.", meaning: "National Love Your Pet Day. Your pet loves you without conditions, without a performance review, without caring what you look like at 6 AM. It means the purest love in your house has four legs and zero judgment. Return it.", anchorQuestion: "What does your pet love about you that people miss?", whoIsThisSoul: ["If your pet could talk, what would it say about your week?", "When did your pet last make a bad day better just by existing?"], adventures: ["Love your pet extra today. Treat, walk, belly rub — the works.", "Take a photo of your pet being ridiculous. Share it."] },
  "02-21": { title: "National Sticky Bun Day", tagline: "Sticky fingers. Zero regrets.", meaning: "National Sticky Bun Day. A sticky bun is a cinnamon roll that stopped pretending to be neat. It means some foods — and some days — are supposed to be messy. Lick your fingers. That is the whole etiquette.", anchorQuestion: "What messy pleasure have you been avoiding to stay neat?", whoIsThisSoul: ["What is your sticky bun — the thing you love that makes a mess?", "When did you last eat something with your hands and not care?"], adventures: ["Eat a sticky bun today. Fingers will be sticky. That is correct.", "Let one thing be messy today without cleaning it up immediately."] },
  "02-22": { title: "National Margarita Day", tagline: "Salt the rim. Lime the day.", meaning: "National Margarita Day. A margarita is a vacation in a glass with salt on the rim — the only cocktail that comes with its own tiny beach. It means sometimes the vacation is not a trip. It is a glass, a lime, and twenty minutes of pretending.", anchorQuestion: "Where would your margarita take you if it could?", whoIsThisSoul: ["What is your margarita — the small thing that feels like a vacation?", "When did you last salt the rim of your own day?"], adventures: ["Drink a margarita today, if you drink. Virgin counts. Lime mandatory.", "Put your feet up for twenty minutes. Vacation rules apply."] },
  "02-23": { title: "National Banana Bread Day", tagline: "The bananas were going bad. Now they are bread.", meaning: "National Banana Bread Day. Banana bread is what happens when you refuse to throw away the brown bananas — transformation born of stubbornness. It means the thing you thought was ruined might just be bread waiting to happen.", anchorQuestion: "What brown banana in your life is actually bread?", whoIsThisSoul: ["What have you saved from the trash that turned out great?", "When did you last turn a loss into loaf?"], adventures: ["Bake banana bread today. Brown bananas required.", "Give a slice to someone. Banana bread is a gift, not a snack."] },
  "02-24": { title: "National Tortilla Chip Day", tagline: "The chip is just the vehicle. The dip is the destination.", meaning: "National Tortilla Chip Day. A tortilla chip is a triangle that exists to carry better things to your mouth — salsa, queso, guac, all of it. It means the vehicle matters less than the cargo. The chip is humble. The dip is the point.", anchorQuestion: "What is your dip — the thing that makes the ordinary vehicle worth it?", whoIsThisSoul: ["Are you the chip or the dip in your friendships?", "What would you scoop up if the bowl were endless?"], adventures: ["Eat tortilla chips and dip today. The good dip, not the sad jar.", "Make a dip from scratch. Guac counts. Queso counts double."] },
  "02-25": { title: "National Clam Chowder Day", tagline: "Creamy. Chunky. Coastal. Controversial.", meaning: "National Clam Chowder Day. Clam chowder starts the oldest food fight in America: New England creamy versus Manhattan tomato, and everybody has an opinion. It means food is never just food — it is identity, region, and a hill to die on.", anchorQuestion: "Creamy or tomato? Pick a side and defend it.", whoIsThisSoul: ["What food fight would you actually show up for?", "What does your chowder say about where you are from?"], adventures: ["Eat clam chowder today. Pick your side.", "Ask someone their chowder stance. The argument is the holiday."] },
  "02-26": { title: "National Tell a Fairy Tale Day", tagline: "Once upon a time, you told the truth with magic.", meaning: "National Tell a Fairy Tale Day. Fairy tales are the oldest way humans told the truth — wrapped in wolves, witches, and warnings. It means every story you tell about your life is a fairy tale with the magic left in or taken out. Choose wisely.", anchorQuestion: "What fairy tale is your life actually telling?", whoIsThisSoul: ["Are you the hero, the villain, or the wolf in your own story?", "What would your fairy tale be called?"], adventures: ["Tell a fairy tale today — to a kid, a friend, or yourself.", "Rewrite one fairy tale with you as the main character."] },
  "02-27": { title: "National Retro Day", tagline: "Everything old is cool again. Especially you.", meaning: "National Retro Day. Retro is just nostalgia with better lighting — everything old comes back, from vinyl to mom jeans to the music you swore you outgrew. It means the past is not gone. It is just waiting for its comeback tour.", anchorQuestion: "What from your past deserves a comeback?", whoIsThisSoul: ["What era would you time-travel to for one day?", "What retro thing about you never actually went out of style?"], adventures: ["Wear something retro today. Or listen to a song from your past on repeat.", "Dig up an old photo and show someone. Tell the story."] },
  "02-28": { title: "National Tooth Fairy Day", tagline: "Check under the pillow. The fairy was here.", meaning: "National Tooth Fairy Day. The Tooth Fairy is the only economy where losing a body part pays cash, and kids accept it without a single question. It means magic is just a story adults agree to keep telling — and the story is worth more than the coin.", anchorQuestion: "What magic did you believe in that you miss?", whoIsThisSoul: ["What would you leave under your pillow for the fairy today?", "When did you stop believing — and what would it take to start again?"], adventures: ["Leave a surprise under someone's pillow today.", "Tell a kid the Tooth Fairy story like you still believe it."] },
  "02-29": { title: "Leap Day", tagline: "A free day. The calendar glitched in your favor.", meaning: "Leap Day. Once every four years the calendar hands you a free day that does not exist the rest of the time. It means time is not as fixed as it pretends to be — sometimes you get an extra day, no strings attached. Spend it like it is stolen.", anchorQuestion: "What would you do with a day that does not officially exist?", whoIsThisSoul: ["If you could leap over one day of your life, which one?", "What would you do with time that nobody is counting?"], adventures: ["Do something today that you would never do on a real day.", "Tell someone: happy Leap Day. You get to say it once every four years."] },
  // ---- March ----
  "03-01": { title: "National Peanut Butter Lovers Day", tagline: "Creamy or crunchy? There is no wrong answer. There is a war.", meaning: "National Peanut Butter Lovers Day. Peanut butter is the only food that works for breakfast, lunch, dinner, and a spoon at midnight. It means the simplest things are the most loyal. The jar is always there.", anchorQuestion: "Creamy or crunchy? This matters more than you think.", whoIsThisSoul: ["What is your peanut butter — the simple thing you never get tired of?", "When did you last eat something straight from the jar?"], adventures: ["Eat peanut butter today. Spoon, sandwich, or straight from the jar.", "Try it on something weird. Pickles count. Bananas count double."] },
  "03-02": { title: "National Old Stuff Day", tagline: "Old stuff. New appreciation. Same junk drawer.", meaning: "National Old Stuff Day. Today is for the stuff in the back of the closet — the things you kept for no reason that turned out to be the reason. It means old does not mean useless. It means proven.", anchorQuestion: "What old thing of yours deserves more respect?", whoIsThisSoul: ["What is the oldest thing you own, and why did you keep it?", "What old version of you would you bring back for one day?"], adventures: ["Dig out something old today and use it.", "Tell someone the story of your oldest possession."] },
  "03-03": { title: "National I Want You to Be Happy Day", tagline: "Today is about someone else's happiness. Weird, right?", meaning: "National I Want You to Be Happy Day. A holiday whose entire assignment is wanting someone else to be happy — no catch, no reciprocity, no strings. It means happiness is not a zero-sum game. Their joy does not cost you yours.", anchorQuestion: "Whose happiness would you choose today, no strings attached?", whoIsThisSoul: ["When did someone else's happiness make you happy?", "What would it take for you to want someone happy who hurt you?"], adventures: ["Do one thing today purely to make someone else happy.", "Tell someone: I want you to be happy. Mean it."] },
  "03-04": { title: "National Snack Day", tagline: "Snack like nobody is watching the pantry.", meaning: "National Snack Day. Snacks are the meals that refuse to be serious — eaten standing up, straight from the bag, no plate required. It means not every bite needs a ceremony. Sometimes food is just a handful of joy.", anchorQuestion: "What is your perfect snack, no judgment?", whoIsThisSoul: ["What do you snack on when nobody is watching?", "When did a snack save your day?"], adventures: ["Eat your favorite snack today. Standing up counts. Bag counts.", "Try a snack you have never had."] },
  "03-05": { title: "National Cheese Doodle Day", tagline: "Orange fingers. Zero dignity. Full commitment.", meaning: "National Cheese Doodle Day. Cheese doodles are engineered to stain your fingers orange, and we eat them anyway — because some foods demand full commitment. It means dignity is overrated when the snack is this good.", anchorQuestion: "What do you love that leaves evidence on your fingers?", whoIsThisSoul: ["When did you last eat something that stained you and not care?", "What is your cheese doodle — the snack you would defend to anyone?"], adventures: ["Eat cheese doodles today. Orange fingers mandatory.", "Lick the cheese dust off your fingers. That is the ritual."] },
  "03-06": { title: "National Oreo Cookie Day", tagline: "Twist. Lick. Dunk. In that order.", meaning: "National Oreo Cookie Day. The Oreo has one correct procedure — twist, lick, dunk — and millions of people have strong opinions about skipping steps. It means rituals matter, even silly ones. Especially silly ones.", anchorQuestion: "What is your Oreo procedure?", whoIsThisSoul: ["What small ritual of yours would look insane to an outsider?", "When did a cookie last settle an argument?"], adventures: ["Eat an Oreo today. Follow the procedure. Or break it on purpose.", "Dunk one in milk. Watch it. That is meditation."] },
  "03-07": { title: "National Cereal Day", tagline: "Cereal is soup for people who gave up.", meaning: "National Cereal Day. Cereal is breakfast, dinner, midnight snack, and emergency meal — the most versatile food ever poured from a box. It means some days the whole plan is milk plus crunch, and that is enough.", anchorQuestion: "What is your cereal — the thing that works for every meal?", whoIsThisSoul: ["What did you eat for dinner that was actually breakfast?", "When did cereal save you from cooking?"], adventures: ["Eat cereal today. Any time. Any bowl. No rules.", "Try a cereal you have never had. Or the one you loved as a kid."] },
  "03-08": { title: "International Women's Day", tagline: "Women. The whole day. The whole point.", meaning: "International Women's Day. A day that started as a protest and became a celebration — because women had to fight for the day itself. It means half the world runs on work that gets called invisible. Today, see it.", anchorQuestion: "Which woman's work do you benefit from without noticing?", whoIsThisSoul: ["What would the world look like if women's work were priced fairly?", "Which woman in your life has never been properly thanked?"], adventures: ["Thank a woman today. Specifics, not generics.", "Learn about one woman from history you have never heard of."] },
  "03-09": { title: "National Meatball Day", tagline: "Round. Saucy. Perfect. No notes.", meaning: "National Meatball Day. A meatball is just ground meat that decided to be a sphere, and somehow that made it better. It means shape matters. The same ingredients, rolled into a ball, become a celebration.", anchorQuestion: "What in your life needs to be rolled into a ball and celebrated?", whoIsThisSoul: ["What is your meatball — the thing that is better than the sum of its parts?", "Spaghetti or sub? Pick a side. This is important."], adventures: ["Eat meatballs today. Any style. All styles.", "Roll something into a ball — meat, dough, or a plan — and commit to it."] },
  "03-10": { title: "National Mario Day", tagline: "Mar 10. MAR10. Get it? The plumber gets it.", meaning: "National Mario Day. March 10 spells MAR10, and that is the entire reason this holiday exists — a pun that became a celebration. It means joy does not need a deep reason. Sometimes a date looks like a name, and that is enough.", anchorQuestion: "What pun in your life deserves a holiday?", whoIsThisSoul: ["Are you Mario or Luigi today?", "What game would you play if you could live inside it?"], adventures: ["Play a Mario game today, or watch someone play one.", "Jump on an imaginary Goomba. You know you want to."] },
  "03-11": { title: "National Worship of Tools Day", tagline: "Tools. The things that fix things. Including you.", meaning: "National Worship of Tools Day. Tools are the only objects that exist purely to make you more capable — a hammer is a longer arm, a wrench is a stronger hand. It means you are not supposed to do everything barehanded. Use the tool.", anchorQuestion: "What tool do you refuse to use that would make your life easier?", whoIsThisSoul: ["What is your favorite tool — literal or metaphorical?", "When did the right tool change everything?"], adventures: ["Use a tool today. A real one. Fix something small.", "Sharpen, clean, or organize one tool you own."] },
  "03-12": { title: "National Plant a Flower Day", tagline: "Plant it now. Thank yourself in spring.", meaning: "National Plant a Flower Day. Planting a flower is a bet on a future you cannot see yet — you put a bulb in cold dirt and trust it. It means hope is an action, not a feeling. The flower is the receipt.", anchorQuestion: "What are you planting now that you will not see bloom for months?", whoIsThisSoul: ["What flower would you be, and why?", "When did you last plant something and forget it, then get surprised?"], adventures: ["Plant a flower today. Pot counts. Windowsill counts.", "If you cannot plant, buy flowers for someone. Same energy."] },
  "03-13": { title: "National Good Samaritan Day", tagline: "Help a stranger. Do not get caught doing it.", meaning: "National Good Samaritan Day. The Good Samaritan is the oldest story about helping someone who is not your people, for no reason, at personal cost. It means kindness does not check IDs. The stranger is the neighbor.", anchorQuestion: "Who is your neighbor that you have been walking past?", whoIsThisSoul: ["When did a stranger help you and you never got to thank them?", "What would you do for a stranger that you would not do for a friend?"], adventures: ["Help a stranger today. Small counts. Holding a door counts.", "Do it without telling anyone. The secret is the point."] },
  "03-14": { title: "National Pi Day", tagline: "3.14. Pie. Pi. The math checks out.", meaning: "National Pi Day. March 14 is 3.14, and pi is the number that never ends and never repeats — like the arguments about whether pie or cake is better. It means some things go on forever, and that is beautiful, not broken.", anchorQuestion: "What in your life goes on forever without repeating?", whoIsThisSoul: ["Are you a pie person or a cake person? Defend it.", "What irrational thing about you never ends?"], adventures: ["Eat pie today. Any pie. Pi-themed bonus points.", "Memorize one more digit of pi than you knew yesterday."] },
  "03-15": { title: "National Napping Day", tagline: "Nap like the Romans. The Ides demand it.", meaning: "National Napping Day. The day after the clocks jump forward, when everyone is running on an hour less sleep and pretending they are fine. It means the nap is not laziness — it is recovery from a theft. The clock stole an hour. Take it back.", anchorQuestion: "When did you last nap without guilt?", whoIsThisSoul: ["What would you dream about if you napped right now?", "Who stole your hour, and how are you taking it back?"], adventures: ["Nap today. Twenty minutes. Alarm optional, guilt forbidden.", "If you cannot nap, lie down for ten minutes and call it a nap."] },
  "03-16": { title: "National Panda Day", tagline: "Pandas. Round. Lazy. Perfect. No notes.", meaning: "National Panda Day. Pandas eat bamboo, roll down hills, and are terrible at survival — and we love them anyway. It means you do not have to be efficient to be beloved. Sometimes the whole strategy is: be round, eat snacks, roll.", anchorQuestion: "What is your panda move — the lazy thing you are great at?", whoIsThisSoul: ["If you were a panda, what would your day look like?", "What would you do if survival was not the assignment?"], adventures: ["Watch a panda video today. The rolling ones are the best.", "Be a panda for an hour: eat, lie down, roll."] },
  "03-17": { title: "St. Patrick's Day", tagline: "Everyone is Irish today. Wear green or pay the price.", meaning: "St. Patrick's Day. A saint's day that became a global excuse to wear green, drink too much, and claim Irish ancestry you do not have. It means identity is sometimes just a color and a party. Pinch those who forgot.", anchorQuestion: "What are you pretending to be today?", whoIsThisSoul: ["What does green mean to you — luck, envy, or just a shirt?", "When did you last pinch someone? For the holiday, obviously."], adventures: ["Wear green today. Or risk the pinch.", "Eat or drink something green. Clover optional."] },
  "03-18": { title: "National Awkward Moments Day", tagline: "That thing you said in 2019. It is still funny.", meaning: "National Awkward Moments Day. Everybody has a highlight reel of awkward moments that play at 3 AM — the wrong name, the wave at a stranger, the reply-all. It means awkward is not a bug. It is the proof you showed up and tried.", anchorQuestion: "What is your most iconic awkward moment?", whoIsThisSoul: ["What awkward thing of yours still makes you cringe — and laugh?", "When did awkward turn out to be charming?"], adventures: ["Tell someone your most awkward story today. Own it.", "Forgive yourself for one awkward moment. It was not that bad."] },
  "03-19": { title: "National Let's Laugh Day", tagline: "Laugh. Loud. In public. Scare the pigeons.", meaning: "National Let's Laugh Day. Laughing is the only exercise that works your face, your belly, and your mood at the same time — and it is free. It means laughter is not a reaction. It is a decision. Make it.", anchorQuestion: "What makes you laugh every single time?", whoIsThisSoul: ["When did you last laugh so hard you could not breathe?", "What is funny about your life right now that you are missing?"], adventures: ["Laugh today. Real laugh, not polite laugh.", "Watch or read something that makes you laugh out loud."] },
  "03-20": { title: "National Ravioli Day", tagline: "Little pasta pillows full of joy.", meaning: "National Ravioli Day. Ravioli is pasta that hides a surprise inside — a little pocket of cheese, meat, or mystery. It means the best things have a filling. The outside is just the wrapper.", anchorQuestion: "What is inside you that nobody can see from the outside?", whoIsThisSoul: ["What is your filling — the surprise inside your wrapper?", "When did you last bite into something and get surprised?"], adventures: ["Eat ravioli today. Any filling. All fillings.", "Hide a surprise inside something ordinary today."] },
  "03-21": { title: "National Fragrance Day", tagline: "Smell like the version of you you want to be.", meaning: "National Fragrance Day. Smell is the only sense that goes straight to memory — one whiff and you are twelve years old at your grandmother's house. It means scent is a time machine you wear on your skin.", anchorQuestion: "What smell takes you straight back in time?", whoIsThisSoul: ["What would your signature scent be if you had one?", "Who do you still remember by their smell?"], adventures: ["Wear a fragrance today. Or notice one.", "Smell something on purpose — coffee, rain, a book. Pay attention."] },
  "03-22": { title: "National Goof Off Day", tagline: "Goof off. It is literally the assignment.", meaning: "National Goof Off Day. Goofing off is not the opposite of working — it is the pressure valve that keeps working possible. It means the day has one task: waste time joyfully. The goofing is the work.", anchorQuestion: "What does goofing off look like for you at your best?", whoIsThisSoul: ["When did goofing off lead to your best idea?", "What would you do if goofing off were your job?"], adventures: ["Goof off today. Deliberately. With witnesses.", "Cancel one productive thing and replace it with something silly."] },
  "03-23": { title: "National Puppy Day", tagline: "Puppies. The whole day. That is the post.", meaning: "National Puppy Day. Puppies are chaos with fur — they chew your shoes, pee on the floor, and look at you like you are the whole world. It means love does not require good behavior. It just requires showing up with a wag.", anchorQuestion: "What puppy energy do you need today?", whoIsThisSoul: ["If you were a puppy, what kind would you be?", "What do puppies know that adults forgot?"], adventures: ["Pet a puppy today. Or watch puppy videos. Both count.", "Be a puppy for ten minutes: excited, wiggly, zero dignity."] },
  "03-24": { title: "National Cocktail Day", tagline: "Shaken, stirred, or straight from the can.", meaning: "National Cocktail Day. A cocktail is just juice, ice, and a decision — but the decision is what makes it a cocktail. It means presentation is not shallow. The glass, the garnish, the ritual — that is the drink.", anchorQuestion: "What is your cocktail — the drink that is also a mood?", whoIsThisSoul: ["What would you mix together to make the cocktail of your life?", "When did a drink last mark an occasion properly?"], adventures: ["Drink a cocktail today, if you drink. Mocktail counts. Garnish mandatory.", "Learn to make one cocktail properly. Or invent one."] },
  "03-25": { title: "National Tolkien Reading Day", tagline: "Not all those who wander are lost. Some are reading.", meaning: "National Tolkien Reading Day. Tolkien built a whole world because he wanted better stories — languages, maps, histories, all of it. It means worldbuilding is not escapism. It is authorship. Build your world.", anchorQuestion: "What world would you build if you had Tolkien's patience?", whoIsThisSoul: ["Are you Frodo, Sam, Gandalf, or Gollum today?", "What is your precious — the thing you would carry to a volcano?"], adventures: ["Read Tolkien today. Even one page. Even the poems.", "Draw a map of your own world. It does not have to make sense."] },
  "03-26": { title: "National Spinach Day", tagline: "Popeye was right. Eat the spinach.", meaning: "National Spinach Day. Spinach is the vegetable that made a cartoon sailor strong, and somehow that was enough to get kids to eat it. It means the right story can make anything appealing — even leaves.", anchorQuestion: "What healthy thing do you avoid because the story is boring?", whoIsThisSoul: ["What is your spinach — the thing that is good for you that you resist?", "When did a story change what you were willing to eat — literally or otherwise?"], adventures: ["Eat spinach today. Cooked, raw, or blended into something.", "Tell yourself the Popeye story while you eat it. It helps."] },
  "03-27": { title: "National Scribble Day", tagline: "Scribble like nobody is grading the art.", meaning: "National Scribble Day. Scribbling is drawing without the pressure — no lines to stay inside, no picture to produce, just the hand moving. It means art does not need a product. The scribble is the product.", anchorQuestion: "What would you draw if nobody ever saw it?", whoIsThisSoul: ["When did you stop scribbling and start trying to draw well?", "What does your scribble look like when you are not thinking?"], adventures: ["Scribble today. Paper, napkin, or margins. No purpose required.", "Scribble over something you were trying to make perfect. Free it."] },
  "03-28": { title: "National Something on a Stick Day", tagline: "If it is on a stick, it is a party.", meaning: "National Something on a Stick Day. Food on a stick is fair food, party food, food that does not need a plate or a plan. It means anything becomes fun if you put it on a stick. The stick is the celebration.", anchorQuestion: "What would you put on a stick if you could put anything on a stick?", whoIsThisSoul: ["What in your life needs a stick — a handle, a grip, a way to hold it?", "When did you last eat fair food?"], adventures: ["Eat something on a stick today. Kebab, corndog, popsicle — all valid.", "Put something on a stick that has no business being on a stick."] },
  "03-29": { title: "National Mom and Pop Business Owners Day", tagline: "Shop small. The owners are right there.", meaning: "National Mom and Pop Business Owners Day. Mom-and-pop shops are the only businesses where the owner is also the cashier, the janitor, and the person who knows your order. It means small business is not a category — it is a person.", anchorQuestion: "What small business in your life do you love?", whoIsThisSoul: ["What would you sell if you ran a mom-and-pop shop?", "When did a small business treat you like a regular?"], adventures: ["Shop at a small business today. Say hi to the owner.", "Leave a review for a small business you love."] },
  "03-30": { title: "National Take a Walk in the Park Day", tagline: "The park is right there. Go.", meaning: "National Take a Walk in the Park Day. A walk in the park is the cheapest therapy ever prescribed — trees, air, and no destination. It means you do not need a trail or a plan. The park is enough.", anchorQuestion: "When did you last walk in a park with no destination?", whoIsThisSoul: ["What does the park give you that the gym never could?", "What would you notice if you walked slower?"], adventures: ["Walk in a park today. No fitness goal. Just walk.", "Sit on a bench for five minutes. That counts as a walk."] },
  "03-31": { title: "National Crayon Day", tagline: "Color outside the lines. The lines are fake.", meaning: "National Crayon Day. Crayons are the first art supply most of us ever held, and the only one that never asked us to be good. It means color does not need permission. The lines were always fake.", anchorQuestion: "What color would you be if you were a crayon?", whoIsThisSoul: ["When did you stop coloring outside the lines?", "What would you color if the lines did not matter?"], adventures: ["Color something today. Crayon preferred. Outside the lines required.", "Name a crayon color after yourself."] },
  // ---- April ----
  "04-01": { title: "April Fools' Day", tagline: "Trust nothing. Laugh at everything.", meaning: "April Fools' Day. The one day a year when lying is a sport and everyone agrees to play. It means pranks are just jokes with a setup — and the best prank is the one where everyone laughs, including the target.", anchorQuestion: "What is the best prank you ever pulled — or fell for?", whoIsThisSoul: ["When did a joke go too far, and what did it teach you?", "What would you prank if you knew everyone would laugh?"], adventures: ["Pull a harmless prank today. Harmless is the whole rule.", "Be the target gracefully. Laugh first."] },
  "04-02": { title: "National Peanut Butter and Jelly Day", tagline: "The greatest sandwich ever made. Fight me.", meaning: "National Peanut Butter and Jelly Day. PB&J is the only sandwich that works for every age, every budget, and every mood. It means the greatest things are not complicated. They are two spreads and bread.", anchorQuestion: "What is your PB&J ratio — more peanut butter or more jelly?", whoIsThisSoul: ["What is your PB&J — the simple combo that never fails?", "When did a sandwich last fix your day?"], adventures: ["Eat a PB&J today. Crust on or off — your call.", "Cut it diagonally. It tastes better. Science cannot explain it."] },
  "04-03": { title: "National Find a Rainbow Day", tagline: "Look for the rainbow. Be the rainbow.", meaning: "National Find a Rainbow Day. Rainbows are the only weather that is also a promise — light and water agreeing to make something beautiful. It means after the rain, there is not just sunshine. There is color.", anchorQuestion: "What rainbow are you looking for right now?", whoIsThisSoul: ["When did you last see a rainbow and actually stop?", "What colors would your rainbow have if you picked them?"], adventures: ["Look for a rainbow today — real, painted, or in a puddle of oil.", "If there is no rainbow, make one. Prism, hose, or imagination."] },
  "04-04": { title: "National Vitamin C Day", tagline: "Orange you glad it is Vitamin C Day?", meaning: "National Vitamin C Day. Vitamin C is the nutrient that keeps you from getting scurvy, which is a pirate disease — so technically this is pirate prevention day. It means the small daily things keep you from falling apart.", anchorQuestion: "What small daily thing keeps you from falling apart?", whoIsThisSoul: ["What is your Vitamin C — the thing you need a little of every day?", "When did you last feel scurvy of the soul?"], adventures: ["Eat something with Vitamin C today. Orange, pepper, or a supplement.", "Take your vitamins. The gummy ones count."] },
  "04-05": { title: "National Deep Dish Pizza Day", tagline: "Pizza, but it is a casserole with confidence.", meaning: "National Deep Dish Pizza Day. Deep dish is pizza that refused to be flat — it built walls, piled on cheese, and became a casserole with a crust. It means some things get better when you go deeper. Thin crust is a choice. Deep dish is a commitment.", anchorQuestion: "Deep dish or thin crust? This defines you.", whoIsThisSoul: ["What in your life needs to go deeper?", "When did you last commit to the deep version of something?"], adventures: ["Eat deep dish pizza today. Fork and knife allowed.", "Go deep on something today — one topic, one conversation, one slice."] },
  "04-06": { title: "National Caramel Popcorn Day", tagline: "Sweet. Salty. Stuck to your teeth. Perfect.", meaning: "National Caramel Popcorn Day. Caramel popcorn is regular popcorn that got dressed up and decided to be dessert. It means a little sweetness changes everything — same corn, different life.", anchorQuestion: "What would a little sweetness change in your day?", whoIsThisSoul: ["What is your caramel — the sweet coating on something ordinary?", "When did something sweet get stuck to you in a good way?"], adventures: ["Eat caramel popcorn today. Teeth will be sticky. Worth it.", "Caramelize one thing today — popcorn, onions, or a mood."] },
  "04-07": { title: "National Beer Day", tagline: "Cheers to the beverage that built civilizations.", meaning: "National Beer Day. Beer is one of the oldest drinks humans ever made — older than bread, older than most governments. It means gathering around a drink is one of the oldest human habits there is. Cheers to that.", anchorQuestion: "What are you toasting today?", whoIsThisSoul: ["What does beer mean to you — social, solo, or skip?", "When did a drink last mark a real moment?"], adventures: ["Drink a beer today, if you drink. Cheers someone.", "If you do not drink, toast with whatever you have. The toast is the point."] },
  "04-08": { title: "National All Is Ours Day", tagline: "Everything is yours today. All of it.", meaning: "National All Is Ours Day. A strange little holiday about appreciating what you already have — the whole world, shared. It means the things you take for granted are the things someone else is praying for. All of it is ours.", anchorQuestion: "What do you already have that you treat like it is not yours?", whoIsThisSoul: ["What would you claim if you believed it was all yours?", "When did you last feel like the world belonged to you?"], adventures: ["Claim one thing today as yours — a bench, a sunset, a moment.", "Share something you have with someone who does not. It is all ours."] },
  "04-09": { title: "National Unicorn Day", tagline: "Believe in the unicorn. Be the unicorn.", meaning: "National Unicorn Day. Unicorns are not real, and that has never stopped anyone from believing in them — because the belief is the point. It means some things are worth believing in precisely because they are impossible.", anchorQuestion: "What impossible thing do you believe in?", whoIsThisSoul: ["If you were a unicorn, what would your horn do?", "When did believing in something impossible save you?"], adventures: ["Wear something unicorn today. Horn optional, encouraged.", "Believe in one impossible thing before breakfast."] },
  "04-10": { title: "National Siblings Day", tagline: "The people who knew you before you were cool.", meaning: "National Siblings Day. Siblings are the only people who knew you before you had a brand — they saw the awkward years and stayed. It means family is not chosen, but the love is. Call your sibling.", anchorQuestion: "What do your siblings know about you that nobody else does?", whoIsThisSoul: ["Are you the oldest, middle, youngest, or only — and how does it show?", "What sibling story do you still tell at every gathering?"], adventures: ["Contact a sibling today. Text counts. Call is better.", "Tell a sibling story to someone who has never heard it."] },
  "04-11": { title: "National Pet Day", tagline: "Pets. The whole day. Again. They deserve it.", meaning: "National Pet Day. Pets do not know what day it is, and they do not care — they just know you came home. It means the love of a pet is the most reliable thing in most people's lives. Celebrate it like it matters, because it does.", anchorQuestion: "What has your pet taught you that no human could?", whoIsThisSoul: ["If your pet wrote your biography, what would the title be?", "When did your pet last know you were sad before you did?"], adventures: ["Celebrate your pet today. Extra treats, extra walk, extra love.", "Adopt, foster, or donate to a shelter if you can."] },
  "04-12": { title: "National Grilled Cheese Sandwich Day", tagline: "Bread. Cheese. Butter. Perfection.", meaning: "National Grilled Cheese Sandwich Day. A grilled cheese is three ingredients and one perfect idea — crispy outside, melted inside, no improvements needed. It means the best things are simple, and simple is not easy. The crust is the whole game.", anchorQuestion: "What is your grilled cheese — the simple thing you do perfectly?", whoIsThisSoul: ["What cheese would you be? Be honest.", "When did a grilled cheese last fix everything?"], adventures: ["Eat a grilled cheese today. Real butter. Real cheese.", "Try a fancy version — tomato, bacon, or three cheeses."] },
  "04-13": { title: "National Peach Cobbler Day", tagline: "Cobbler: the dessert that does not care about looks.", meaning: "National Peach Cobbler Day. Cobbler is the dessert that gave up on presentation and decided to just taste amazing — fruit, sugar, crust, done. It means ugly delicious beats pretty mediocre every time.", anchorQuestion: "What ugly delicious thing in your life deserves more credit?", whoIsThisSoul: ["What dessert would you be — cobbler, cake, or something fancy?", "When did you last choose taste over looks?"], adventures: ["Eat peach cobbler today. Ice cream on top is not optional.", "Make a cobbler. It is supposed to look messy."] },
  "04-14": { title: "National Pecan Day", tagline: "Pecans: the nut that knows it is fancy.", meaning: "National Pecan Day. Pecans are the only nut with a name that starts arguments about pronunciation — puh-KAHN versus PEE-can. It means even a nut can be a debate. Say it your way.", anchorQuestion: "Puh-KAHN or PEE-can? There is a right answer and it is yours.", whoIsThisSoul: ["What do you pronounce differently than everyone around you?", "What small thing do you have strong opinions about?"], adventures: ["Eat pecans today. Pie, praline, or straight from the bag.", "Start a pecan pronunciation argument. See what happens."] },
  "04-15": { title: "National Tax Day", tagline: "The taxman cometh. So does the refund.", meaning: "National Tax Day. The deadline nobody celebrates and everybody remembers — the day the government collects its share. It means adulting has a due date, and the due date is today. File it. Then breathe.", anchorQuestion: "What adulting task have you been avoiding that is due today?", whoIsThisSoul: ["What does Tax Day feel like in your body?", "If you got a refund, what would you actually do with it?"], adventures: ["File your taxes today, if you have not. Or celebrate that you already did.", "Do one piece of adulting you have been avoiding."] },
  "04-16": { title: "National Eggs Benedict Day", tagline: "Poached eggs. Hollandaise. Brunch royalty.", meaning: "National Eggs Benedict Day. Eggs Benedict is breakfast that requires a sauce, a poach, and a plan — the most high-maintenance breakfast ever, and worth every step. It means some mornings deserve the full production.", anchorQuestion: "What is your Eggs Benedict — the thing worth the full production?", whoIsThisSoul: ["What does your perfect brunch look like?", "When did you last make something complicated just because it was worth it?"], adventures: ["Eat Eggs Benedict today. Hollandaise mandatory.", "Make brunch an event, not a meal."] },
  "04-17": { title: "National Haiku Poetry Day", tagline: "Five, seven, five. That is the whole poem.", meaning: "National Haiku Poetry Day. A haiku is seventeen syllables and one whole feeling — proof that small is not less. It means you do not need a novel to say something true. Five, seven, five. Done.", anchorQuestion: "What would your haiku say today?", whoIsThisSoul: ["What can you say in seventeen syllables that you cannot say in a paragraph?", "When did brevity beat you?"], adventures: ["Write a haiku today. Five, seven, five. No cheating.", "Read a haiku out loud. Feel how much fits in so little."] },
  "04-18": { title: "National Animal Crackers Day", tagline: "The box is a train. The crackers are animals. The magic is real.", meaning: "National Animal Crackers Day. Animal crackers come in a box shaped like a circus train, and every kid knows the box is part of the snack. It means packaging is part of the magic. The train matters.", anchorQuestion: "What packaging from your childhood do you still remember?", whoIsThisSoul: ["What animal cracker are you — lion, tiger, bear, or the weird one?", "When did you last eat something that came in a fun box?"], adventures: ["Eat animal crackers today. From the train box if you can.", "Name every animal in the box. Bonus for the obscure ones."] },
  "04-19": { title: "National Garlic Day", tagline: "Garlic: the flavor that fights back.", meaning: "National Garlic Day. Garlic is the only ingredient that announces itself — you can smell it from the street, and the whole neighborhood knows what is for dinner. It means some flavors do not whisper. They declare.", anchorQuestion: "What flavor do you declare — the one everyone knows is yours?", whoIsThisSoul: ["How much garlic is too much garlic? Trick question. There is no such thing.", "What would you cook if the smell did not matter?"], adventures: ["Cook with garlic today. Extra cloves. No such thing as too much.", "Eat garlic bread. Double garlic."] },
  "04-20": { title: "National Lima Bean Respect Day", tagline: "Lima beans. Finally getting the respect they deserve.", meaning: "National Lima Bean Respect Day. Lima beans are the most disrespected legume in the pod — pushed to the side of the plate, picked out of the succotash. It means even the humble things deserve respect. Today, the lima bean gets its due.", anchorQuestion: "What in your life deserves more respect than it gets?", whoIsThisSoul: ["What are you the lima bean of — underrated and pushed aside?", "When did you last stand up for something unpopular?"], adventures: ["Eat lima beans today. With respect.", "Give respect to one underrated thing today — a food, a person, or yourself."] },
  "04-21": { title: "National Tea Day", tagline: "Tea: hot water with opinions.", meaning: "National Tea Day. Tea is just leaves and hot water, and somehow it became a ritual, a ceremony, and a whole personality. It means the simplest things become sacred when you slow down for them.", anchorQuestion: "What is your tea — the ritual that slows you down?", whoIsThisSoul: ["Are you a tea person, a coffee person, or a whatever-is-hot person?", "When did a cup of tea last fix something?"], adventures: ["Drink tea today. Slowly. No rushing.", "Try a tea you have never had."] },
  "04-22": { title: "Earth Day", tagline: "The planet is the only home with free rent. Act like it.", meaning: "Earth Day. One day a year the whole planet agrees to notice the planet — the air, the water, the dirt, all of it. It means the Earth is not a backdrop. It is the house. Take your shoes off. Pick up after yourself.", anchorQuestion: "What is one thing you can do for the Earth today that you will actually do?", whoIsThisSoul: ["What part of the Earth do you love most?", "When did you last touch the ground on purpose?"], adventures: ["Do one thing for the Earth today. Pick up litter, plant something, or just go outside.", "Turn off one thing you do not need. The planet notices."] },
  "04-23": { title: "National Picnic Day", tagline: "Blanket. Basket. Bugs. Bliss.", meaning: "National Picnic Day. A picnic is a meal that refuses to stay indoors — food tastes better on a blanket with ants as uninvited guests. It means eating outside is not a compromise. It is an upgrade.", anchorQuestion: "What would your perfect picnic look like?", whoIsThisSoul: ["What food tastes better outside?", "When did you last eat on the ground on purpose?"], adventures: ["Have a picnic today. Blanket optional, outside required.", "If it rains, picnic on the floor indoors. Same energy."] },
  "04-24": { title: "National Pigs in a Blanket Day", tagline: "Tiny hot dogs. Tiny blankets. Tiny perfection.", meaning: "National Pigs in a Blanket Day. Pigs in a blanket are the only food that is also a bedtime story — a little pig, tucked into a little blanket. It means small food is better food. The mini version always wins.", anchorQuestion: "What mini version of something is better than the original?", whoIsThisSoul: ["What would you wrap in a blanket if you could?", "When did finger food last make a party?"], adventures: ["Eat pigs in a blanket today. Mini ones count double.", "Wrap something in dough and bake it. That is the whole recipe."] },
  "04-25": { title: "National Zucchini Bread Day", tagline: "Vegetables in bread. The sneakiest health food.", meaning: "National Zucchini Bread Day. Zucchini bread is banana bread's quieter cousin — the one that sneaks a vegetable into dessert and nobody notices. It means the best health food is the kind that does not announce itself.", anchorQuestion: "What vegetable are you sneaking into your life?", whoIsThisSoul: ["What is your zucchini bread — the good thing disguised as a treat?", "When did you last eat something healthy without realizing it?"], adventures: ["Eat zucchini bread today. With butter. Obviously.", "Bake a loaf and give half away. Bread is a gift."] },
  "04-26": { title: "National Pretzel Day", tagline: "Twisted. Salty. Perfect. Like you.", meaning: "National Pretzel Day. A pretzel is dough tied in a knot — the only food shaped like a problem. It means being twisted is not a flaw. It is the shape. Salt on top.", anchorQuestion: "What knot in your life turned out to be the shape?", whoIsThisSoul: ["Are you a soft pretzel or a hard pretzel person?", "What twist in your story made it better?"], adventures: ["Eat a pretzel today. Soft with cheese, or hard with mustard.", "Tie something in a knot on purpose. Then untie it."] },
  "04-27": { title: "National Prime Rib Day", tagline: "Prime rib: the roast that means business.", meaning: "National Prime Rib Day. Prime rib is the roast that shows up for holidays and special occasions — the cut that says this day matters. It means some meals are events. The roast is the reason.", anchorQuestion: "What deserves a prime rib in your life?", whoIsThisSoul: ["What is your prime rib — the meal that means celebration?", "When did you last cook something that took all day?"], adventures: ["Eat prime rib today, if you can. Or any roast that feels special.", "Make a meal an event. Set the table. Light a candle."] },
  "04-28": { title: "National Superhero Day", tagline: "Capes optional. Heroics required.", meaning: "National Superhero Day. Superheroes are just people who decided to help, plus a costume. It means the cape is not the power. The decision is. Everybody has a superpower — most people just never put on the costume.", anchorQuestion: "What is your superpower?", whoIsThisSoul: ["If you had one superpower for a day, what would it be?", "Who is the superhero in your real life?"], adventures: ["Wear a cape today. Or a towel. Same thing.", "Do one heroic thing — help someone, stand up, show up."] },
  "04-29": { title: "National Shrimp Scampi Day", tagline: "Garlic. Butter. Shrimp. The holy trinity.", meaning: "National Shrimp Scampi Day. Shrimp scampi is garlic, butter, and shrimp in a pan — three ingredients that decided to be perfect together. It means the best recipes are short. The flavor does the talking.", anchorQuestion: "What three ingredients make your perfect day?", whoIsThisSoul: ["What is your scampi — the thing that is perfect with three ingredients?", "When did simple last beat fancy?"], adventures: ["Eat shrimp scampi today. Extra garlic. Extra butter.", "Cook something with only three ingredients. See what happens."] },
  "04-30": { title: "National Honesty Day", tagline: "Tell the truth. All day. See what happens.", meaning: "National Honesty Day. Founded as the antidote to April Fools' — one day of lying, one day of truth. It means honesty is not just not-lying. It is saying the true thing, out loud, on purpose.", anchorQuestion: "What true thing have you been avoiding saying?", whoIsThisSoul: ["What lie do you tell most often — to others or to yourself?", "When did honesty cost you something and still feel worth it?"], adventures: ["Tell one true thing today that you have been avoiding.", "Be honest with yourself about one thing. Just one."] },
  // ---- May ----
  "05-01": { title: "National Chocolate Parfait Day", tagline: "Layers. Chocolate. A glass. Go.", meaning: "National Chocolate Parfait Day. A parfait is just dessert with architecture — layers you can see through the glass. It means presentation is part of the flavor. Eat with your eyes first.", anchorQuestion: "What layers are you hiding that deserve to be seen?", whoIsThisSoul: ["What is your parfait — the thing that is better in layers?", "When did you last make something beautiful just to eat it?"], adventures: ["Eat a chocolate parfait today. Layers visible.", "Layer something today — dessert, outfit, or a plan."] },
  "05-02": { title: "National Truffle Day", tagline: "Truffles: chocolate that went to finishing school.", meaning: "National Truffle Day. A truffle is chocolate that got rolled in cocoa and decided to be fancy — same chocolate, better outfit. It means a little finish goes a long way. The truffle is proof.", anchorQuestion: "What in your life needs a truffle finish?", whoIsThisSoul: ["What is your truffle — the fancy version of something simple?", "When did a small finish change everything?"], adventures: ["Eat a truffle today. The chocolate kind. Or the mushroom kind. Both count.", "Finish one thing properly today — the garnish, the bow, the last touch."] },
  "05-03": { title: "National Paranormal Day", tagline: "Ghosts. Aliens. Things that go bump. Today they are real.", meaning: "National Paranormal Day. Paranormal means beyond normal — the things science cannot explain yet, and the stories we tell about them. It means not everything fits in a spreadsheet. Some things just go bump.", anchorQuestion: "What paranormal thing have you experienced that you cannot explain?", whoIsThisSoul: ["What do you believe in that you cannot prove?", "If ghosts are real, whose ghost would visit you?"], adventures: ["Tell a ghost story today. Or listen to one.", "Watch something spooky. Leave one light on."] },
  "05-04": { title: "Star Wars Day", tagline: "May the Fourth be with you. Always.", meaning: "Star Wars Day. May the Fourth be with you — the pun that launched a thousand lightsabers. It means the Force is just the idea that something bigger connects us, and that idea built a whole universe.", anchorQuestion: "Are you Jedi, Sith, or the droid who just wants to survive?", whoIsThisSoul: ["What is your Force — the thing that connects you to everything?", "When did you last feel the Force, whatever it is to you?"], adventures: ["Watch Star Wars today. Any one. All of them. Your call.", "Say May the Fourth be with you to everyone. Everyone."] },
  "05-05": { title: "Cinco de Mayo", tagline: "Celebrate the Battle of Puebla. And the tacos.", meaning: "Cinco de Mayo. Not Mexican Independence Day — the Battle of Puebla, when a smaller army beat a bigger one. It means underdogs win sometimes, and when they do, we eat tacos.", anchorQuestion: "When did you beat a bigger army?", whoIsThisSoul: ["What battle of yours deserves a taco?", "What do you celebrate that other people misunderstand?"], adventures: ["Eat tacos today. Real ones. With lime.", "Learn one true thing about the Battle of Puebla."] },
  "05-06": { title: "National Beverage Day", tagline: "Drink something. Anything. Cheers.", meaning: "National Beverage Day. A holiday for every drink — water, soda, juice, tea, all of it. It means hydration is a celebration. The beverage is the point.", anchorQuestion: "What is your beverage — the drink that is also a mood?", whoIsThisSoul: ["What do you reach for when you need comfort?", "When did a drink last mark a moment?"], adventures: ["Drink your favorite beverage today. Slowly.", "Try a beverage you have never had."] },
  "05-07": { title: "National Roast Leg of Lamb Day", tagline: "Lamb. Roasted. A whole occasion.", meaning: "National Roast Leg of Lamb Day. A roast leg of lamb is a Sunday dinner that decided to be a holiday — meat, herbs, hours in the oven. It means some meals are worth the wait. The roast is the reason.", anchorQuestion: "What in your life is worth a slow roast?", whoIsThisSoul: ["What is your roast — the meal that means home?", "When did you last cook something that took all afternoon?"], adventures: ["Eat roast lamb today, or any slow roast.", "Cook something low and slow. The waiting is the recipe."] },
  "05-08": { title: "National Coconut Cream Pie Day", tagline: "Coconut. Cream. Pie. The holy trinity.", meaning: "National Coconut Cream Pie Day. Coconut cream pie is the dessert that tastes like a vacation — tropical, creamy, and topped with toasted coconut like sand on a beach. It means dessert can be a destination.", anchorQuestion: "What dessert takes you on vacation?", whoIsThisSoul: ["What is your coconut cream pie — the thing that tastes like escape?", "When did you last eat dessert on a beach, real or imagined?"], adventures: ["Eat coconut cream pie today. Toasted coconut on top mandatory.", "If you hate coconut, eat a pie that feels like a vacation to you."] },
  "05-09": { title: "National Moscato Day", tagline: "Sweet wine for sweet people.", meaning: "National Moscato Day. Moscato is the wine for people who like their wine sweet and their evenings sweeter. It means sweetness is not a flaw. It is a flavor.", anchorQuestion: "What is sweet in your life right now?", whoIsThisSoul: ["Are you a sweet wine person or a dry wine person — and what does that say about you?", "When did sweetness last surprise you?"], adventures: ["Drink Moscato today, if you drink. Sweet counts.", "If you do not drink, eat something sweet and call it Moscato energy."] },
  "05-10": { title: "National Clean Up Your Room Day", tagline: "The room is a mess. You know it. Today is the day.", meaning: "National Clean Up Your Room Day. Your room is a mess, and you have been walking past it for weeks. It means cleaning is not punishment — it is finding things you forgot you had.", anchorQuestion: "What will you find when you clean your room?", whoIsThisSoul: ["What does your mess say about you?", "When did cleaning last feel like therapy?"], adventures: ["Clean your room today. One room. One hour. Go.", "Find one thing you forgot you owned. Keep it or let it go."] },
  "05-11": { title: "National Eat What You Want Day", tagline: "Eat what you want. No rules. No guilt.", meaning: "National Eat What You Want Day. One day a year with no food rules — no calories, no guilt, no should. It means the rules are made up, and today they are suspended. Eat what you want.", anchorQuestion: "What do you want to eat that the rules say you should not?", whoIsThisSoul: ["What food rules are you following that are not even yours?", "When did you last eat something purely because you wanted it?"], adventures: ["Eat what you want today. Anything. No justification required.", "Skip the food guilt for one day. Just one."] },
  "05-12": { title: "National Nutty Fudge Day", tagline: "Fudge with nuts. The best kind of nuts.", meaning: "National Nutty Fudge Day. Fudge is already a commitment — sugar, butter, chocolate, and patience. Add nuts and it becomes a texture argument. It means the best things have a little crunch.", anchorQuestion: "What is your crunch — the texture that makes it better?", whoIsThisSoul: ["Are you nutty fudge or plain fudge?", "When did a little crunch change everything?"], adventures: ["Eat nutty fudge today. Nuts mandatory.", "Add crunch to something today — food, conversation, or a plan."] },
  "05-13": { title: "National Fruit Cocktail Day", tagline: "Fruit cocktail: the fruit salad that gave up and got canned.", meaning: "National Fruit Cocktail Day. Fruit cocktail is the fruit salad that comes in a can — cherries, peaches, pears, all swimming together. It means mixed fruit is still fruit. The can does not make it less.", anchorQuestion: "What canned version of something do you secretly love?", whoIsThisSoul: ["What is your fruit cocktail — the mix that should not work but does?", "When did you last eat fruit from a can and enjoy it?"], adventures: ["Eat fruit cocktail today. From the can. With the syrup.", "Mix three fruits together that have never met."] },
  "05-14": { title: "National Dance Like a Chicken Day", tagline: "Do the chicken dance. You know the moves.", meaning: "National Dance Like a Chicken Day. The chicken dance is the only dance that requires flapping, waddling, and zero dignity. It means dancing is not about looking good. It is about flapping.", anchorQuestion: "When did you last dance like a chicken?", whoIsThisSoul: ["What dance do you do when nobody is watching?", "When did dignity last stop you from having fun?"], adventures: ["Do the chicken dance today. Flap. Waddle. Commit.", "Dance like an animal. Any animal. Full commitment."] },
  "05-15": { title: "National Chocolate Chip Day", tagline: "The chip that built an empire.", meaning: "National Chocolate Chip Day. The chocolate chip was an accident — a baker ran out of nuts and chopped up a chocolate bar instead. It means the best inventions are accidents with good PR.", anchorQuestion: "What accident in your life turned out to be the best thing?", whoIsThisSoul: ["What is your chocolate chip — the accident that became essential?", "When did running out of something lead to something better?"], adventures: ["Eat chocolate chips today. Straight from the bag counts.", "Bake chocolate chip cookies. Or eat the dough. No judgment."] },
  "05-16": { title: "National Barbecue Day", tagline: "Smoke. Fire. Meat. The oldest party.", meaning: "National Barbecue Day. Barbecue is fire, smoke, and meat — the oldest party humans ever threw. It means gathering around fire is in our bones. The grill is the altar.", anchorQuestion: "What would you barbecue if you could barbecue anything?", whoIsThisSoul: ["What is your barbecue — the gathering that feels ancient?", "When did smoke and fire last bring people together for you?"], adventures: ["Barbecue today. Grill, smoker, or a pan on the stove.", "Eat something smoky. Share it with someone."] },
  "05-17": { title: "National Pack Rat Day", tagline: "You are not hoarding. You are curating.", meaning: "National Pack Rat Day. Pack rats keep everything — string, foil, that one screw from 2019. It means keeping things is not a flaw. It is preparation. The pack rat is always ready.", anchorQuestion: "What are you hoarding that you will actually need one day?", whoIsThisSoul: ["What is the weirdest thing you have kept?", "When did something you saved save you?"], adventures: ["Keep something today that you would normally throw away.", "Organize one drawer of your hoard. Just one."] },
  "05-18": { title: "National No Dirty Dishes Day", tagline: "No dishes. Paper plates. Freedom.", meaning: "National No Dirty Dishes Day. One day a year with no dishes — paper plates, takeout, or just eating straight from the pot. It means the dishes can wait. Today, they do not exist.", anchorQuestion: "What chore would you ban for a day if you could?", whoIsThisSoul: ["What does a sink full of dishes say about your week?", "When did you last skip a chore and feel free?"], adventures: ["Use no real dishes today. Paper plates. Takeout. Zero guilt.", "Let the dishes sit. They will be there tomorrow."] },
  "05-19": { title: "National Devil's Food Cake Day", tagline: "Devil's food: chocolate cake with an attitude.", meaning: "National Devil's Food Cake Day. Devil's food is chocolate cake that went dark — deeper, richer, more intense than regular chocolate cake. It means darkness is a flavor. The devil's food is the good stuff.", anchorQuestion: "What is your devil's food — the dark version you prefer?", whoIsThisSoul: ["Are you angel food or devil's food?", "When did the dark version turn out better?"], adventures: ["Eat devil's food cake today. Dark chocolate mandatory.", "Embrace your dark side for one dessert."] },
  "05-20": { title: "National Pick Strawberries Day", tagline: "Pick them. Eat them. Stain your fingers.", meaning: "National Pick Strawberries Day. Picking strawberries is the only farming where you eat half the harvest before it reaches the basket. It means the work is the reward. The stained fingers are the receipt.", anchorQuestion: "What would you pick if you could pick anything?", whoIsThisSoul: ["What is your strawberry — the thing you cannot help eating while you work?", "When did you last eat something straight from the source?"], adventures: ["Eat strawberries today. Fresh, not frozen.", "If you can, pick them yourself. Eat one in the field."] },
  "05-21": { title: "National Waiters and Waitresses Day", tagline: "Tip well. They are the whole restaurant.", meaning: "National Waiters and Waitresses Day. Servers are the face of every restaurant — they carry the food, the mood, and the complaints. It means the person serving you is a person. Tip like it.", anchorQuestion: "When did a server make your day?", whoIsThisSoul: ["What would you do if you served people for a living?", "How do you treat the people who serve you?"], adventures: ["Tip extra today. Generously.", "Thank your server by name. Mean it."] },
  "05-22": { title: "National Buy a Musical Instrument Day", tagline: "Buy the instrument. Learn it later.", meaning: "National Buy a Musical Instrument Day. Buying an instrument is a promise to your future self — the one who can play it. It means the instrument is the first step. The practice is the rest.", anchorQuestion: "What instrument would you play if you could play anything?", whoIsThisSoul: ["What is your instrument — the thing you bought and never learned?", "When did music last move you?"], adventures: ["Play an instrument today. Even a kazoo. Even badly.", "If you do not own one, hum. Humming counts."] },
  "05-23": { title: "National Lucky Penny Day", tagline: "Find a penny. Pick it up. All day long you will have good luck.", meaning: "National Lucky Penny Day. A penny on the ground is the smallest fortune you can find — one cent, and a whole superstition. It means luck is mostly about noticing. The penny was always there.", anchorQuestion: "What lucky penny have you walked past lately?", whoIsThisSoul: ["Do you believe in luck, or do you make it?", "When did a tiny bit of luck change your day?"], adventures: ["Pick up a penny today. Heads up is extra lucky.", "Leave a penny heads-up for someone else to find."] },
  "05-24": { title: "National Escargot Day", tagline: "Snails. Garlic butter. Courage.", meaning: "National Escargot Day. Escargot is snails in garlic butter — the dish that separates the adventurous from the cautious. It means courage is a flavor. The snail is just the vehicle.", anchorQuestion: "What escargot in your life are you avoiding because it is snails?", whoIsThisSoul: ["What would you eat if courage were the only ingredient?", "When did you last try something that scared you?"], adventures: ["Try escargot today, if you can. Or any food that scares you.", "Be brave about one bite."] },
  "05-25": { title: "National Wine Day", tagline: "Wine. The whole day. The whole bottle. (Responsibly.)", meaning: "National Wine Day. Wine is grapes that waited, fermented, and became something better — patience in a bottle. It means some things get better with time, and some days the answer is a glass.", anchorQuestion: "What in your life is aging like wine?", whoIsThisSoul: ["What is your wine — the thing that got better with age?", "When did you last sip something and actually taste it?"], adventures: ["Drink wine today, if you drink. Sip it. Taste it.", "If you do not drink, eat grapes. Same plant, same patience."] },
  "05-26": { title: "National Blueberry Cheesecake Day", tagline: "Cheesecake. Blueberries. The dream team.", meaning: "National Blueberry Cheesecake Day. Cheesecake is already a commitment; blueberries on top make it a celebration. It means toppings matter. The blueberry is the crown.", anchorQuestion: "What is the blueberry on top of your cheesecake?", whoIsThisSoul: ["What topping makes everything better for you?", "When did a small addition change the whole dish?"], adventures: ["Eat blueberry cheesecake today. Blueberries on top mandatory.", "Add a topping to something ordinary today."] },
  "05-27": { title: "National Grape Popsicle Day", tagline: "Grape popsicles: summer on a stick.", meaning: "National Grape Popsicle Day. A grape popsicle is summer frozen on a stick — purple, cold, and guaranteed to stain your tongue. It means summer is a flavor, and the flavor is grape.", anchorQuestion: "What tastes like summer to you?", whoIsThisSoul: ["What is your grape popsicle — the frozen memory of summer?", "When did you last stain your tongue purple?"], adventures: ["Eat a grape popsicle today. Tongue staining required.", "Freeze some grapes. Eat them frozen. Same energy."] },
  "05-28": { title: "National Hamburger Day", tagline: "Burgers. The only food that needs no occasion.", meaning: "National Hamburger Day. A hamburger is the only food that works for a cookout, a drive-thru, a fancy restaurant, and 2 AM. It means some foods are universal. The burger is one of them.", anchorQuestion: "What is your burger order?", whoIsThisSoul: ["What is your burger — the thing that works everywhere?", "When did a burger last fix a bad day?"], adventures: ["Eat a hamburger today. Your way. No judgment.", "Grill one. Or drive-thru one. Both count."] },
  "05-29": { title: "National Biscuit Day", tagline: "Biscuits: butter's best friend.", meaning: "National Biscuit Day. A biscuit is flour, butter, and heat — three things that decided to be perfect together. It means simple food is not lesser food. The biscuit is proof.", anchorQuestion: "What is your biscuit — the simple thing you do perfectly?", whoIsThisSoul: ["What would you put on a biscuit if you could put anything on it?", "When did a biscuit last make a meal?"], adventures: ["Eat a biscuit today. With butter. With gravy. With jam. All of it.", "Bake biscuits. They are supposed to be ugly."] },
  "05-30": { title: "National Mint Julep Day", tagline: "Mint. Bourbon. Crushed ice. Kentucky.", meaning: "National Mint Julep Day. A mint julep is bourbon, mint, and crushed ice in a silver cup — the official drink of the Kentucky Derby and the unofficial drink of hot afternoons. It means some drinks are events. The cup matters.", anchorQuestion: "What drink feels like an event to you?", whoIsThisSoul: ["What is your mint julep — the drink that means occasion?", "When did you last drink from a fancy cup for no reason?"], adventures: ["Drink a mint julep today, if you drink. Mint mandatory.", "If you do not drink, make a mint iced tea. Same cup, same vibe."] },
  "05-31": { title: "National Macaroon Day", tagline: "Macaroons: coconut's greatest hit.", meaning: "National Macaroon Day. A macaroon is coconut, sugar, and egg white — three ingredients that became a chewy, golden cloud. It means the simplest recipes are sometimes the best ones. The macaroon is proof.", anchorQuestion: "What simple thing of yours is secretly a masterpiece?", whoIsThisSoul: ["Macaroon or macaron — do you know the difference? Does it matter?", "When did simple last beat complicated?"], adventures: ["Eat a macaroon today. Coconut. Chewy. Golden.", "Bake three-ingredient anything. See what happens."] },
  // ---- June ----
  "06-01": { title: "National Olive Day", tagline: "Olives: love them or leave them. There is no middle.", meaning: "National Olive Day. Olives are the most divisive food on earth — people either love them or act like you served them a punishment. It means some flavors are not for everyone, and that is fine. The olive does not care.", anchorQuestion: "Olives: love or leave? Defend your answer.", whoIsThisSoul: ["What do you love that other people think is gross?", "When did you last change your mind about a food?"], adventures: ["Eat olives today. Green, black, or stuffed.", "If you hate olives, eat one anyway. Today is the day."] },
  "06-02": { title: "National Rocky Road Day", tagline: "Rocky road: ice cream with obstacles.", meaning: "National Rocky Road Day. Rocky road is ice cream with marshmallows and nuts — obstacles in your dessert. It means the rocky road is the good road. The smooth road is boring.", anchorQuestion: "What rocky road are you on right now?", whoIsThisSoul: ["What is your rocky road — the hard path that tastes better?", "When did the obstacles turn out to be the best part?"], adventures: ["Eat rocky road ice cream today. Marshmallows and nuts mandatory.", "Take the rocky road today — literally or otherwise."] },
  "06-03": { title: "National Egg Day", tagline: "Eggs: the original superfood.", meaning: "National Egg Day. An egg is the only food that comes in its own packaging, cooks a dozen ways, and works for every meal. It means the simplest things are the most versatile. The egg is proof.", anchorQuestion: "How do you like your eggs?", whoIsThisSoul: ["What is your egg — the thing that works a dozen ways?", "When did an egg last save breakfast?"], adventures: ["Eat eggs today. Any style. All styles.", "Cook an egg a way you have never tried."] },
  "06-04": { title: "National Cheese Day", tagline: "Cheese. All day. No apologies.", meaning: "National Cheese Day. Cheese is milk that refused to be ordinary — it aged, it cultured, it became something else entirely. It means transformation takes time, and time is the ingredient nobody wants to wait for.", anchorQuestion: "What cheese are you — sharp, soft, stinky, or melted?", whoIsThisSoul: ["What in your life is aging like cheese?", "When did you last eat cheese for a meal and call it dinner?"], adventures: ["Eat cheese today. The good stuff. A cheese board if you are feeling fancy.", "Try a cheese you have never had."] },
  "06-05": { title: "National Moonshine Day", tagline: "Moonshine: the original DIY.", meaning: "National Moonshine Day. Moonshine is liquor made in secret, by hand, outside the law — the original DIY spirit. It means some things are better homemade, and some rules are meant to be bent. Sip responsibly.", anchorQuestion: "What would you make by hand if the law did not matter?", whoIsThisSoul: ["What is your moonshine — the thing you make yourself because store-bought is not the same?", "When did DIY last beat store-bought?"], adventures: ["Learn one fact about moonshine today. The history is wild.", "Make something by hand today. Anything."] },
  "06-06": { title: "National Applesauce Cake Day", tagline: "Applesauce cake: the cake that hides fruit.", meaning: "National Applesauce Cake Day. Applesauce cake is cake with a secret — the applesauce keeps it moist and nobody knows it is there. It means the best ingredients are invisible. The cake is the proof.", anchorQuestion: "What secret ingredient makes your life work?", whoIsThisSoul: ["What is your applesauce — the hidden thing that keeps everything moist?", "When did a secret ingredient save the recipe?"], adventures: ["Eat applesauce cake today. Or any cake with a secret.", "Hide a healthy ingredient in something delicious."] },
  "06-07": { title: "National Chocolate Ice Cream Day", tagline: "Chocolate ice cream. The classic. The only.", meaning: "National Chocolate Ice Cream Day. Chocolate ice cream is the flavor every other flavor is measured against — the original, the standard, the one that never goes out of style. It means classics are classics for a reason.", anchorQuestion: "What is your chocolate ice cream — the classic you never outgrow?", whoIsThisSoul: ["What flavor would you be if you were ice cream?", "When did a classic last beat the fancy new thing?"], adventures: ["Eat chocolate ice cream today. Cone or bowl. No toppings required.", "Eat it slowly. The classic deserves it."] },
  "06-08": { title: "National Best Friends Day", tagline: "Best friends. The family you picked.", meaning: "National Best Friends Day. Best friends are the family you chose — the ones who know the stories, the passwords, and the version of you from before you were cool. It means chosen family is real family.", anchorQuestion: "Who is your best friend, and what do they know that nobody else does?", whoIsThisSoul: ["When did your best friend last save you?", "What makes a best friend different from a friend?"], adventures: ["Contact your best friend today. Tell them they are your best friend.", "Do something with your best friend. Anything. Even nothing."] },
  "06-09": { title: "National Donald Duck Day", tagline: "Donald Duck. Quacking since 1934.", meaning: "National Donald Duck Day, on the birthday of the most temperamental duck in cartoon history. Donald is angry, unlucky, and unintelligible — and beloved anyway. It means you do not have to be likable to be loved. You just have to be yourself, quacks and all.", anchorQuestion: "When are you Donald Duck — angry, unlucky, and still loved?", whoIsThisSoul: ["What cartoon character are you, really?", "When did your temper last get you in trouble — and was it worth it?"], adventures: ["Do your best Donald Duck impression today.", "Watch a Donald Duck cartoon. Quack along."] },
  "06-10": { title: "National Iced Tea Day", tagline: "Iced tea: summer in a glass.", meaning: "National Iced Tea Day. Iced tea is summer in a glass — cold, sweet, and best consumed on a porch. It means some drinks are seasons. The iced tea is June.", anchorQuestion: "What drink tastes like summer to you?", whoIsThisSoul: ["Sweet or unsweet? This is a personality test.", "When did iced tea last fix a hot day?"], adventures: ["Drink iced tea today. Sweet or unsweet — your call.", "Brew it yourself. Sun tea counts. Porch optional."] },
  "06-11": { title: "National Corn on the Cob Day", tagline: "Corn on the cob: summer's favorite mess.", meaning: "National Corn on the Cob Day. Corn on the cob is the only food you eat by holding it with both hands and getting butter on your face. It means some foods are meant to be messy. The mess is the meal.", anchorQuestion: "What messy food do you love anyway?", whoIsThisSoul: ["What is your corn on the cob — the thing worth getting messy for?", "When did you last eat with both hands and not care?"], adventures: ["Eat corn on the cob today. Butter. Salt. Both hands.", "Get butter on your face. Leave it. That is the look."] },
  "06-12": { title: "National Peanut Butter Cookie Day", tagline: "Peanut butter cookies: the fork marks are the signature.", meaning: "National Peanut Butter Cookie Day. Peanut butter cookies have fork marks on top — the only cookie with a signature. It means the mark matters. The fork press is the whole identity.", anchorQuestion: "What is your fork mark — the signature on everything you make?", whoIsThisSoul: ["What do you sign your work with, literally or otherwise?", "When did a small mark make something yours?"], adventures: ["Eat peanut butter cookies today. Fork marks mandatory.", "Bake them and press the fork marks yourself."] },
  "06-13": { title: "National Weed Your Garden Day", tagline: "Weed the garden. Weed your life. Same thing.", meaning: "National Weed Your Garden Day. Weeds are just plants in the wrong place — like bad habits, bad thoughts, and that one friend. It means weeding is not destruction. It is making room.", anchorQuestion: "What weeds are growing in your garden?", whoIsThisSoul: ["What weed in your life looks like a flower if you squint?", "When did pulling a weed feel like therapy?"], adventures: ["Pull a weed today. Garden, or life — your call.", "Make room for one thing by removing another."] },
  "06-14": { title: "National Strawberry Shortcake Day", tagline: "Shortcake. Strawberries. Cream. Summer.", meaning: "National Strawberry Shortcake Day. Strawberry shortcake is summer in a bowl — berries, cream, and cake that falls apart if you look at it. It means some desserts are not built to last. They are built to be eaten now.", anchorQuestion: "What shortcake moment are you in right now?", whoIsThisSoul: ["What is your strawberry shortcake — the thing that falls apart if you wait?", "When did you last eat dessert that could not wait?"], adventures: ["Eat strawberry shortcake today. Real whipped cream. No cans.", "Eat it immediately. Do not save it. That is the lesson."] },
  "06-15": { title: "National Nature Photography Day", tagline: "Take a photo of nature. Nature takes the rest.", meaning: "National Nature Photography Day. Nature photography is just standing still long enough for the world to show you something — the light, the bird, the flower. It means looking is a skill. The photo is the receipt.", anchorQuestion: "What would you photograph if you had to pick one thing in nature?", whoIsThisSoul: ["When did nature last surprise you with a photo?", "What do you see when you actually look?"], adventures: ["Take a photo of nature today. Phone counts.", "Go outside and look for one beautiful thing. Photograph it."] },
  "06-16": { title: "National Fudge Day", tagline: "Fudge: sugar, butter, and patience.", meaning: "National Fudge Day. Fudge is sugar and butter that decided to be a solid — a candy that requires patience and a candy thermometer. It means some things cannot be rushed. The fudge knows.", anchorQuestion: "What fudge are you making that cannot be rushed?", whoIsThisSoul: ["What is your fudge — the thing that takes patience and is worth it?", "When did patience last pay off?"], adventures: ["Eat fudge today. Any flavor. All flavors.", "Make fudge. Stir it. Wait. The waiting is the recipe."] },
  "06-17": { title: "National Eat Your Vegetables Day", tagline: "Eat your vegetables. Your mom was right.", meaning: "National Eat Your Vegetables Day. Your mom was right about the vegetables — they are good for you, and you have been avoiding them for no reason. It means the boring advice is usually the correct advice.", anchorQuestion: "What vegetable have you been avoiding that you actually like?", whoIsThisSoul: ["What boring advice turned out to be right?", "When did you last eat a vegetable on purpose?"], adventures: ["Eat your vegetables today. All of them. Even the ones you hate.", "Cook a vegetable a way you have never tried."] },
  "06-18": { title: "National Picnic Day", tagline: "Blanket. Basket. Bugs. Bliss. Again.", meaning: "National Picnic Day. A picnic is a meal that refuses to stay indoors — food tastes better on a blanket with ants as uninvited guests. It means eating outside is not a compromise. It is an upgrade.", anchorQuestion: "What would your perfect picnic look like?", whoIsThisSoul: ["What food tastes better outside?", "When did you last eat on the ground on purpose?"], adventures: ["Have a picnic today. Blanket optional, outside required.", "If it rains, picnic on the floor indoors. Same energy."] },
  "06-19": { title: "National Martini Day", tagline: "Shaken or stirred? The argument is the drink.", meaning: "National Martini Day. A martini is gin, vermouth, and an argument about whether it should be shaken or stirred. It means the argument is part of the drink. The olive is the period.", anchorQuestion: "Shaken or stirred?", whoIsThisSoul: ["What is your martini — the thing with a correct answer that everyone argues about?", "When did an argument last make something better?"], adventures: ["Drink a martini today, if you drink. Olive mandatory.", "If you do not drink, drink olive brine and call it research."] },
  "06-20": { title: "National Ice Cream Soda Day", tagline: "Ice cream plus soda. The float that started it all.", meaning: "National Ice Cream Soda Day. An ice cream soda is ice cream, soda, and a straw — the float that started the whole float family. It means some things are better together, even if they fizz.", anchorQuestion: "What is your ice cream soda — the combo that should not work but does?", whoIsThisSoul: ["What two things in your life fizz when they meet?", "When did a combination surprise you?"], adventures: ["Drink an ice cream soda today. Straw mandatory.", "Make a float with a soda you have never tried."] },
  "06-21": { title: "National Selfie Day", tagline: "Take the selfie. You look fine.", meaning: "National Selfie Day. A selfie is a self-portrait with no filter and no apology — you, right now, as you are. It means you are allowed to document yourself. You do not need a reason.", anchorQuestion: "When did you last take a selfie you actually liked?", whoIsThisSoul: ["What does your selfie say about you that a posed photo never could?", "Who do you take selfies for?"], adventures: ["Take a selfie today. No filter. No apology.", "Send it to someone. Or keep it. Both count."] },
  "06-22": { title: "National Onion Rings Day", tagline: "Onion rings: the circle of life.", meaning: "National Onion Rings Day. An onion ring is an onion that became a circle — the only vegetable that is also geometry. It means some foods are shapes first and flavors second. The ring is the point.", anchorQuestion: "What circle in your life keeps coming back around?", whoIsThisSoul: ["What is your onion ring — the thing that is better as a circle?", "When did you last eat something shaped like a ring?"], adventures: ["Eat onion rings today. Crispy. With dip.", "Draw a circle. Sit inside it. See what happens."] },
  "06-23": { title: "National Pecan Sandies Day", tagline: "Pecan sandies: the cookie that crumbles perfectly.", meaning: "National Pecan Sandies Day. A pecan sandy is a shortbread cookie with pecans — crumbly, buttery, and guaranteed to fall apart in your hand. It means some cookies are meant to crumble. The crumbs are the cookie.", anchorQuestion: "What in your life crumbles perfectly?", whoIsThisSoul: ["What is your pecan sandy — the thing that falls apart beautifully?", "When did crumbling turn out to be the point?"], adventures: ["Eat pecan sandies today. Crumbs everywhere. That is correct.", "Let something crumble today without fixing it."] },
  "06-24": { title: "National Pralines Day", tagline: "Pralines: sugar, nuts, and Southern magic.", meaning: "National Pralines Day. A praline is sugar and nuts cooked until they become something else entirely — candy with a history. It means transformation takes heat. The praline knows.", anchorQuestion: "What heat in your life made you into something else?", whoIsThisSoul: ["What is your praline — the thing that took heat to become itself?", "When did sweetness last come from a hard process?"], adventures: ["Eat pralines today. Southern style.", "Cook sugar until it transforms. Watch it. That is alchemy."] },
  "06-25": { title: "National Strawberry Parfait Day", tagline: "Strawberries. Cream. Layers. Again.", meaning: "National Strawberry Parfait Day. A strawberry parfait is strawberries and cream in layers you can see — dessert with transparency. It means layers are meant to be seen. The glass is the point.", anchorQuestion: "What layers of yours deserve to be seen?", whoIsThisSoul: ["What is your strawberry parfait — the thing that is better in layers?", "When did transparency make dessert better?"], adventures: ["Eat a strawberry parfait today. Layers visible.", "Show one layer of yourself you usually hide."] },
  "06-26": { title: "National Chocolate Pudding Day", tagline: "Chocolate pudding: the dessert that wobbles.", meaning: "National Chocolate Pudding Day. Chocolate pudding is the dessert that wobbles — soft, silky, and impossible to eat neatly. It means some desserts are not meant to be neat. The wobble is the charm.", anchorQuestion: "What wobbles in your life that you love anyway?", whoIsThisSoul: ["What is your chocolate pudding — the soft thing that cannot be neat?", "When did wobbling turn out to be the point?"], adventures: ["Eat chocolate pudding today. Wobble it first.", "Let something wobble today without stabilizing it."] },
  "06-27": { title: "National Orange Blossom Day", tagline: "Orange blossoms: the smell of spring leaving.", meaning: "National Orange Blossom Day. Orange blossoms smell like spring deciding to stay a little longer — sweet, floral, and gone too soon. It means some scents are seasons. The blossom is the season.", anchorQuestion: "What smell means spring to you?", whoIsThisSoul: ["What blossom are you — the flower that smells like a season?", "When did a smell last stop you in your tracks?"], adventures: ["Smell an orange blossom today. Or any blossom.", "Wear a floral scent. Or just notice one."] },
  "06-28": { title: "National Tapioca Day", tagline: "Tapioca: the pudding with pearls.", meaning: "National Tapioca Day. Tapioca is pudding with pearls — little chewy spheres that make the whole thing interesting. It means texture is a flavor. The pearls are the point.", anchorQuestion: "What pearls are hiding in your pudding?", whoIsThisSoul: ["What is your tapioca — the thing with unexpected texture?", "When did texture last surprise you?"], adventures: ["Eat tapioca today. Pearls mandatory.", "Drink boba. Same pearls, different delivery."] },
  "06-29": { title: "National Camera Day", tagline: "Take the photo. The moment is leaving.", meaning: "National Camera Day. A camera is a machine for stopping time — one click and the moment is yours forever. It means moments are not permanent unless you catch them. The photo is the net.", anchorQuestion: "What moment do you wish you had photographed?", whoIsThisSoul: ["What would you photograph if you could only take one more photo?", "When did a photo last bring back a moment you forgot?"], adventures: ["Take a photo today. Any photo. The moment is the point.", "Print a photo. Physical photos hit different."] },
  "06-30": { title: "National Meteor Watch Day", tagline: "Look up. The sky is falling. Beautifully.", meaning: "National Meteor Watch Day. Meteors are rocks from space burning up in our sky — the universe putting on a show for free. It means look up. The sky is doing something amazing and most people are looking at their phones.", anchorQuestion: "When did you last look up at the sky on purpose?", whoIsThisSoul: ["What is your meteor — the thing that burns bright and disappears?", "If you could wish on a meteor, what would you wish?"], adventures: ["Watch the sky tonight. Meteors optional, looking up mandatory.", "Make a wish on the first star you see."] },
  // ---- July ----
  "07-01": { title: "National Creative Ice Cream Flavors Day", tagline: "Ice cream flavors that should not exist. But do.", meaning: "National Creative Ice Cream Flavors Day. Someone made bacon ice cream, and garlic ice cream, and lobster ice cream — and the world said, why not? It means creativity is just permission. The flavor is the excuse.", anchorQuestion: "What creative flavor would you invent?", whoIsThisSoul: ["What is your creative ice cream flavor — the one nobody would order but everyone should try?", "When did you last create something that should not exist?"], adventures: ["Eat a weird ice cream flavor today. Or invent one.", "Describe your ice cream flavor to someone. Sell it."] },
  "07-02": { title: "World UFO Day", tagline: "They are out there. Today we admit it.", meaning: "World UFO Day. UFOs are the things in the sky we cannot explain — and the fact that we cannot explain them is the whole point. It means the sky is bigger than our answers.", anchorQuestion: "What UFO have you seen — literal or otherwise?", whoIsThisSoul: ["Do you believe in aliens? Really?", "What unexplained thing in your life do you keep coming back to?"], adventures: ["Watch the sky tonight. Look for something unexplained.", "Tell someone your UFO story. Everyone has one."] },
  "07-03": { title: "National Eat Your Beans Day", tagline: "Beans. The magical fruit. You know the song.", meaning: "National Eat Your Beans Day. Beans are the cheapest protein on earth, the most musical food, and the foundation of half the world's cooking. It means humble food feeds the world. The bean is the hero.", anchorQuestion: "What bean are you — black, pinto, kidney, or the weird one?", whoIsThisSoul: ["What humble thing in your life deserves a holiday?", "When did beans last save dinner?"], adventures: ["Eat beans today. Any kind. All kinds.", "Sing the bean song. You know it."] },
  "07-04": { title: "Independence Day", tagline: "Fireworks. Freedom. Hot dogs. America.", meaning: "Independence Day. Fireworks, freedom, and hot dogs — the day America declared itself independent and has been arguing about what that means ever since. It means independence is not a one-time declaration. It is a daily practice.", anchorQuestion: "What does independence mean to you, personally?", whoIsThisSoul: ["When did you declare your own independence?", "What are you independent from — and what are you still dependent on?"], adventures: ["Watch fireworks today. Or light sparklers. Or just look up.", "Declare one independence today — from a habit, a person, or a rule."] },
  "07-05": { title: "National Apple Turnover Day", tagline: "Apple turnover: pie that folded.", meaning: "National Apple Turnover Day. An apple turnover is pie that gave up on being round and folded in half instead — and it is better for it. It means folding is not failure. The turnover is proof.", anchorQuestion: "What in your life needs to fold in half to get better?", whoIsThisSoul: ["What is your apple turnover — the thing that got better by giving up its shape?", "When did folding turn out to be the right move?"], adventures: ["Eat an apple turnover today. Warm. With ice cream if you are brave.", "Fold something in half. A napkin, a plan, a piece of paper."] },
  "07-06": { title: "National Fried Chicken Day", tagline: "Fried chicken. The only argument is the seasoning.", meaning: "National Fried Chicken Day. Fried chicken is crispy, salty, juicy, and the subject of a thousand arguments about seasoning. It means the best food starts arguments. The seasoning is the whole debate.", anchorQuestion: "What is your fried chicken seasoning?", whoIsThisSoul: ["What food argument would you actually show up for?", "When did fried chicken last fix a bad day?"], adventures: ["Eat fried chicken today. Crispy. Hot. With all the fixings.", "Argue about seasoning with someone. Friendly argument only."] },
  "07-07": { title: "National Macaroni Day", tagline: "Macaroni: the pasta that became a hug.", meaning: "National Macaroni Day. Macaroni is the pasta that became a hug — elbow noodles, cheese sauce, and a whole childhood. It means comfort food is not about nutrition. It is about memory.", anchorQuestion: "What is your macaroni — the comfort food that is also a memory?", whoIsThisSoul: ["Who made your macaroni growing up?", "When did mac and cheese last fix everything?"], adventures: ["Eat macaroni today. And cheese. Obviously.", "Make it from a box. The box is the point."] },
  "07-08": { title: "National Ice Cream Sundae Day", tagline: "Sundae: ice cream with a cherry on top of its life.", meaning: "National Ice Cream Sundae Day. A sundae is ice cream that decided to get dressed up — sauce, nuts, whipped cream, cherry. It means toppings are not extra. They are the whole point.", anchorQuestion: "What is your sundae topping — the thing that makes it complete?", whoIsThisSoul: ["What would your sundae look like if you built it right now?", "When did a cherry on top actually matter?"], adventures: ["Eat an ice cream sundae today. Cherry on top mandatory.", "Build a sundae with every topping you can find."] },
  "07-09": { title: "National Sugar Cookie Day", tagline: "Sugar cookies: the blank canvas of cookies.", meaning: "National Sugar Cookie Day. A sugar cookie is the blank canvas of cookies — plain, sweet, and ready for frosting, sprinkles, or nothing at all. It means plain is not boring. Plain is potential.", anchorQuestion: "What blank canvas in your life is waiting for frosting?", whoIsThisSoul: ["What is your sugar cookie — the plain thing you love anyway?", "When did plain last beat fancy?"], adventures: ["Eat sugar cookies today. Frosted or plain. Both count.", "Decorate a sugar cookie. Or eat it plain. Both are correct."] },
  "07-10": { title: "National Pina Colada Day", tagline: "If you like pina coladas, today is your day.", meaning: "National Pina Colada Day. If you like pina coladas, and getting caught in the rain — today is your day. It means the song was right: the best things are a little tropical, a little silly, and best shared.", anchorQuestion: "Do you like pina coladas?", whoIsThisSoul: ["What is your pina colada — the song that is also a drink?", "When did you last get caught in the rain on purpose?"], adventures: ["Drink a pina colada today, if you drink. Virgin counts.", "Sing the song. All of it. Out loud."] },
  "07-11": { title: "National Slurpee Day", tagline: "Free Slurpee Day. The 7-Eleven giveth.", meaning: "National Slurpee Day, on 7/11 — the day 7-Eleven gives away free Slurpees and everyone becomes a kid again. It means free things taste better. The Slurpee is proof.", anchorQuestion: "What is your Slurpee flavor?", whoIsThisSoul: ["When did free last taste this good?", "What would you line up for, just because it is free?"], adventures: ["Get a Slurpee today. Free if you can. Cherry or Coke or both.", "Mix two flavors. That is the advanced move."] },
  "07-12": { title: "National Different Colored Eyes Day", tagline: "Different colored eyes. Different. Beautiful. Yours.", meaning: "National Different Colored Eyes Day. Heterochromia — two different colored eyes — is the rarest eye trait on earth. It means different is not a defect. It is a feature. The eyes are proof.", anchorQuestion: "What different thing about you is actually your best feature?", whoIsThisSoul: ["What would you see differently if your eyes were different colors?", "When did being different last work in your favor?"], adventures: ["Look at someone's eyes today. Really look.", "Celebrate one different thing about yourself. Out loud."] },
  "07-13": { title: "National French Fry Day", tagline: "French fries: the only food that needs no occasion.", meaning: "National French Fry Day. French fries are the only food that works with everything — burgers, steaks, breakfast, 2 AM. It means some foods are universal. The fry is one of them.", anchorQuestion: "What is your fry order — and what does it say about you?", whoIsThisSoul: ["What is your french fry — the thing that goes with everything?", "When did fries last save a meal?"], adventures: ["Eat french fries today. Any cut. All cuts.", "Dip them in something weird. Ranch, mayo, or gravy."] },
  "07-14": { title: "National Mac and Cheese Day", tagline: "Mac and cheese. The sequel. The main event.", meaning: "National Mac and Cheese Day. Mac and cheese is the sequel to macaroni day — the full production, the baked version, the one with the crust. It means some foods deserve two holidays. The mac and cheese is one of them.", anchorQuestion: "Baked or stovetop? This defines you.", whoIsThisSoul: ["What deserves two holidays in your life?", "When did mac and cheese last make everything better?"], adventures: ["Eat mac and cheese today. Baked if you can. Boxed if you cannot.", "Add a topping. Breadcrumbs, bacon, or hot sauce."] },
  "07-15": { title: "National Gummy Worm Day", tagline: "Gummy worms: the candy that wiggles.", meaning: "National Gummy Worm Day. Gummy worms are candy that wiggles — the only sweet that moves like it is alive. It means candy does not have to be serious. It can wiggle.", anchorQuestion: "What wiggles in your life that should not?", whoIsThisSoul: ["What is your gummy worm — the silly thing you love anyway?", "When did you last eat candy that moved?"], adventures: ["Eat gummy worms today. Wiggle them first.", "Put gummy worms in dirt pudding. Or just eat them."] },
  "07-16": { title: "National Fresh Spinach Day", tagline: "Fresh spinach. Popeye would approve.", meaning: "National Fresh Spinach Day. Fresh spinach is the leaf that made a sailor strong — and the only vegetable with its own cartoon endorsement. It means the fresh version is always better. The can was a lie.", anchorQuestion: "What fresh version of something have you been settling for canned?", whoIsThisSoul: ["What is your fresh spinach — the thing that is better fresh?", "When did fresh last beat canned?"], adventures: ["Eat fresh spinach today. Salad, sautéed, or blended.", "Tell yourself the Popeye story while you eat it."] },
  "07-17": { title: "World Emoji Day", tagline: "Emojis: the language we all speak.", meaning: "World Emoji Day. Emojis are the only language everyone on earth speaks — a face, a flame, a peach that is not a peach. It means pictures are words. The emoji is the sentence.", anchorQuestion: "What is your most-used emoji, and what does it say about you?", whoIsThisSoul: ["What emoji would you be?", "When did an emoji say what words could not?"], adventures: ["Text someone using only emojis today.", "Use your rarest emoji. Find it. Send it."] },
  "07-18": { title: "National Caviar Day", tagline: "Caviar: tiny eggs, huge attitude.", meaning: "National Caviar Day. Caviar is fish eggs that cost more than the fish — the most luxurious food that is also the weirdest. It means luxury is just a story we tell about salt and eggs. The story is delicious.", anchorQuestion: "What luxury in your life is just a story?", whoIsThisSoul: ["What is your caviar — the fancy thing you secretly think is weird?", "When did luxury last feel worth it?"], adventures: ["Eat caviar today, if you can. Or eat something fancy and pretend it is caviar.", "Be fancy for one bite. Just one."] },
  "07-19": { title: "National Daiquiri Day", tagline: "Daiquiris: the frozen vacation.", meaning: "National Daiquiri Day. A daiquiri is rum, lime, and ice blended into a frozen vacation — the drink that tastes like the beach. It means some drinks are trips. The daiquiri is one of them.", anchorQuestion: "Where would your daiquiri take you?", whoIsThisSoul: ["What is your daiquiri — the drink that is also a trip?", "When did a frozen drink last feel like a vacation?"], adventures: ["Drink a daiquiri today, if you drink. Frozen mandatory.", "If you do not drink, blend frozen fruit and call it a daiquiri."] },
  "07-20": { title: "National Moon Day", tagline: "The moon. We went there. We came back. We left a flag.", meaning: "National Moon Day, on the anniversary of the first moon landing. Humans went to the moon in a computer less powerful than your phone. It means impossible is just a word for not-yet. The moon is proof.", anchorQuestion: "What is your moon — the impossible thing you want to land on?", whoIsThisSoul: ["If you could go to the moon, would you?", "What small step would you take today toward your moon?"], adventures: ["Look at the moon tonight. Really look.", "Take one small step toward your impossible thing."] },
  "07-21": { title: "National Junk Food Day", tagline: "Junk food. No guilt. No rules. Today.", meaning: "National Junk Food Day. One day a year where junk food is not junk — it is the holiday. Chips, candy, soda, all of it. It means the rules are suspended. The junk is the point.", anchorQuestion: "What is your junk food — the one you would defend to a nutritionist?", whoIsThisSoul: ["What junk food do you love that you would never admit to?", "When did junk food last make a day better?"], adventures: ["Eat junk food today. Your favorite. No guilt.", "Skip the salad. Just today."] },
  "07-22": { title: "National Mango Day", tagline: "Mangoes: the fruit that fights back.", meaning: "National Mango Day. A mango is the only fruit that requires a strategy — peel, pit, juice everywhere. It means some fruits are worth the mess. The mango is one of them.", anchorQuestion: "What mango in your life is worth the mess?", whoIsThisSoul: ["What is your mango — the thing that is messy and worth it?", "When did you last eat a mango with your hands?"], adventures: ["Eat a mango today. With your hands. Mess mandatory.", "Cut it the fancy way. Or just bite it. Both count."] },
  "07-23": { title: "National Vanilla Ice Cream Day", tagline: "Vanilla: the flavor that is not a flavor. It is the standard.", meaning: "National Vanilla Ice Cream Day. Vanilla is called boring, but vanilla is the flavor every other flavor is built on — the foundation, the base, the one that never fails. It means vanilla is not plain. Vanilla is the standard.", anchorQuestion: "What vanilla in your life is actually the foundation?", whoIsThisSoul: ["Are you vanilla, or do you just play vanilla on TV?", "When did vanilla last beat the fancy flavor?"], adventures: ["Eat vanilla ice cream today. Plain. No toppings.", "Appreciate the vanilla. It is doing the work."] },
  "07-24": { title: "National Tequila Day", tagline: "Tequila: the shot that starts stories.", meaning: "National Tequila Day. Tequila is the shot that starts stories — salt, lime, and a decision. It means some drinks are beginnings. The tequila is one of them.", anchorQuestion: "What story did tequila start for you?", whoIsThisSoul: ["What is your tequila — the thing that starts stories?", "When did a shot last change the night?"], adventures: ["Drink tequila today, if you drink. Salt and lime mandatory.", "If you do not drink, eat lime with salt and call it research."] },
  "07-25": { title: "National Wine and Cheese Day", tagline: "Wine and cheese: the pairing that built civilization.", meaning: "National Wine and Cheese Day. Wine and cheese are the oldest pairing in the book — grapes and milk, fermented and aged, better together. It means some pairs are meant to be. The wine and cheese are proof.", anchorQuestion: "What is your wine and cheese — the pairing that just works?", whoIsThisSoul: ["Who is your cheese to your wine?", "When did a pairing last surprise you?"], adventures: ["Eat wine and cheese today. Pair them properly.", "Try a pairing you have never tried."] },
  "07-26": { title: "National Aunt and Uncle Day", tagline: "Aunts and uncles: the backup parents.", meaning: "National Aunt and Uncle Day. Aunts and uncles are the backup parents — the ones who spoil you, tell you the family secrets, and send you home sugared up. It means family has a bench. The aunts and uncles are the bench.", anchorQuestion: "Who was your favorite aunt or uncle, and why?", whoIsThisSoul: ["What aunt or uncle energy do you bring to the family?", "When did an aunt or uncle last save you?"], adventures: ["Contact an aunt or uncle today. Tell them they matter.", "Be the cool aunt or uncle today. Spoil someone."] },
  "07-27": { title: "National Scotch Day", tagline: "Scotch: the drink that takes its time.", meaning: "National Scotch Day. Scotch is whisky that waited — years in a barrel, in Scotland, in the dark. It means some things cannot be rushed. The scotch knows.", anchorQuestion: "What in your life is aging like scotch?", whoIsThisSoul: ["What is your scotch — the thing that took years and was worth it?", "When did waiting last pay off?"], adventures: ["Drink scotch today, if you drink. Neat. Sip it.", "If you do not drink, wait for something. The waiting is the drink."] },
  "07-28": { title: "National Hamburger Day", tagline: "Burgers. Again. Because one day was not enough.", meaning: "National Hamburger Day. A hamburger is the only food that works for a cookout, a drive-thru, a fancy restaurant, and 2 AM. It means some foods are universal. The burger is one of them.", anchorQuestion: "What is your burger order?", whoIsThisSoul: ["What is your burger — the thing that works everywhere?", "When did a burger last fix a bad day?"], adventures: ["Eat a hamburger today. Your way. No judgment.", "Grill one. Or drive-thru one. Both count."] },
  "07-29": { title: "National Chicken Wing Day", tagline: "Wings: the food that requires a wet wipe.", meaning: "National Chicken Wing Day. Wings are the only food that comes with a wet wipe — because the mess is part of the deal. It means some foods are meant to be eaten with your hands and your face. The wipe is the period.", anchorQuestion: "What is your wing flavor?", whoIsThisSoul: ["What is your chicken wing — the messy thing worth the wipe?", "When did wings last make a party?"], adventures: ["Eat chicken wings today. Sauce mandatory. Wet wipe mandatory.", "Try a flavor you have never had."] },
  "07-30": { title: "National Cheesecake Day", tagline: "Cheesecake: the dessert that means business.", meaning: "National Cheesecake Day. Cheesecake is the dessert that means business — dense, rich, and unapologetic. It means some desserts are not light. They are serious. The cheesecake is serious.", anchorQuestion: "What is your cheesecake — the serious dessert?", whoIsThisSoul: ["What dessert would you be — cheesecake, pie, or something light?", "When did cheesecake last settle an argument?"], adventures: ["Eat cheesecake today. Any flavor. All flavors.", "Eat it slowly. The cheesecake deserves it."] },
  "07-31": { title: "National Avocado Day", tagline: "Avocados: the fruit that is also a personality.", meaning: "National Avocado Day. Avocados are the fruit that became a personality — toast, guac, and a whole generation's identity. It means some foods are movements. The avocado is one of them.", anchorQuestion: "What is your avocado — the thing that became a personality?", whoIsThisSoul: ["When is an avocado perfect, and how do you know?", "What food became your identity?"], adventures: ["Eat avocado today. Toast, guac, or straight with salt.", "Cut it open at the perfect moment. That is the whole game."] },
  // ---- August ----
  "08-01": { title: "National Girlfriend Day", tagline: "Girlfriends. The ones who know everything.", meaning: "National Girlfriend Day. Girlfriends are the ones who know the stories, the secrets, and the version of you from before you were cool. It means friendship is a relationship. The girlfriend is the proof.", anchorQuestion: "Who is your girlfriend — the friend who knows everything?", whoIsThisSoul: ["What do your girlfriends know that nobody else does?", "When did a girlfriend last save you?"], adventures: ["Contact your girlfriends today. Tell them they matter.", "Do something with a girlfriend. Anything. Even nothing."] },
  "08-02": { title: "National Ice Cream Sandwich Day", tagline: "Ice cream sandwich: the portable party.", meaning: "National Ice Cream Sandwich Day. An ice cream sandwich is ice cream you can hold — the portable party. It means some desserts are meant to be handheld. The sandwich is the point.", anchorQuestion: "What is your ice cream sandwich — the portable version of joy?", whoIsThisSoul: ["What would you put between two cookies if you could put anything there?", "When did a sandwich last make you happy?"], adventures: ["Eat an ice cream sandwich today. Cookie or wafer — your call.", "Make one. Two cookies, ice cream, done."] },
  "08-03": { title: "National Watermelon Day", tagline: "Watermelon: summer you can eat.", meaning: "National Watermelon Day. Watermelon is summer you can eat — cold, sweet, and guaranteed to drip down your chin. It means some fruits are seasons. The watermelon is August.", anchorQuestion: "What tastes like summer to you?", whoIsThisSoul: ["What is your watermelon — the thing that drips down your chin?", "When did you last spit a watermelon seed?"], adventures: ["Eat watermelon today. Spit the seeds. That is the ritual.", "Have a seed-spitting contest. The record is the point."] },
  "08-04": { title: "National Chocolate Chip Cookie Day", tagline: "Chocolate chip cookies: the cookie that built an empire.", meaning: "National Chocolate Chip Cookie Day. The chocolate chip cookie was an accident — a baker ran out of nuts and chopped up a chocolate bar instead. It means the best inventions are accidents with good PR.", anchorQuestion: "What accident in your life turned out to be the best thing?", whoIsThisSoul: ["What is your chocolate chip cookie — the accident that became essential?", "When did running out of something lead to something better?"], adventures: ["Eat chocolate chip cookies today. Warm. With milk.", "Bake them. Or eat the dough. No judgment."] },
  "08-05": { title: "National Underwear Day", tagline: "Underwear. The foundation. Literally.", meaning: "National Underwear Day. Underwear is the foundation of every outfit — invisible, essential, and the first thing you put on. It means foundations matter, even when nobody sees them.", anchorQuestion: "What is your underwear — the foundation nobody sees?", whoIsThisSoul: ["What foundation in your life is invisible but essential?", "When did you last feel good in your underwear?"], adventures: ["Wear your favorite underwear today.", "Buy new underwear. You deserve it. Everyone does."] },
  "08-06": { title: "National Root Beer Float Day", tagline: "Root beer float: the fizzy, creamy, perfect thing.", meaning: "National Root Beer Float Day. A root beer float is root beer and vanilla ice cream — fizzy, creamy, and impossible to drink neatly. It means some drinks are meant to be messy. The float is the point.", anchorQuestion: "What is your root beer float — the fizzy, creamy combo?", whoIsThisSoul: ["What two things in your life fizz when they meet?", "When did a float last make a day better?"], adventures: ["Drink a root beer float today. Straw mandatory. Spoon mandatory.", "Make one with a root beer you have never tried."] },
  "08-07": { title: "National Raspberries in Cream Day", tagline: "Raspberries in cream: the simplest luxury.", meaning: "National Raspberries in Cream Day. Raspberries in cream is the simplest luxury — berries, cream, done. It means luxury does not need a recipe. The berries are the recipe.", anchorQuestion: "What is your raspberries in cream — the simple luxury?", whoIsThisSoul: ["When did simple last feel luxurious?", "What berry would you be?"], adventures: ["Eat raspberries in cream today. Fresh berries. Real cream.", "If there are no raspberries, eat any berry in cream."] },
  "08-08": { title: "National Frozen Custard Day", tagline: "Frozen custard: ice cream's richer cousin.", meaning: "National Frozen Custard Day. Frozen custard is ice cream with egg yolks — richer, denser, smoother. It means a little richness goes a long way. The custard is proof.", anchorQuestion: "What is your frozen custard — the richer version?", whoIsThisSoul: ["When did richness last beat lightness?", "What would you make richer if you could?"], adventures: ["Eat frozen custard today. Concrete if you can.", "Try a flavor you have never had."] },
  "08-09": { title: "National Book Lovers Day", tagline: "Books. The whole day. That is the post.", meaning: "National Book Lovers Day. Books are the only objects that contain whole worlds and fit on a shelf. It means reading is not a hobby. It is a portal.", anchorQuestion: "What book changed your life?", whoIsThisSoul: ["What are you reading right now — really?", "If your life were a book, what would the title be?"], adventures: ["Read today. Any book. Any page.", "Buy a book. Or borrow one. Or reread a favorite."] },
  "08-10": { title: "National S'mores Day", tagline: "S'mores: the campfire's greatest hit.", meaning: "National S'mores Day. A s'more is graham, chocolate, and marshmallow toasted over a fire — the only dessert that requires a campfire. It means some desserts are experiences. The s'more is one of them.", anchorQuestion: "What is your s'more — the dessert that is also an experience?", whoIsThisSoul: ["How do you like your marshmallow — golden or burnt?", "When did a campfire last make a memory?"], adventures: ["Eat a s'more today. Campfire if you can, microwave if you cannot.", "Toast a marshmallow. Golden or burnt — your call."] },
  "08-11": { title: "National Son and Daughter Day", tagline: "Sons and daughters. The whole reason.", meaning: "National Son and Daughter Day. Sons and daughters are the reason for everything — the whole point of the whole thing. It means parenting is not a job. It is a life.", anchorQuestion: "What do your kids teach you that nobody else can?", whoIsThisSoul: ["What would your kids say about you if they were honest?", "When did your kid last surprise you?"], adventures: ["Spend time with your kids today. Or call them.", "Tell them one thing you love about them. Specifics."] },
  "08-12": { title: "National Middle Child Day", tagline: "Middle children. The forgotten. The best.", meaning: "National Middle Child Day. Middle children are the forgotten ones — not the oldest, not the baby, just the middle. It means the middle is not nothing. The middle is the bridge.", anchorQuestion: "Are you a middle child? How does it show?", whoIsThisSoul: ["What does it feel like to be in the middle?", "When did being in the middle turn out to be the best spot?"], adventures: ["Celebrate a middle child today. They are usually overlooked.", "If you are a middle child, celebrate yourself. You deserve it."] },
  "08-13": { title: "International Left Handers Day", tagline: "Lefties. The right brain's favorite.", meaning: "International Left Handers Day. Left-handers live in a right-handed world — scissors, desks, spiral notebooks, all against them. It means the world is built for the majority, and the minority adapts. The lefties are the adapters.", anchorQuestion: "Are you left-handed? What does the world get wrong for you?", whoIsThisSoul: ["What is your left-handedness — the thing the world built wrong for you?", "When did adapting feel like a superpower?"], adventures: ["Try writing with your left hand today. Or your non-dominant hand.", "Use left-handed scissors. Feel the struggle."] },
  "08-14": { title: "National Creamsicle Day", tagline: "Creamsicle: the popsicle that grew up.", meaning: "National Creamsicle Day. A creamsicle is orange sherbet wrapped around vanilla ice cream — a popsicle that grew up. It means some things get better when they grow up. The creamsicle is proof.", anchorQuestion: "What creamsicle in your life grew up and got better?", whoIsThisSoul: ["What is your creamsicle — the thing that is better grown up?", "When did growing up last taste good?"], adventures: ["Eat a creamsicle today. Orange. Creamy. Cold.", "Make a creamsicle. Orange juice and vanilla ice cream. Done."] },
  "08-15": { title: "National Relaxation Day", tagline: "Relax. It is literally the assignment.", meaning: "National Relaxation Day. Relaxation is not laziness — it is maintenance. It means the body and mind need downtime the way a car needs an oil change. Today, change the oil.", anchorQuestion: "What does relaxation actually look like for you?", whoIsThisSoul: ["When did you last relax without guilt?", "What would you do if relaxation were your job?"], adventures: ["Relax today. Deliberately. With witnesses.", "Cancel one thing and replace it with nothing."] },
  "08-16": { title: "National Rum Day", tagline: "Rum: the pirate's choice. And yours.", meaning: "National Rum Day. Rum is the pirate's drink — sugar, molasses, and the sea. It means some drinks are adventures. The rum is one of them.", anchorQuestion: "What is your rum — the drink that is also an adventure?", whoIsThisSoul: ["If you were a pirate, what would your rum be?", "When did rum last start a story?"], adventures: ["Drink rum today, if you drink. With Coke. With pineapple. With lime.", "If you do not drink, eat pineapple and call it pirate food."] },
  "08-17": { title: "National Thrift Shop Day", tagline: "Thrift shops: where treasures hide.", meaning: "National Thrift Shop Day. Thrift shops are treasure hunts with price tags — the only stores where you might find a designer jacket next to a broken toaster. It means one person's junk is another person's treasure. The hunt is the point.", anchorQuestion: "What is your best thrift shop find?", whoIsThisSoul: ["What treasure are you hiding in a thrift shop somewhere?", "When did secondhand last beat new?"], adventures: ["Visit a thrift shop today. Buy something weird.", "Donate something. The cycle is the point."] },
  "08-18": { title: "National Ice Cream Pie Day", tagline: "Ice cream pie: the pie that is also ice cream.", meaning: "National Ice Cream Pie Day. An ice cream pie is pie and ice cream in one — the dessert that could not decide and decided to be both. It means indecision is not a flaw. It is a dessert.", anchorQuestion: "What in your life could not decide and became both?", whoIsThisSoul: ["What is your ice cream pie — the thing that is two things at once?", "When did not deciding turn out to be the right decision?"], adventures: ["Eat ice cream pie today. Any flavor. All flavors.", "Make one. Crust, ice cream, freezer. Done."] },
  "08-19": { title: "National Potato Day", tagline: "Potatoes: the world's most versatile vegetable.", meaning: "National Potato Day. A potato can be mashed, fried, baked, boiled, chipped, or hasselbacked — the most versatile vegetable on earth. It means humble things are powerful. The potato is proof.", anchorQuestion: "What is your potato — the humble thing that does everything?", whoIsThisSoul: ["How do you like your potatoes?", "When did a potato last save dinner?"], adventures: ["Eat potatoes today. Any style. All styles.", "Cook a potato a way you have never tried."] },
  "08-20": { title: "National Lemonade Day", tagline: "Lemonade: the drink that fixed a bad day.", meaning: "National Lemonade Day. Lemonade is lemons, sugar, and water — three ingredients that turn sour into sweet. It means when life gives you lemons, you make lemonade. The saying is the recipe.", anchorQuestion: "What lemons has life given you lately?", whoIsThisSoul: ["What is your lemonade — the thing you made from sour?", "When did sour last turn sweet?"], adventures: ["Drink lemonade today. Homemade if you can.", "Make lemonade. Squeeze the lemons yourself."] },
  "08-21": { title: "National Senior Citizens Day", tagline: "Seniors: the ones who lived it all.", meaning: "National Senior Citizens Day. Seniors are the ones who lived it — the wars, the weddings, the whole history. It means wisdom is not a book. It is a person. Listen to them.", anchorQuestion: "Who is the senior in your life with the best stories?", whoIsThisSoul: ["What would you ask a senior if you could ask anything?", "When did a senior last teach you something?"], adventures: ["Visit a senior today. Or call one.", "Listen to a story. Really listen."] },
  "08-22": { title: "National Tooth Fairy Day", tagline: "Check under the pillow. The fairy was here. Again.", meaning: "National Tooth Fairy Day. The Tooth Fairy is the only economy where losing a body part pays cash, and kids accept it without a single question. It means magic is just a story adults agree to keep telling — and the story is worth more than the coin.", anchorQuestion: "What magic did you believe in that you miss?", whoIsThisSoul: ["What would you leave under your pillow for the fairy today?", "When did you stop believing — and what would it take to start again?"], adventures: ["Leave a surprise under someone's pillow today.", "Tell a kid the Tooth Fairy story like you still believe it."] },
  "08-23": { title: "National Cuban Sandwich Day", tagline: "Cuban sandwich: pressed to perfection.", meaning: "National Cuban Sandwich Day. A Cuban sandwich is ham, pork, pickles, and mustard pressed flat — the only sandwich that gets better when you crush it. It means pressure is not always bad. The press is the point.", anchorQuestion: "What in your life gets better under pressure?", whoIsThisSoul: ["What is your Cuban sandwich — the thing that improves when pressed?", "When did pressure last make something better?"], adventures: ["Eat a Cuban sandwich today. Pressed. Hot. With pickles.", "Press something today. A sandwich, a flower, or a point."] },
  "08-24": { title: "National Peach Pie Day", tagline: "Peach pie: summer in a crust.", meaning: "National Peach Pie Day. Peach pie is summer in a crust — ripe peaches, sugar, and a flaky shell. It means some pies are seasons. The peach pie is August.", anchorQuestion: "What pie tastes like summer to you?", whoIsThisSoul: ["What is your peach pie — the thing that tastes like a season?", "When did a pie last make a day?"], adventures: ["Eat peach pie today. With ice cream. Obviously.", "Bake a peach pie. The crust is the whole game."] },
  "08-25": { title: "National Banana Split Day", tagline: "Banana split: the sundae that went big.", meaning: "National Banana Split Day. A banana split is a sundae that went big — three scoops, three sauces, and a banana as the foundation. It means go big or go home. The split is proof.", anchorQuestion: "What would you split if you could split anything?", whoIsThisSoul: ["What is your banana split — the thing that went big?", "When did going big last pay off?"], adventures: ["Eat a banana split today. Three scoops. Three sauces.", "Share it. A banana split is too big for one person."] },
  "08-26": { title: "National Dog Day", tagline: "Dogs. The whole day. That is the post.", meaning: "National Dog Day. Dogs are loyalty with fur — they love you when you are rich, poor, happy, sad, or wearing sweatpants for the third day. It means love does not require conditions. The dog is proof.", anchorQuestion: "What does your dog love about you?", whoIsThisSoul: ["If your dog could talk, what would it say about you?", "When did a dog last make a bad day better?"], adventures: ["Celebrate your dog today. Walk, treat, belly rub — the works.", "Adopt, foster, or donate to a shelter if you can."] },
  "08-27": { title: "National Just Because Day", tagline: "Just because. No reason. That is the reason.", meaning: "National Just Because Day. Just Because Day is the holiday for doing things for no reason — sending flowers, buying cake, calling someone, just because. It means you do not need a reason. Just because is the reason.", anchorQuestion: "What would you do just because?", whoIsThisSoul: ["When did you last do something just because?", "What just-because gift would you give someone?"], adventures: ["Do something today just because. No reason. No occasion.", "Send a just-because gift. Or a just-because text."] },
  "08-28": { title: "National Red Wine Day", tagline: "Red wine. The whole glass. The whole evening.", meaning: "National Red Wine Day. Red wine is grapes that aged in oak and came out complex — the drink that gets better when you wait. It means some things need time. The wine knows.", anchorQuestion: "What in your life is aging like red wine?", whoIsThisSoul: ["What is your red wine — the thing that got better with time?", "When did waiting last make something better?"], adventures: ["Drink red wine today, if you drink. Sip it. Taste it.", "If you do not drink, eat grapes. Same plant, same patience."] },
  "08-29": { title: "National Chop Suey Day", tagline: "Chop suey: the dish that is also a debate.", meaning: "National Chop Suey Day. Chop suey is a dish with a disputed history — Chinese, American, both, neither. It means food is never just food. It is history, migration, and a whole argument in a bowl.", anchorQuestion: "What dish in your life has a disputed history?", whoIsThisSoul: ["What is your chop suey — the thing with a history nobody agrees on?", "When did food last start an argument?"], adventures: ["Eat chop suey today. With rice. With chopsticks if you are brave.", "Learn one true thing about chop suey. The history is wild."] },
  "08-30": { title: "National Toasted Marshmallow Day", tagline: "Toasted marshmallows: the campfire's second act.", meaning: "National Toasted Marshmallow Day. A toasted marshmallow is a campfire's second act — golden outside, molten inside. It means some things are better toasted. The marshmallow is proof.", anchorQuestion: "Golden or burnt? This defines you.", whoIsThisSoul: ["What is your toasted marshmallow — the thing that is better toasted?", "When did a campfire last make a memory?"], adventures: ["Toast a marshmallow today. Golden or burnt — your call.", "Eat it immediately. Do not wait."] },
  "08-31": { title: "National Trail Mix Day", tagline: "Trail mix: the snack that goes everywhere.", meaning: "National Trail Mix Day. Trail mix is the snack that goes everywhere — hiking, driving, desk drawer. It means the best snacks are portable. The trail mix is proof.", anchorQuestion: "What is your trail mix — the snack that goes everywhere with you?", whoIsThisSoul: ["What is in your perfect trail mix?", "When did trail mix last save a hike — or a meeting?"], adventures: ["Eat trail mix today. Your mix. Your rules.", "Make a trail mix. Nuts, fruit, chocolate. Done."] },
  // ---- September ----
  "09-01": { title: "National No Rhyme or Reason Day", tagline: "No rhyme. No reason. Just today.", meaning: "National No Rhyme or Reason Day. A day for doing things with no rhyme and no reason — no plan, no purpose, no explanation. It means not everything needs a reason. Today, the lack of reason is the reason.", anchorQuestion: "What would you do today with no rhyme and no reason?", whoIsThisSoul: ["When did you last do something for no reason?", "What would you do if you did not need a reason?"], adventures: ["Do one thing today with no rhyme and no reason.", "Tell someone: no rhyme, no reason. Just because."] },
  "09-02": { title: "National Blueberry Popsicle Day", tagline: "Blueberry popsicles: summer's last stand.", meaning: "National Blueberry Popsicle Day. A blueberry popsicle is summer frozen on a stick — sweet, cold, and purple. It means summer does not end all at once. It melts slowly, on a stick.", anchorQuestion: "What summer thing are you holding onto?", whoIsThisSoul: ["What is your blueberry popsicle — the last taste of summer?", "When did you last eat a popsicle?"], adventures: ["Eat a blueberry popsicle today. Purple tongue required.", "Freeze blueberries. Eat them frozen. Same energy."] },
  "09-03": { title: "National Welsh Rarebit Day", tagline: "Welsh rarebit: cheese on toast with a fancy name.", meaning: "National Welsh Rarebit Day. Welsh rarebit is cheese on toast with a fancy name — the dish that proves naming something well makes it taste better. It means presentation is flavor. The name is the recipe.", anchorQuestion: "What would you rename to make it taste better?", whoIsThisSoul: ["What is your Welsh rarebit — the plain thing with a fancy name?", "When did a name change how something tasted?"], adventures: ["Eat Welsh rarebit today. Cheese on toast. Fancy name mandatory.", "Rename something ordinary today. Give it a fancy title."] },
  "09-04": { title: "National Wildlife Day", tagline: "Wildlife. The ones who were here first.", meaning: "National Wildlife Day. Wildlife are the ones who were here first — the animals, the birds, the whole ecosystem. It means the world is not ours. We are just renting it. The wildlife are the landlords.", anchorQuestion: "What wildlife do you share your world with?", whoIsThisSoul: ["What wild animal would you be?", "When did wildlife last surprise you?"], adventures: ["Watch wildlife today. Birds, squirrels, or anything wild.", "Learn about one endangered animal. Tell someone."] },
  "09-05": { title: "National Cheese Pizza Day", tagline: "Cheese pizza. The original. The only.", meaning: "National Cheese Pizza Day. Cheese pizza is the original — no toppings, no arguments, just cheese and crust. It means the original is not boring. The original is the standard.", anchorQuestion: "What is your cheese pizza — the original you never outgrow?", whoIsThisSoul: ["What topping would you add if you had to add one?", "When did plain last beat fancy?"], adventures: ["Eat cheese pizza today. No toppings. The cheese is the point.", "Make a pizza. Cheese only. No arguing."] },
  "09-06": { title: "National Read a Book Day", tagline: "Read a book. The whole day. That is the post.", meaning: "National Read a Book Day. A book is a whole world in your hands — and today the assignment is to open one. It means reading is not homework. It is a portal.", anchorQuestion: "What book are you reading right now — really?", whoIsThisSoul: ["What book would you reread forever?", "If your life were a book, what chapter are you in?"], adventures: ["Read a book today. Any book. Any page.", "Buy a book. Or borrow one. Or reread a favorite."] },
  "09-07": { title: "National Beer Lovers Day", tagline: "Beer. The whole day. Cheers.", meaning: "National Beer Lovers Day. Beer is one of the oldest drinks humans ever made — older than bread, older than most governments. It means gathering around a drink is one of the oldest human habits there is. Cheers to that.", anchorQuestion: "What are you toasting today?", whoIsThisSoul: ["What does beer mean to you — social, solo, or skip?", "When did a drink last mark a real moment?"], adventures: ["Drink a beer today, if you drink. Cheers someone.", "If you do not drink, toast with whatever you have. The toast is the point."] },
  "09-08": { title: "National Iguana Awareness Day", tagline: "Iguanas. The lizards with attitude.", meaning: "National Iguana Awareness Day. Iguanas are lizards with attitude — they stare, they bask, and they do not care what you think. It means attitude is a survival strategy. The iguana is proof.", anchorQuestion: "What iguana energy do you need today?", whoIsThisSoul: ["What is your iguana — the thing you bask in?", "When did attitude last save you?"], adventures: ["Watch an iguana video today. The basking ones are the best.", "Bask in the sun for ten minutes. Iguana style."] },
  "09-09": { title: "National Teddy Bear Day", tagline: "Teddy bears. The original comfort.", meaning: "National Teddy Bear Day. A teddy bear is the original comfort object — soft, silent, and always there. It means comfort does not need to be complicated. The bear is proof.", anchorQuestion: "What is your teddy bear — the comfort you still need?", whoIsThisSoul: ["When did a teddy bear last comfort you?", "What would your teddy bear say about you?"], adventures: ["Hug a teddy bear today. Or a pillow. Or a person.", "Give a teddy bear to someone. Comfort is a gift."] },
  "09-10": { title: "National Swap Ideas Day", tagline: "Swap an idea. Get a better one back.", meaning: "National Swap Ideas Day. Ideas are the only things that multiply when you give them away — swap one, get one back, now you have two. It means hoarding ideas is pointless. The swap is the point.", anchorQuestion: "What idea would you swap today?", whoIsThisSoul: ["What idea of yours deserves to be swapped?", "When did someone else's idea change yours?"], adventures: ["Swap an idea with someone today. Any idea.", "Write down one idea and give it away."] },
  "09-11": { title: "National Make Your Bed Day", tagline: "Make your bed. Start the day right.", meaning: "National Make Your Bed Day. Making your bed is the smallest win — two minutes, one bed, and the day starts with a victory. It means small wins compound. The bed is the first one.", anchorQuestion: "What small win would start your day right?", whoIsThisSoul: ["What does your bed say about your day?", "When did a small win last change your whole day?"], adventures: ["Make your bed today. Properly. Corners and all.", "Start the day with one small win. The bed counts."] },
  "09-12": { title: "National Chocolate Milkshake Day", tagline: "Chocolate milkshakes: the thick, cold, perfect thing.", meaning: "National Chocolate Milkshake Day. A chocolate milkshake is ice cream, milk, and chocolate blended into a thick, cold, perfect thing. It means some drinks are meals. The milkshake is one of them.", anchorQuestion: "What is your milkshake — the thick, cold, perfect thing?", whoIsThisSoul: ["What would you blend into a milkshake if you could blend anything?", "When did a milkshake last fix a day?"], adventures: ["Drink a chocolate milkshake today. Thick. Cold. With a straw.", "Make one. Ice cream, milk, chocolate. Done."] },
  "09-13": { title: "National Peanut Day", tagline: "Peanuts. The ballpark's favorite.", meaning: "National Peanut Day. Peanuts are the ballpark's favorite — salted, shelled, and scattered on the floor. It means some foods are places. The peanut is the ballpark.", anchorQuestion: "What food is a place for you?", whoIsThisSoul: ["What is your peanut — the snack that means a place?", "When did peanuts last mean a ballgame?"], adventures: ["Eat peanuts today. Salted. In the shell if you can.", "Crack them. Scatter the shells. Ballpark rules."] },
  "09-14": { title: "National Eat a Hoagie Day", tagline: "Hoagies: the sandwich that means business.", meaning: "National Eat a Hoagie Day. A hoagie is a sandwich that means business — long roll, cold cuts, and no nonsense. It means some sandwiches are meals. The hoagie is one of them.", anchorQuestion: "What is your hoagie order?", whoIsThisSoul: ["What is your hoagie — the sandwich that means business?", "When did a sandwich last feel like a meal?"], adventures: ["Eat a hoagie today. Your way. No judgment.", "Make a hoagie. Long roll. Cold cuts. Done."] },
  "09-15": { title: "National Linguine Day", tagline: "Linguine: the pasta that is also a tongue.", meaning: "National Linguine Day. Linguine means little tongues in Italian — the pasta that is also a body part. It means language is flavor. The linguine is proof.", anchorQuestion: "What pasta are you?", whoIsThisSoul: ["What does your tongue taste today?", "When did language last taste like pasta?"], adventures: ["Eat linguine today. With clams if you are brave.", "Learn one Italian word. Use it at dinner."] },
  "09-16": { title: "National Guacamole Day", tagline: "Guac: the dip that is also a meal.", meaning: "National Guacamole Day. Guacamole is the dip that is also a meal — avocados, lime, salt, and a whole party. It means some dips are destinations. The guac is one of them.", anchorQuestion: "What is your guac — the dip that is also a meal?", whoIsThisSoul: ["Chunky or smooth? This defines you.", "When did guac last make a party?"], adventures: ["Eat guacamole today. With chips. With a spoon. Both count.", "Make it fresh. Lime mandatory."] },
  "09-17": { title: "National Apple Dumpling Day", tagline: "Apple dumplings: the dessert in a blanket.", meaning: "National Apple Dumpling Day. An apple dumpling is an apple wrapped in pastry — a dessert in a blanket. It means wrapping things makes them better. The blanket is the point.", anchorQuestion: "What would you wrap in a blanket if you could?", whoIsThisSoul: ["What is your apple dumpling — the thing wrapped in comfort?", "When did a blanket last fix something?"], adventures: ["Eat an apple dumpling today. With ice cream. Obviously.", "Wrap something in a blanket. A person, a pet, or yourself."] },
  "09-18": { title: "National Cheeseburger Day", tagline: "Cheeseburgers. The burger, but better.", meaning: "National Cheeseburger Day. A cheeseburger is a hamburger that got a promotion — same burger, plus cheese. It means a little upgrade goes a long way. The cheese is the promotion.", anchorQuestion: "What is your cheeseburger upgrade?", whoIsThisSoul: ["What cheese makes a burger a cheeseburger?", "When did a small upgrade change everything?"], adventures: ["Eat a cheeseburger today. Your cheese. Your rules.", "Add cheese to something that did not have cheese. See what happens."] },
  "09-19": { title: "International Talk Like a Pirate Day", tagline: "Arrr. Talk like a pirate. All day.", meaning: "International Talk Like a Pirate Day. A day to talk like a pirate — arrr, matey, and all the rest. It means language is play. The pirate is the proof.", anchorQuestion: "What pirate phrase would you use all day?", whoIsThisSoul: ["If you were a pirate, what would your name be?", "When did talking silly last make a day better?"], adventures: ["Talk like a pirate today. All day. Arrr.", "Dress like a pirate. Eye patch optional, encouraged."] },
  "09-20": { title: "National Pepperoni Pizza Day", tagline: "Pepperoni pizza. The people's pizza.", meaning: "National Pepperoni Pizza Day. Pepperoni pizza is the people's pizza — the most ordered, the most loved, the most argued about. It means some foods are democracies. The pepperoni is the vote.", anchorQuestion: "What is your pepperoni pizza — the people's choice?", whoIsThisSoul: ["How much pepperoni is too much pepperoni? Trick question.", "When did pepperoni last win an argument?"], adventures: ["Eat pepperoni pizza today. Extra pepperoni.", "Order it. Do not make it. Today is for ordering."] },
  "09-21": { title: "National Pecan Cookie Day", tagline: "Pecan cookies: the nutty, buttery, perfect thing.", meaning: "National Pecan Cookie Day. A pecan cookie is a cookie with pecans — nutty, buttery, and guaranteed to crumble. It means nuts make cookies better. The pecan is proof.", anchorQuestion: "What nut makes everything better for you?", whoIsThisSoul: ["What is your pecan cookie — the thing with a little crunch?", "When did a cookie last make a day?"], adventures: ["Eat pecan cookies today. Crumbs mandatory.", "Bake them. Or buy them. Both count."] },
  "09-22": { title: "National Ice Cream Cone Day", tagline: "Ice cream cones: the edible cup.", meaning: "National Ice Cream Cone Day. An ice cream cone is ice cream in an edible cup — the only dessert that eats its own bowl. It means packaging can be delicious. The cone is the point.", anchorQuestion: "What cone would you pick — waffle, sugar, or cake?", whoIsThisSoul: ["What is your ice cream cone — the thing that eats its own bowl?", "When did a cone last leak on you?"], adventures: ["Eat ice cream in a cone today. Lick, do not bite.", "Let it drip. The drip is the ritual."] },
  "09-23": { title: "National Great American Pot Pie Day", tagline: "Pot pie: the meal in a crust.", meaning: "National Great American Pot Pie Day. A pot pie is a whole meal in a crust — meat, vegetables, gravy, all under a lid. It means comfort has a crust. The pot pie is proof.", anchorQuestion: "What is your pot pie — the comfort with a crust?", whoIsThisSoul: ["What would you put in a pot pie if you could put anything in it?", "When did a pot pie last fix a cold day?"], adventures: ["Eat pot pie today. Chicken, beef, or veggie.", "Break the crust. That is the best part."] },
  "09-24": { title: "National Cherries Jubilee Day", tagline: "Cherries jubilee: dessert on fire.", meaning: "National Cherries Jubilee Day. Cherries jubilee is cherries set on fire — dessert with a flamethrower. It means some desserts are performances. The fire is the point.", anchorQuestion: "What in your life deserves to be set on fire — safely?", whoIsThisSoul: ["What is your cherries jubilee — the dessert that performs?", "When did fire last make dessert better?"], adventures: ["Eat cherries jubilee today. Or any flaming dessert.", "If you cannot flame it, eat cherries. The cherries count."] },
  "09-25": { title: "National Lobster Day", tagline: "Lobster: the bug that became luxury.", meaning: "National Lobster Day. Lobster was once prison food — served to inmates so often they complained. Now it is luxury. It means value is a story. The lobster is proof.", anchorQuestion: "What lobster in your life went from prison food to luxury?", whoIsThisSoul: ["What is your lobster — the thing that changed value?", "When did you last eat something that used to be cheap?"], adventures: ["Eat lobster today, if you can. With butter. Lots of butter.", "If you cannot, eat something that used to be cheap and is now fancy."] },
  "09-26": { title: "National Pancake Day", tagline: "Pancakes. The stack that means morning.", meaning: "National Pancake Day. Pancakes are the stack that means morning — flour, eggs, milk, and a griddle. It means some foods are times of day. The pancake is morning.", anchorQuestion: "What is your pancake stack — how high, and with what on top?", whoIsThisSoul: ["What is your pancake — the thing that means morning?", "When did pancakes last make a morning?"], adventures: ["Eat pancakes today. Stack them. Syrup mandatory.", "Make them from scratch. Or from a box. Both count."] },
  "09-27": { title: "National Chocolate Milk Day", tagline: "Chocolate milk. The drink of champions.", meaning: "National Chocolate Milk Day. Chocolate milk is milk that decided to be fun — the drink of champions, kids, and everyone who never outgrew it. It means fun is not childish. The chocolate milk is proof.", anchorQuestion: "What is your chocolate milk — the fun thing you never outgrew?", whoIsThisSoul: ["When did you last drink chocolate milk?", "What childhood drink do you still love?"], adventures: ["Drink chocolate milk today. Cold. From a carton if you want.", "Dunk a cookie in it. That is the advanced move."] },
  "09-28": { title: "National Strawberry Cream Pie Day", tagline: "Strawberry cream pie: the pink, creamy, perfect thing.", meaning: "National Strawberry Cream Pie Day. Strawberry cream pie is pink, creamy, and perfect — the pie that looks like summer. It means some pies are colors. The strawberry cream pie is pink.", anchorQuestion: "What pie is your color?", whoIsThisSoul: ["What is your strawberry cream pie — the pink, creamy, perfect thing?", "When did a pie last look like a season?"], adventures: ["Eat strawberry cream pie today. Pink mandatory.", "If there is no pie, eat strawberries and cream. Same energy."] },
  "09-29": { title: "National Coffee Day", tagline: "Coffee. The whole day. That is the post.", meaning: "National Coffee Day. Coffee is the drink that runs the world — the morning ritual, the afternoon rescue, the whole economy in a cup. It means coffee is not a beverage. It is a system.", anchorQuestion: "How do you take your coffee?", whoIsThisSoul: ["What is your coffee — the ritual that runs your day?", "When did coffee last save you?"], adventures: ["Drink coffee today. Your way. No judgment.", "Try a coffee you have never had."] },
  "09-30": { title: "National Hot Mulled Cider Day", tagline: "Hot mulled cider: fall in a mug.", meaning: "National Hot Mulled Cider Day. Hot mulled cider is fall in a mug — apples, spices, and warmth. It means some drinks are seasons. The cider is fall.", anchorQuestion: "What drink tastes like fall to you?", whoIsThisSoul: ["What is your hot mulled cider — the drink that means fall?", "When did a mug last warm more than your hands?"], adventures: ["Drink hot mulled cider today. Spices mandatory.", "Simmer it on the stove. The smell is the point."] },
  // ---- October ----
  "10-01": { title: "International Coffee Day", tagline: "Coffee. Again. Because one day was not enough.", meaning: "International Coffee Day. Coffee is the drink that runs the world — the morning ritual, the afternoon rescue, the whole economy in a cup. It means coffee is not a beverage. It is a system.", anchorQuestion: "How do you take your coffee?", whoIsThisSoul: ["What is your coffee — the ritual that runs your day?", "When did coffee last save you?"], adventures: ["Drink coffee today. Your way. No judgment.", "Try a coffee you have never had."] },
  "10-02": { title: "National Fried Scallops Day", tagline: "Fried scallops: the sea's little pillows.", meaning: "National Fried Scallops Day. Fried scallops are the sea's little pillows — sweet, tender, and fried to a golden crisp. It means some seafood is comfort food. The scallop is proof.", anchorQuestion: "What seafood comforts you?", whoIsThisSoul: ["What is your fried scallop — the sea's little pillow?", "When did seafood last feel like comfort?"], adventures: ["Eat fried scallops today. Golden. Crispy.", "If you do not eat seafood, eat a pillow-shaped food."] },
  "10-03": { title: "National Boyfriend Day", tagline: "Boyfriends. The ones who know everything.", meaning: "National Boyfriend Day. Boyfriends are the ones who know the stories, the secrets, and the version of you from before you were cool. It means partnership is a relationship. The boyfriend is the proof.", anchorQuestion: "Who is your boyfriend — the partner who knows everything?", whoIsThisSoul: ["What do your partners know that nobody else does?", "When did a boyfriend last save you?"], adventures: ["Contact your boyfriend today. Tell him he matters.", "Do something with a boyfriend. Anything. Even nothing."] },
  "10-04": { title: "National Taco Day", tagline: "Tacos. The only food that needs no occasion.", meaning: "National Taco Day. Tacos are the only food that works for every meal, every mood, and every Tuesday. It means some foods are universal. The taco is one of them.", anchorQuestion: "What is your taco order?", whoIsThisSoul: ["What is your taco — the thing that works everywhere?", "When did a taco last fix a bad day?"], adventures: ["Eat tacos today. Your way. No judgment.", "Try a taco you have never had."] },
  "10-05": { title: "National Do Something Nice Day", tagline: "Do something nice. For no reason.", meaning: "National Do Something Nice Day. Do something nice — for a stranger, a friend, or yourself. It means niceness is not weakness. It is a choice.", anchorQuestion: "What nice thing could you do today?", whoIsThisSoul: ["When did niceness last change your day?", "What nice thing would you do if nobody was watching?"], adventures: ["Do something nice today. Small counts.", "Do it without telling anyone. The secret is the point."] },
  "10-06": { title: "National Noodle Day", tagline: "Noodles. The slurp heard around the world.", meaning: "National Noodle Day. Noodles are the only food you slurp — long, twirly, and impossible to eat quietly. It means some foods are sounds. The noodle is a slurp.", anchorQuestion: "What is your noodle — the food you slurp?", whoIsThisSoul: ["What noodle would you be — spaghetti, ramen, or something else?", "When did a noodle last make you happy?"], adventures: ["Eat noodles today. Slurp loudly. That is the rule.", "Try a noodle you have never had."] },
  "10-07": { title: "National Frappe Day", tagline: "Frappe: the coffee that is also dessert.", meaning: "National Frappe Day. A frappe is coffee blended with ice until it becomes dessert — the drink that could not decide. It means indecision is delicious. The frappe is proof.", anchorQuestion: "What is your frappe — the thing that could not decide?", whoIsThisSoul: ["Coffee or dessert? Why not both?", "When did blending two things make something better?"], adventures: ["Drink a frappe today. Blended. Cold. With whipped cream.", "Blend something unexpected. See what happens."] },
  "10-08": { title: "National Pierogi Day", tagline: "Pierogi: the dumpling that means home.", meaning: "National Pierogi Day. Pierogi are dumplings filled with potato, cheese, or meat — the food that means home in a dozen countries. It means dumplings are universal. The pierogi is proof.", anchorQuestion: "What dumpling means home to you?", whoIsThisSoul: ["What is your pierogi — the dumpling that means home?", "When did a dumpling last make you feel at home?"], adventures: ["Eat pierogi today. With sour cream. With onions.", "Make them. Or buy them. Both count."] },
  "10-09": { title: "National Moldy Cheese Day", tagline: "Moldy cheese: the cheese that went too far. On purpose.", meaning: "National Moldy Cheese Day. Moldy cheese is cheese that went too far — blue veins, funky smell, and a flavor that divides rooms. It means going too far is sometimes the point. The mold is the flavor.", anchorQuestion: "What in your life went too far and got better?", whoIsThisSoul: ["What is your moldy cheese — the thing that is better funky?", "When did too far turn out to be just right?"], adventures: ["Eat moldy cheese today. Blue, brie, or anything funky.", "If you hate moldy cheese, eat a cheese you have never tried."] },
  "10-10": { title: "National Angel Food Cake Day", tagline: "Angel food cake: the cake that floats.", meaning: "National Angel Food Cake Day. Angel food cake is the cake that floats — light, airy, and fat-free. It means some cakes are clouds. The angel food is proof.", anchorQuestion: "What floats in your life?", whoIsThisSoul: ["Are you angel food or devil's food?", "When did light last beat heavy?"], adventures: ["Eat angel food cake today. With strawberries. With cream.", "Eat it lightly. The cake is a cloud."] },
  "10-11": { title: "National Sausage Pizza Day", tagline: "Sausage pizza. The hearty pizza.", meaning: "National Sausage Pizza Day. Sausage pizza is the hearty pizza — meat, cheese, and a crust that can hold it all. It means some pizzas are meals. The sausage pizza is one of them.", anchorQuestion: "What is your sausage pizza — the hearty version?", whoIsThisSoul: ["What topping makes a pizza a meal?", "When did a pizza last feel like a feast?"], adventures: ["Eat sausage pizza today. Hearty. Hot.", "Add sausage to a pizza that did not have sausage."] },
  "10-12": { title: "National Gumbo Day", tagline: "Gumbo: the stew that is also a history.", meaning: "National Gumbo Day. Gumbo is a stew that is also a history — African, French, Spanish, and Native, all in one pot. It means food is history. The gumbo is proof.", anchorQuestion: "What gumbo is your life — the mix that should not work but does?", whoIsThisSoul: ["What is your gumbo — the stew that is also a history?", "When did a mix last become something new?"], adventures: ["Eat gumbo today. With rice. With hot sauce.", "Learn one true thing about gumbo. The history is the recipe."] },
  "10-13": { title: "National No Bra Day", tagline: "No bra. No rules. No apologies.", meaning: "National No Bra Day. A day to skip the bra — for comfort, for awareness, for the sheer relief of it. It means comfort is not a luxury. It is a right. Take the bra off.", anchorQuestion: "What would you take off today if comfort were the rule?", whoIsThisSoul: ["What uncomfortable thing are you wearing — literally or otherwise?", "When did comfort last feel like rebellion?"], adventures: ["Skip the bra today. Or skip any uncomfortable thing.", "Be comfortable on purpose. That is the holiday."] },
  "10-14": { title: "National Dessert Day", tagline: "Dessert. The whole day. That is the post.", meaning: "National Dessert Day. Dessert is the meal after the meal — the part you actually wanted. It means dessert is not extra. Dessert is the point.", anchorQuestion: "What is your dessert — the part you actually wanted?", whoIsThisSoul: ["What dessert would you eat all day if you could?", "When did dessert last come first?"], adventures: ["Eat dessert today. Any dessert. All desserts.", "Eat dessert first. The meal can wait."] },
  "10-15": { title: "National Cheese Curd Day", tagline: "Cheese curds: the squeaky, salty, perfect thing.", meaning: "National Cheese Curd Day. Cheese curds are cheese that squeaks — fresh, salty, and impossible to eat quietly. It means some cheese is noise. The curd is proof.", anchorQuestion: "What squeaks in your life?", whoIsThisSoul: ["What is your cheese curd — the squeaky, salty, perfect thing?", "When did cheese last make a sound?"], adventures: ["Eat cheese curds today. Fresh. Squeaky.", "If you cannot find curds, eat cheese that squeaks."] },
  "10-16": { title: "World Food Day", tagline: "Food. The thing that feeds the world.", meaning: "World Food Day. Food is the thing that feeds the world — and the fact that not everyone has enough is the whole point of the day. It means food is not just fuel. It is justice.", anchorQuestion: "What would you do if everyone had enough food?", whoIsThisSoul: ["What does food mean to you beyond fuel?", "When did food last feel like justice?"], adventures: ["Eat today. And share food with someone who needs it.", "Donate food. Or money for food. The sharing is the point."] },
  "10-17": { title: "National Pasta Day", tagline: "Pasta. The whole day. That is the post.", meaning: "National Pasta Day. Pasta is the food that works for every mood — comfort, celebration, Tuesday. It means some foods are universal. The pasta is one of them.", anchorQuestion: "What is your pasta — the food for every mood?", whoIsThisSoul: ["What pasta shape are you?", "When did pasta last fix a day?"], adventures: ["Eat pasta today. Any shape. All shapes.", "Twirl it. No cutting allowed."] },
  "10-18": { title: "National Chocolate Cupcake Day", tagline: "Chocolate cupcakes: the cake you can hold.", meaning: "National Chocolate Cupcake Day. A chocolate cupcake is cake you can hold — the portable celebration. It means some cakes are meant to be handheld. The cupcake is proof.", anchorQuestion: "What is your cupcake — the portable celebration?", whoIsThisSoul: ["What would you put on a cupcake if you could put anything on it?", "When did a cupcake last make a day?"], adventures: ["Eat a chocolate cupcake today. Frosting mandatory.", "Lick the frosting first. That is the rule."] },
  "10-19": { title: "National New Friends Day", tagline: "New friends. Say hi. It might stick.", meaning: "National New Friends Day. New friends are the ones you have not met yet — the people who will change your life and you do not know their names. It means friendship is not finished. The new friends are coming.", anchorQuestion: "Who is a new friend you have not met yet?", whoIsThisSoul: ["When did you last make a new friend?", "What would you say to a stranger who might become a friend?"], adventures: ["Say hi to someone new today. One sentence counts.", "Message someone you have been meaning to reconnect with."] },
  "10-20": { title: "National Brandied Fruit Day", tagline: "Brandied fruit: the fruit that got fancy.", meaning: "National Brandied Fruit Day. Brandied fruit is fruit soaked in brandy until it becomes something else — dessert, topping, or a whole mood. It means soaking changes things. The brandy is proof.", anchorQuestion: "What are you soaking in right now?", whoIsThisSoul: ["What is your brandied fruit — the thing that got fancy by soaking?", "When did soaking last change something?"], adventures: ["Eat brandied fruit today. Or any fruit with a kick.", "Soak something. Fruit, or a thought."] },
  "10-21": { title: "National Pumpkin Cheesecake Day", tagline: "Pumpkin cheesecake: fall in a dessert.", meaning: "National Pumpkin Cheesecake Day. Pumpkin cheesecake is fall in a dessert — pumpkin, spice, and cream cheese. It means some desserts are seasons. The pumpkin cheesecake is fall.", anchorQuestion: "What dessert tastes like fall to you?", whoIsThisSoul: ["What is your pumpkin cheesecake — the fall dessert?", "When did fall last taste this good?"], adventures: ["Eat pumpkin cheesecake today. Spices mandatory.", "If there is no cheesecake, eat pumpkin anything."] },
  "10-22": { title: "National Nut Day", tagline: "Nuts. The whole day. Go nuts.", meaning: "National Nut Day. Nuts are the snack that goes everywhere — hiking, driving, desk drawer. It means the best snacks are portable. The nut is proof.", anchorQuestion: "What nut are you?", whoIsThisSoul: ["What is your nut — the snack that goes everywhere?", "When did you last go nuts?"], adventures: ["Eat nuts today. Any kind. All kinds.", "Go nuts today. Just a little."] },
  "10-23": { title: "National Boston Cream Pie Day", tagline: "Boston cream pie: the cake that is also a pie.", meaning: "National Boston Cream Pie Day. Boston cream pie is a cake that calls itself a pie — the dessert that could not decide. It means names lie. The cake is proof.", anchorQuestion: "What in your life is misnamed?", whoIsThisSoul: ["What is your Boston cream pie — the thing that is two things at once?", "When did a name last lie to you?"], adventures: ["Eat Boston cream pie today. Cake or pie — your call.", "Call something by the wrong name today. See what happens."] },
  "10-24": { title: "National Bologna Day", tagline: "Bologna: the sandwich meat of childhood.", meaning: "National Bologna Day. Bologna is the sandwich meat of childhood — fried, flat, and eaten on white bread with mustard. It means some foods are memories. The bologna is proof.", anchorQuestion: "What bologna memory do you have?", whoIsThisSoul: ["What is your bologna — the childhood food you still love?", "When did a sandwich last take you back?"], adventures: ["Eat a bologna sandwich today. Fried if you are brave.", "Eat it on white bread. With mustard. Childhood rules."] },
  "10-25": { title: "World Pasta Day", tagline: "Pasta. The world agrees. Again.", meaning: "World Pasta Day. Pasta is the food the whole world agrees on — every country has a noodle, and every noodle is right. It means some foods are universal. The pasta is one of them.", anchorQuestion: "What noodle from another country would you try?", whoIsThisSoul: ["What is your pasta — the food the world agrees on?", "When did a noodle last cross a border for you?"], adventures: ["Eat pasta today. Any country. Any shape.", "Try a noodle from a country you have never visited."] },
  "10-26": { title: "National Pumpkin Day", tagline: "Pumpkins. The whole day. Carve one.", meaning: "National Pumpkin Day. Pumpkins are fall — carving, pie, seeds, and a whole season in one orange globe. It means some vegetables are seasons. The pumpkin is fall.", anchorQuestion: "What would you carve into a pumpkin?", whoIsThisSoul: ["What is your pumpkin — the thing that means fall?", "When did a pumpkin last make a season?"], adventures: ["Carve a pumpkin today. Or eat pumpkin anything.", "Roast the seeds. Salt mandatory."] },
  "10-27": { title: "National American Beer Day", tagline: "American beer. The whole day. Cheers.", meaning: "National American Beer Day. American beer is the beer that built a country — light, cold, and best consumed at a cookout. It means some drinks are places. The American beer is America.", anchorQuestion: "What are you toasting today?", whoIsThisSoul: ["What does American beer mean to you?", "When did a beer last feel like a place?"], adventures: ["Drink an American beer today, if you drink. Cheers someone.", "If you do not drink, toast with whatever you have. The toast is the point."] },
  "10-28": { title: "National Chocolate Day", tagline: "Chocolate. The whole day. No apologies.", meaning: "National Chocolate Day. Chocolate is the food that needs no occasion — the answer to every question, the fix for every mood. It means chocolate is not a treat. Chocolate is a system.", anchorQuestion: "What chocolate fixes your day?", whoIsThisSoul: ["What is your chocolate — the thing that fixes every mood?", "When did chocolate last save you?"], adventures: ["Eat chocolate today. Dark, milk, or white. All count.", "Eat it slowly. The chocolate deserves it."] },
  "10-29": { title: "National Cat Day", tagline: "Cats. The whole day. They own it.", meaning: "National Cat Day. Cats own the day — they own every day, actually, and they let us live here. It means the cat is not a pet. The cat is the landlord.", anchorQuestion: "What does your cat think of you?", whoIsThisSoul: ["If your cat could talk, what would it say about your week?", "When did a cat last make a bad day better?"], adventures: ["Celebrate your cat today. Treat, nap, sunbeam — the works.", "If you have no cat, admire one. From a distance. They prefer it."] },
  "10-30": { title: "National Candy Corn Day", tagline: "Candy corn: love it or hate it. There is no middle.", meaning: "National Candy Corn Day. Candy corn is the most divisive candy on earth — people either love it or act like you served them a punishment. It means some candy is not for everyone, and that is fine. The candy corn does not care.", anchorQuestion: "Candy corn: love or hate? Defend your answer.", whoIsThisSoul: ["What do you love that other people think is gross?", "When did you last change your mind about candy?"], adventures: ["Eat candy corn today. Love it or hate it. Both count.", "If you hate it, eat one anyway. Today is the day."] },
  "10-31": { title: "Halloween", tagline: "Trick or treat. Costumes. Candy. Chaos.", meaning: "Halloween. The night when everyone gets to be someone else — costumes, candy, and a whole evening of pretending. It means masks are not just for hiding. Sometimes they are for revealing.", anchorQuestion: "What would you dress up as if judgment did not exist?", whoIsThisSoul: ["What mask do you wear every day that Halloween lets you take off?", "When did a costume last reveal the real you?"], adventures: ["Wear a costume today. Any costume. Even a hat counts.", "Eat candy. Trick or treat. Be someone else for a night."] },
  // ---- November ----
  "11-01": { title: "National Cinnamon Day", tagline: "Cinnamon: the spice that means fall.", meaning: "National Cinnamon Day. Cinnamon is the spice that means fall — warm, sweet, and in everything from rolls to lattes. It means some spices are seasons. The cinnamon is fall.", anchorQuestion: "What spice means fall to you?", whoIsThisSoul: ["What is your cinnamon — the spice that means a season?", "When did cinnamon last make a day?"], adventures: ["Eat something with cinnamon today. Rolls, toast, or oatmeal.", "Smell cinnamon. The smell is the holiday."] },
  "11-02": { title: "National Deviled Egg Day", tagline: "Deviled eggs: the appetizer that is also a debate.", meaning: "National Deviled Egg Day. Deviled eggs are the appetizer that is also a debate — paprika or no paprika, sweet or dill, two halves or three. It means some foods are arguments. The deviled egg is proof.", anchorQuestion: "What is your deviled egg recipe?", whoIsThisSoul: ["What is your deviled egg — the thing with a correct answer everyone argues about?", "When did a deviled egg last start an argument?"], adventures: ["Eat deviled eggs today. Paprika mandatory.", "Make them. Or buy them. Both count."] },
  "11-03": { title: "National Sandwich Day", tagline: "Sandwiches. The whole day. That is the post.", meaning: "National Sandwich Day. A sandwich is the only food that works for every meal, every budget, and every mood. It means some foods are universal. The sandwich is one of them.", anchorQuestion: "What is your sandwich order?", whoIsThisSoul: ["What is your sandwich — the thing that works everywhere?", "When did a sandwich last fix a bad day?"], adventures: ["Eat a sandwich today. Your way. No judgment.", "Make a sandwich with something unexpected."] },
  "11-04": { title: "National Candy Day", tagline: "Candy. The whole day. No apologies.", meaning: "National Candy Day. Candy is the food that needs no occasion — sweet, colorful, and best eaten by the handful. It means candy is not a treat. Candy is a system.", anchorQuestion: "What candy fixes your day?", whoIsThisSoul: ["What is your candy — the thing that fixes every mood?", "When did candy last save you?"], adventures: ["Eat candy today. Your favorite. By the handful.", "Share candy with someone. Candy is better shared."] },
  "11-05": { title: "National Donut Day", tagline: "Donuts. The whole day. (The other one is in June.)", meaning: "National Donut Day. There are two Donut Days — one in June, one in November — because donuts deserve two. It means some foods are worth celebrating twice. The donut is one of them.", anchorQuestion: "What deserves two holidays in your life?", whoIsThisSoul: ["What is your donut — the thing worth celebrating twice?", "When did a donut last make a day?"], adventures: ["Eat a donut today. Any donut. All donuts.", "Buy a dozen. Share them. Or do not."] },
  "11-06": { title: "National Nachos Day", tagline: "Nachos: the snack that is also a meal.", meaning: "National Nachos Day. Nachos are the snack that is also a meal — chips, cheese, and everything else, piled high. It means some snacks are feasts. The nachos are proof.", anchorQuestion: "What is your nacho topping?", whoIsThisSoul: ["What is your nacho — the snack that is also a meal?", "When did nachos last make a party?"], adventures: ["Eat nachos today. Piled high. Cheese mandatory.", "Build the tallest nacho stack you can."] },
  "11-07": { title: "National Bittersweet Chocolate with Almonds Day", tagline: "Bittersweet chocolate. Almonds. The sophisticated combo.", meaning: "National Bittersweet Chocolate with Almonds Day. Bittersweet chocolate with almonds is the sophisticated combo — dark, nutty, and a little bitter. It means sophistication is just bitterness plus nuts. The chocolate is proof.", anchorQuestion: "What is your bittersweet combo?", whoIsThisSoul: ["What is your bittersweet chocolate with almonds — the sophisticated thing?", "When did bitter last taste good?"], adventures: ["Eat bittersweet chocolate with almonds today.", "Be sophisticated for one bite. Just one."] },
  "11-08": { title: "National Cappuccino Day", tagline: "Cappuccino: the coffee with a foam hat.", meaning: "National Cappuccino Day. A cappuccino is espresso with a foam hat — the coffee that dressed up. It means foam matters. The hat is the drink.", anchorQuestion: "What is your cappuccino — the coffee with a hat?", whoIsThisSoul: ["What hat would you wear if you were a cappuccino?", "When did foam last make a drink?"], adventures: ["Drink a cappuccino today. Foam mandatory.", "Make latte art. Or just foam. Foam counts."] },
  "11-09": { title: "National Scrapple Day", tagline: "Scrapple: the breakfast meat with a past.", meaning: "National Scrapple Day. Scrapple is the breakfast meat with a past — pork, cornmeal, and a history nobody wants to explain. It means some foods are mysteries. The scrapple is proof.", anchorQuestion: "What scrapple in your life has a past nobody wants to explain?", whoIsThisSoul: ["What is your scrapple — the thing with a mysterious past?", "When did mystery last taste good?"], adventures: ["Eat scrapple today, if you can. Or any breakfast meat with a past.", "Learn one true thing about scrapple. The history is wild."] },
  "11-10": { title: "National Vanilla Cupcake Day", tagline: "Vanilla cupcakes: the plain cake that is not plain.", meaning: "National Vanilla Cupcake Day. A vanilla cupcake is the plain cake that is not plain — vanilla is the flavor every other flavor is built on. It means vanilla is not boring. Vanilla is the foundation.", anchorQuestion: "What vanilla in your life is actually the foundation?", whoIsThisSoul: ["What is your vanilla cupcake — the plain thing that is not plain?", "When did vanilla last beat the fancy flavor?"], adventures: ["Eat a vanilla cupcake today. Frosting mandatory.", "Appreciate the vanilla. It is doing the work."] },
  "11-11": { title: "Veterans Day", tagline: "Veterans. Thank them. Mean it.", meaning: "Veterans Day. A day to thank the people who served — not with a sale, not with a post, but with actual gratitude. It means service is not a slogan. It is a person.", anchorQuestion: "Who served that you know?", whoIsThisSoul: ["What does service mean to you?", "When did a veteran last teach you something?"], adventures: ["Thank a veteran today. In person if you can.", "Listen to a veteran's story. Really listen."] },
  "11-12": { title: "National Pizza with the Works Except Anchovies Day", tagline: "Pizza with everything. Except anchovies. Obviously.", meaning: "National Pizza with the Works Except Anchovies Day. The longest holiday name ever, for a pizza with everything except the one topping nobody wants. It means anchovies are the line. The pizza is the proof.", anchorQuestion: "What is your anchovy — the topping you would ban?", whoIsThisSoul: ["What would you put on a pizza with the works?", "When did a topping last start an argument?"], adventures: ["Eat pizza with the works today. No anchovies.", "If you love anchovies, add them. Rebel."] },
  "11-13": { title: "World Kindness Day", tagline: "Kindness. The whole world. One day.", meaning: "World Kindness Day. Kindness without a reason is the only kind that counts, because the second it has a reason it is strategy. It means one small, anonymous good deed can reroute a stranger's whole day.", anchorQuestion: "What kindness could you do today that nobody would ever know about?", whoIsThisSoul: ["When did a stranger's kindness change your day?", "What would you do if kindness were the only currency?"], adventures: ["Do one random act of kindness today. Do not tell anyone.", "Pay for a stranger's coffee, hold a door, leave a kind note."] },
  "11-14": { title: "National Pickle Day", tagline: "Pickles. The crunchy, sour, perfect thing.", meaning: "National Pickle Day. Pickles are cucumbers that went through a transformation and came out better — sour, crunchy, and unapologetic. It means transformation takes brine. The pickle knows.", anchorQuestion: "What pickle are you — dill, sweet, or spicy?", whoIsThisSoul: ["What is your pickle — the thing that got better by soaking?", "When did sour last turn into something you loved?"], adventures: ["Eat pickles today. Crunchy. Sour. With a sandwich.", "Try a pickle you have never had."] },
  "11-15": { title: "National Clean Out Your Refrigerator Day", tagline: "The fridge is a crime scene. Clean it.", meaning: "National Clean Out Your Refrigerator Day. Your fridge is a crime scene — leftovers from last month, condiments from 2019, and something growing in the back. It means cleaning is not punishment. It is archaeology.", anchorQuestion: "What is the oldest thing in your fridge?", whoIsThisSoul: ["What does your fridge say about you?", "When did cleaning the fridge last feel like therapy?"], adventures: ["Clean out your fridge today. Throw away the science experiments.", "Find one thing you forgot you had. Eat it or toss it."] },
  "11-16": { title: "National Fast Food Day", tagline: "Fast food. No guilt. No rules. Today.", meaning: "National Fast Food Day. Fast food is the meal that comes in a bag — quick, salty, and exactly what you wanted. It means sometimes fast is right. The bag is the point.", anchorQuestion: "What is your fast food order?", whoIsThisSoul: ["What is your fast food — the quick thing that hits the spot?", "When did fast food last save a day?"], adventures: ["Eat fast food today. Your order. No guilt.", "Drive-thru it. The drive-thru is the ritual."] },
  "11-17": { title: "National Homemade Bread Day", tagline: "Homemade bread: the smell that means home.", meaning: "National Homemade Bread Day. Homemade bread is flour, water, and time — the smell that means home. It means the simplest things are the most powerful. The bread is proof.", anchorQuestion: "What smells like home to you?", whoIsThisSoul: ["What is your homemade bread — the simple thing that means home?", "When did bread last make a house a home?"], adventures: ["Bake bread today. Any bread. The smell is the point.", "If you cannot bake, buy fresh bread. Warm it. Smell it."] },
  "11-18": { title: "National Princess Day", tagline: "Princesses. The tiaras. The attitude. All of it.", meaning: "National Princess Day. A princess is not a crown — it is an attitude. It means you do not need a castle to be a princess. You need a tiara and the attitude to match.", anchorQuestion: "What princess energy do you need today?", whoIsThisSoul: ["What is your princess — the version of you with a tiara?", "When did you last feel like royalty?"], adventures: ["Wear a tiara today. Or a crown. Or a paper crown.", "Be a princess for an hour. Attitude mandatory."] },
  "11-19": { title: "National Macchiato Day", tagline: "Macchiato: the espresso with a mark.", meaning: "National Macchiato Day. A macchiato is espresso marked with foam — macchiato means marked in Italian. It means a small mark changes everything. The foam is the mark.", anchorQuestion: "What mark would you leave?", whoIsThisSoul: ["What is your macchiato — the thing with a small mark that changes it?", "When did a small mark make a big difference?"], adventures: ["Drink a macchiato today. Foam mark mandatory.", "Leave a mark today. A note, a signature, or a footprint."] },
  "11-20": { title: "National Peanut Butter Fudge Day", tagline: "Peanut butter fudge: the fudge that is also peanut butter.", meaning: "National Peanut Butter Fudge Day. Peanut butter fudge is fudge that is also peanut butter — two great tastes that decided to be one. It means some combos are inevitable. The fudge is proof.", anchorQuestion: "What two great tastes would you combine?", whoIsThisSoul: ["What is your peanut butter fudge — the combo that was inevitable?", "When did two things last become one great thing?"], adventures: ["Eat peanut butter fudge today. Creamy. Sweet. With nuts if you are brave.", "Combine two things you love. See what happens."] },
  "11-21": { title: "National Stuffing Day", tagline: "Stuffing: the side dish that is the main event.", meaning: "National Stuffing Day. Stuffing is the side dish that is the main event — bread, herbs, and butter, and the reason Thanksgiving works. It means the side dish can be the star. The stuffing is proof.", anchorQuestion: "What side dish in your life is actually the main event?", whoIsThisSoul: ["What is your stuffing — the side that steals the show?", "When did a side dish last outshine the main?"], adventures: ["Eat stuffing today. With gravy. Obviously.", "Make stuffing. The herbs are the whole game."] },
  "11-22": { title: "National Cranberry Relish Day", tagline: "Cranberry relish: the tart, sweet, perfect thing.", meaning: "National Cranberry Relish Day. Cranberry relish is tart, sweet, and the only thing on the Thanksgiving table with a bite. It means tart is a flavor. The relish is proof.", anchorQuestion: "What tart thing in your life do you love?", whoIsThisSoul: ["What is your cranberry relish — the tart thing that balances the meal?", "When did tart last save a dish?"], adventures: ["Eat cranberry relish today. Tart. Sweet. With turkey if you have it.", "Make it fresh. The can is a lie."] },
  "11-23": { title: "National Espresso Day", tagline: "Espresso. Small cup. Big energy.", meaning: "National Espresso Day. Espresso is coffee concentrated — small cup, big energy, and the foundation of every fancy coffee drink. It means small is powerful. The espresso is proof.", anchorQuestion: "What small thing in your life has big energy?", whoIsThisSoul: ["What is your espresso — the small thing with big energy?", "When did a small cup last change your day?"], adventures: ["Drink espresso today. Small cup. Big sip.", "Make a fancy coffee drink. The espresso is the base."] },
  "11-24": { title: "National Sardines Day", tagline: "Sardines: the tiny fish with a big reputation.", meaning: "National Sardines Day. Sardines are tiny fish with a big reputation — loved, hated, and packed in a tin. It means small fish can be big deals. The sardine is proof.", anchorQuestion: "What sardine in your life is small but mighty?", whoIsThisSoul: ["What is your sardine — the tiny thing with a big reputation?", "When did a small fish last surprise you?"], adventures: ["Eat sardines today, if you can. On toast. With lemon.", "If you cannot, eat a tiny food. The tininess is the point."] },
  "11-25": { title: "National Parfait Day", tagline: "Parfaits. Layers. A glass. Go.", meaning: "National Parfait Day. A parfait is just dessert with architecture — layers you can see through the glass. It means presentation is part of the flavor. Eat with your eyes first.", anchorQuestion: "What layers are you hiding that deserve to be seen?", whoIsThisSoul: ["What is your parfait — the thing that is better in layers?", "When did you last make something beautiful just to eat it?"], adventures: ["Eat a parfait today. Layers visible.", "Layer something today — dessert, outfit, or a plan."] },
  "11-26": { title: "National Cake Day", tagline: "Cake. The whole day. That is the post.", meaning: "National Cake Day. Cake is the dessert that means celebration — birthdays, weddings, Tuesdays. It means cake is not a treat. Cake is a system.", anchorQuestion: "What cake would you eat all day if you could?", whoIsThisSoul: ["What is your cake — the dessert that means celebration?", "When did cake last make a day?"], adventures: ["Eat cake today. Any cake. All cakes.", "Bake a cake. Or buy one. Both count."] },
  "11-27": { title: "National Bavarian Cream Pie Day", tagline: "Bavarian cream pie: the fancy pie.", meaning: "National Bavarian Cream Pie Day. Bavarian cream pie is the fancy pie — custard, cream, and a crust. It means some pies are formal. The Bavarian cream is proof.", anchorQuestion: "What fancy pie are you?", whoIsThisSoul: ["What is your Bavarian cream pie — the fancy thing?", "When did fancy last feel worth it?"], adventures: ["Eat Bavarian cream pie today. Fancy. With a fork.", "Be fancy for one slice. Just one."] },
  "11-28": { title: "National French Toast Day", tagline: "French toast: the bread that became dessert.", meaning: "National French Toast Day. French toast is bread that became dessert — soaked in egg, fried in butter, and topped with syrup. It means bread can be dessert. The French toast is proof.", anchorQuestion: "What bread in your life became dessert?", whoIsThisSoul: ["What is your French toast — the thing that transformed?", "When did breakfast last taste like dessert?"], adventures: ["Eat French toast today. Syrup mandatory.", "Make it. Soak the bread. Fry it. Top it."] },
  "11-29": { title: "National Lemon Cream Pie Day", tagline: "Lemon cream pie: the tart, creamy, perfect thing.", meaning: "National Lemon Cream Pie Day. Lemon cream pie is tart, creamy, and perfect — the pie that balances sweet and sour. It means balance is a flavor. The pie is proof.", anchorQuestion: "What balances sweet and sour in your life?", whoIsThisSoul: ["What is your lemon cream pie — the balance?", "When did tart last beat sweet?"], adventures: ["Eat lemon cream pie today. Tart. Creamy.", "If there is no pie, eat lemon anything."] },
  "11-30": { title: "National Mousse Day", tagline: "Mousse: the dessert that is also air.", meaning: "National Mousse Day. Mousse is the dessert that is also air — light, fluffy, and impossible to eat neatly. It means some desserts are clouds. The mousse is proof.", anchorQuestion: "What mousse in your life is also air?", whoIsThisSoul: ["What is your mousse — the light, fluffy thing?", "When did light last beat heavy?"], adventures: ["Eat mousse today. Chocolate. Light. Fluffy.", "Eat it with a spoon. Slowly. The mousse deserves it."] },
  // ---- December ----
  "12-01": { title: "National Eat a Red Apple Day", tagline: "Red apples. Crisp. Sweet. The original snack.", meaning: "National Eat a Red Apple Day. A red apple is the original snack — crisp, sweet, and portable. It means the simplest food is sometimes the best. The apple is proof.", anchorQuestion: "What is your apple — the original snack?", whoIsThisSoul: ["When did an apple last fix a craving?", "What would you teach with an apple?"], adventures: ["Eat a red apple today. Crisp. Loud crunch mandatory.", "Cut it into slices. Or bite it whole. Both count."] },
  "12-02": { title: "National Mutt Day", tagline: "Mutts. The best dogs. No papers required.", meaning: "National Mutt Day. Mutts are the best dogs — no papers, no pedigree, just love. It means purebred is not better. The mutt is proof.", anchorQuestion: "What mutt in your life is the best?", whoIsThisSoul: ["What is your mutt — the mixed, unpapered, perfect thing?", "When did a mutt last steal your heart?"], adventures: ["Celebrate a mutt today. Yours or someone else's.", "Adopt a mutt. Or donate to a shelter."] },
  "12-03": { title: "National Apple Pie Day", tagline: "Apple pie. As American as apple pie.", meaning: "National Apple Pie Day. Apple pie is as American as apple pie — the dessert that means home, holidays, and a whole country. It means some pies are identities. The apple pie is America.", anchorQuestion: "What pie means home to you?", whoIsThisSoul: ["What is your apple pie — the dessert that means home?", "When did apple pie last make a day?"], adventures: ["Eat apple pie today. With ice cream. Obviously.", "Bake one. The crust is the whole game."] },
  "12-04": { title: "National Cookie Day", tagline: "Cookies. The whole day. That is the post.", meaning: "National Cookie Day. Cookies are the food that works for every occasion — birthdays, holidays, Tuesdays. It means some foods are universal. The cookie is one of them.", anchorQuestion: "What is your cookie?", whoIsThisSoul: ["What cookie would you be?", "When did a cookie last fix a day?"], adventures: ["Eat cookies today. Any cookie. All cookies.", "Bake cookies. Share them. Or do not."] },
  "12-05": { title: "National Sacher Torte Day", tagline: "Sacher torte: the fancy chocolate cake.", meaning: "National Sacher Torte Day. Sacher torte is the fancy chocolate cake — dense, dark, and Viennese. It means some cakes are formal. The Sacher torte is proof.", anchorQuestion: "What fancy cake are you?", whoIsThisSoul: ["What is your Sacher torte — the fancy thing?", "When did fancy last feel worth it?"], adventures: ["Eat Sacher torte today, if you can. Or any fancy chocolate cake.", "Be fancy for one slice. Just one."] },
  "12-06": { title: "National Gazpacho Day", tagline: "Gazpacho: the soup that is also a salad.", meaning: "National Gazpacho Day. Gazpacho is soup served cold — tomatoes, peppers, and cucumbers blended into a chilled bowl. It means soup does not have to be hot. The gazpacho is proof.", anchorQuestion: "What cold soup in your life is actually good?", whoIsThisSoul: ["What is your gazpacho — the thing that breaks the rules?", "When did cold last beat hot?"], adventures: ["Eat gazpacho today. Cold. With bread.", "Blend a cold soup. Any soup. Chill it."] },
  "12-07": { title: "National Cotton Candy Day", tagline: "Cotton candy: sugar spun into clouds.", meaning: "National Cotton Candy Day. Cotton candy is sugar spun into clouds — pink, fluffy, and gone in three bites. It means some foods are pure joy. The cotton candy is proof.", anchorQuestion: "What cotton candy in your life is pure joy?", whoIsThisSoul: ["What is your cotton candy — the thing that is pure joy?", "When did sugar last become a cloud?"], adventures: ["Eat cotton candy today. Pink. Fluffy. Gone in three bites.", "If there is no cotton candy, eat something pink and sweet."] },
  "12-08": { title: "National Brownie Day", tagline: "Brownies. The dense, fudgy, perfect thing.", meaning: "National Brownie Day. Brownies are dense, fudgy, and perfect — the chocolate cake that decided to be a square. It means some cakes are squares. The brownie is proof.", anchorQuestion: "What is your brownie — the dense, fudgy, perfect thing?", whoIsThisSoul: ["Fudgy or cakey? This defines you.", "When did a brownie last fix a day?"], adventures: ["Eat brownies today. Fudgy. Warm. With ice cream if you are brave.", "Bake them. Or buy them. Both count."] },
  "12-09": { title: "National Pastry Day", tagline: "Pastry. The flaky, buttery, perfect thing.", meaning: "National Pastry Day. Pastry is flour and butter layered until it becomes something else — flaky, golden, and impossible to eat neatly. It means layers matter. The pastry is proof.", anchorQuestion: "What layers in your life make it flaky and golden?", whoIsThisSoul: ["What is your pastry — the flaky, buttery thing?", "When did layers last make something better?"], adventures: ["Eat pastry today. Flaky. Buttery. With coffee.", "Make pastry. Or buy it. Both count."] },
  "12-10": { title: "National Lager Day", tagline: "Lager. The crisp, cold, perfect beer.", meaning: "National Lager Day. Lager is the crisp, cold beer — the one that built a whole industry. It means some beers are standards. The lager is proof.", anchorQuestion: "What is your lager — the crisp, cold standard?", whoIsThisSoul: ["What does lager mean to you?", "When did a lager last feel like the right choice?"], adventures: ["Drink a lager today, if you drink. Cold. Crisp.", "If you do not drink, drink something cold and crisp."] },
  "12-11": { title: "National Noodle Ring Day", tagline: "Noodle ring: the pasta that became a wreath.", meaning: "National Noodle Ring Day. A noodle ring is pasta shaped into a ring — the only pasta that is also a wreath. It means pasta can be anything. The ring is proof.", anchorQuestion: "What ring in your life is also pasta?", whoIsThisSoul: ["What is your noodle ring — the thing shaped like a wreath?", "When did pasta last become a decoration?"], adventures: ["Eat a noodle ring today. Or any pasta in a ring shape.", "Make a wreath. Pasta or otherwise."] },
  "12-12": { title: "National Poinsettia Day", tagline: "Poinsettias. The red flower that means Christmas.", meaning: "National Poinsettia Day. Poinsettias are the red flowers that mean Christmas — bright, bold, and everywhere in December. It means some flowers are seasons. The poinsettia is Christmas.", anchorQuestion: "What flower means Christmas to you?", whoIsThisSoul: ["What is your poinsettia — the flower that means a season?", "When did a flower last mean a holiday?"], adventures: ["Buy a poinsettia today. Red. Bright. On the table.", "Or admire one. They are everywhere in December."] },
  "12-13": { title: "National Cocoa Day", tagline: "Cocoa. The warm, chocolatey, perfect drink.", meaning: "National Cocoa Day. Cocoa is chocolate in a mug — warm, rich, and the drink that means winter. It means some drinks are seasons. The cocoa is winter.", anchorQuestion: "What drink means winter to you?", whoIsThisSoul: ["What is your cocoa — the warm, chocolatey thing?", "When did cocoa last warm more than your hands?"], adventures: ["Drink cocoa today. Warm. With marshmallows.", "Make it from scratch. Or from a packet. Both count."] },
  "12-14": { title: "National Bouillabaisse Day", tagline: "Bouillabaisse: the fish stew that is also a story.", meaning: "National Bouillabaisse Day. Bouillabaisse is a fish stew that is also a story — Provençal, coastal, and full of the sea. It means stew is story. The bouillabaisse is proof.", anchorQuestion: "What stew tells your story?", whoIsThisSoul: ["What is your bouillabaisse — the stew that is also a story?", "When did a stew last tell you something?"], adventures: ["Eat bouillabaisse today, if you can. Or any fish stew.", "If you do not eat fish, eat a stew that tells a story."] },
  "12-15": { title: "National Cupcake Day", tagline: "Cupcakes. The portable celebration.", meaning: "National Cupcake Day. A cupcake is cake you can hold — the portable celebration. It means some cakes are meant to be handheld. The cupcake is proof.", anchorQuestion: "What is your cupcake — the portable celebration?", whoIsThisSoul: ["What would you put on a cupcake if you could put anything on it?", "When did a cupcake last make a day?"], adventures: ["Eat a cupcake today. Frosting mandatory.", "Bake cupcakes. Share them. Or do not."] },
  "12-16": { title: "National Chocolate Covered Anything Day", tagline: "Chocolate covered anything. The rule is in the name.", meaning: "National Chocolate Covered Anything Day. The rule is in the name — cover anything in chocolate. It means chocolate improves everything. The covering is the point.", anchorQuestion: "What would you cover in chocolate?", whoIsThisSoul: ["What is your chocolate covered anything — the thing made better by chocolate?", "When did chocolate last improve something unexpected?"], adventures: ["Cover something in chocolate today. Anything.", "Dip a strawberry. Dip a pretzel. Dip a marshmallow. All count."] },
  "12-17": { title: "National Maple Syrup Day", tagline: "Maple syrup. The sweet, sticky, perfect thing.", meaning: "National Maple Syrup Day. Maple syrup is sap boiled down until it becomes liquid gold — the sweet, sticky, perfect thing. It means patience is a flavor. The syrup is proof.", anchorQuestion: "What sap in your life needs boiling down?", whoIsThisSoul: ["What is your maple syrup — the thing that took patience and became gold?", "When did patience last pay off?"], adventures: ["Eat maple syrup today. On pancakes. On waffles. On anything.", "Use real maple syrup. The fake stuff is a lie."] },
  "12-18": { title: "National Roast Suckling Pig Day", tagline: "Roast suckling pig: the feast that means business.", meaning: "National Roast Suckling Pig Day. A roast suckling pig is a feast that means business — the centerpiece, the showstopper, the whole table. It means some meals are events. The pig is proof.", anchorQuestion: "What feast in your life means business?", whoIsThisSoul: ["What is your roast suckling pig — the feast that means business?", "When did a feast last feel like an event?"], adventures: ["Eat roast pork today. Any roast. The feast is the point.", "Make a meal an event. Set the table. Light a candle."] },
  "12-19": { title: "National Oatmeal Muffin Day", tagline: "Oatmeal muffins: the healthy muffin. Allegedly.", meaning: "National Oatmeal Muffin Day. An oatmeal muffin is the healthy muffin — oats, bran, and a story about fiber. It means healthy can taste good. The muffin is proof.", anchorQuestion: "What healthy thing do you actually like?", whoIsThisSoul: ["What is your oatmeal muffin — the healthy thing that tastes good?", "When did healthy last taste like a treat?"], adventures: ["Eat an oatmeal muffin today. Warm. With butter.", "Bake them. Or buy them. Both count."] },
  "12-20": { title: "National Sangria Day", tagline: "Sangria: the wine that became a fruit salad.", meaning: "National Sangria Day. Sangria is wine that became a fruit salad — red wine, fruit, and a pitcher. It means wine can be a party. The sangria is proof.", anchorQuestion: "What fruit would you put in your sangria?", whoIsThisSoul: ["What is your sangria — the wine that became a party?", "When did sangria last make a gathering?"], adventures: ["Drink sangria today, if you drink. Fruit mandatory.", "If you do not drink, make fruit punch. Same pitcher, same party."] },
  "12-21": { title: "National French Fried Shrimp Day", tagline: "French fried shrimp: the sea's little crunch.", meaning: "National French Fried Shrimp Day. French fried shrimp are the sea's little crunch — crispy, salty, and best with cocktail sauce. It means some seafood is meant to be fried. The shrimp is proof.", anchorQuestion: "What seafood would you fry?", whoIsThisSoul: ["What is your french fried shrimp — the sea's little crunch?", "When did fried seafood last make a day?"], adventures: ["Eat french fried shrimp today. Crispy. With cocktail sauce.", "If you do not eat seafood, eat something crispy."] },
  "12-22": { title: "National Date Nut Bread Day", tagline: "Date nut bread: the bread with a past.", meaning: "National Date Nut Bread Day. Date nut bread is bread with dates and nuts — sweet, dense, and old-fashioned. It means some breads are history. The date nut bread is proof.", anchorQuestion: "What bread in your life has a past?", whoIsThisSoul: ["What is your date nut bread — the bread with a past?", "When did bread last taste like history?"], adventures: ["Eat date nut bread today. With cream cheese.", "Bake it. Or buy it. Both count."] },
  "12-23": { title: "National Pfeffernusse Day", tagline: "Pfeffernusse: the cookie with a name you cannot say.", meaning: "National Pfeffernusse Day. Pfeffernusse are German spice cookies with a name nobody can pronounce — pepper, nuts, and a whole winter. It means names do not matter. The cookie is the point.", anchorQuestion: "What cookie in your life has a name you cannot say?", whoIsThisSoul: ["What is your pfeffernusse — the thing with an impossible name?", "When did a name last stop you from trying something?"], adventures: ["Eat pfeffernusse today, if you can. Or any spice cookie.", "Try to pronounce it. Fail. Eat the cookie anyway."] },
  "12-24": { title: "National Eggnog Day", tagline: "Eggnog. The drink that means Christmas Eve.", meaning: "National Eggnog Day. Eggnog is the drink that means Christmas Eve — eggs, cream, nutmeg, and a whole season. It means some drinks are holidays. The eggnog is Christmas.", anchorQuestion: "What drink means Christmas Eve to you?", whoIsThisSoul: ["What is your eggnog — the drink that means a holiday?", "When did eggnog last make a night?"], adventures: ["Drink eggnog today. With nutmeg. With or without the spike.", "If you hate eggnog, drink something that means Christmas Eve to you."] },
  "12-25": { title: "Christmas Day", tagline: "Merry Christmas. The whole day. The whole point.", meaning: "Christmas Day. The day that means giving, family, and a tree with lights — the holiday that built a whole season around itself. It means giving is the point. The tree is just the decoration.", anchorQuestion: "What are you giving this Christmas?", whoIsThisSoul: ["What does Christmas mean to you — really?", "When did Christmas last feel like Christmas?"], adventures: ["Celebrate Christmas today. Your way. No rules.", "Give something. Anything. The giving is the point."] },
  "12-26": { title: "National Candy Cane Day", tagline: "Candy canes. The striped, minty, perfect thing.", meaning: "National Candy Cane Day. Candy canes are striped, minty, and hooked — the only candy that is also a decoration. It means candy can be art. The cane is proof.", anchorQuestion: "What candy in your life is also art?", whoIsThisSoul: ["What is your candy cane — the striped, minty thing?", "When did candy last decorate a tree?"], adventures: ["Eat a candy cane today. Or hang one on a tree.", "Hook it on a mug. The mug is the tree."] },
  "12-27": { title: "National Fruitcake Day", tagline: "Fruitcake: the cake everyone jokes about. Eat it anyway.", meaning: "National Fruitcake Day. Fruitcake is the cake everyone jokes about — dense, fruity, and regifted more than any dessert in history. It means the joke is the tradition. The fruitcake is proof.", anchorQuestion: "What fruitcake in your life gets joked about but is actually good?", whoIsThisSoul: ["What is your fruitcake — the thing everyone jokes about?", "When did a joke last become a tradition?"], adventures: ["Eat fruitcake today. With coffee. With courage.", "If you hate fruitcake, eat a cake nobody jokes about."] },
  "12-28": { title: "National Chocolate Candy Day", tagline: "Chocolate candy. The whole day. No apologies.", meaning: "National Chocolate Candy Day. Chocolate candy is chocolate in its purest form — bars, truffles, and everything in between. It means chocolate is not a treat. Chocolate is a system.", anchorQuestion: "What chocolate candy fixes your day?", whoIsThisSoul: ["What is your chocolate candy — the thing that fixes every mood?", "When did chocolate candy last save you?"], adventures: ["Eat chocolate candy today. Your favorite. By the handful.", "Share it. Or do not. Both count."] },
  "12-29": { title: "National Pepper Pot Day", tagline: "Pepper pot: the soup with a kick.", meaning: "National Pepper Pot Day. Pepper pot is a soup with a kick — spicy, hearty, and the first soup ever served in America. It means soup can have a kick. The pepper pot is proof.", anchorQuestion: "What soup in your life has a kick?", whoIsThisSoul: ["What is your pepper pot — the soup with a kick?", "When did a soup last surprise you?"], adventures: ["Eat pepper pot today, if you can. Or any spicy soup.", "Add pepper to a soup. The kick is the point."] },
  "12-30": { title: "National Bicarbonate of Soda Day", tagline: "Baking soda. The box that does everything.", meaning: "National Bicarbonate of Soda Day. Baking soda is the box that does everything — baking, cleaning, deodorizing, and a science fair volcano. It means the simplest things are the most versatile. The box is proof.", anchorQuestion: "What baking soda in your life does everything?", whoIsThisSoul: ["What is your baking soda — the thing that does everything?", "When did baking soda last save you?"], adventures: ["Use baking soda today. Bake, clean, or deodorize.", "Make a volcano. You know you want to."] },
  "12-31": { title: "New Year's Eve", tagline: "The last day. The countdown. The confetti.", meaning: "New Year's Eve. The last day of the year — the countdown, the confetti, and the promise that next year will be different. It means endings are beginnings with confetti. The countdown is the point.", anchorQuestion: "What are you counting down to?", whoIsThisSoul: ["What would you leave in this year if you could?", "What are you bringing into next year?"], adventures: ["Count down tonight. Out loud. With confetti.", "Write down one thing you are leaving in this year. Burn it."] },
};

// ---------------------------------------------------------------------------
// MOVABLE HOLIDAYS — computed from the year in the date string.
// The app rolls year-agnostic (MM-DD keys), but these feasts move, so we
// compute them from the year embedded in the incoming YYYY-MM-DD string.
// ---------------------------------------------------------------------------
function nthWeekdayOfMonth(year: number, month: number, weekday: number, n: number): number {
  // month is 1-based; weekday 0 = Sunday … 6 = Saturday; n is 1-based
  const first = new Date(year, month - 1, 1);
  const offset = (weekday - first.getDay() + 7) % 7;
  return 1 + offset + (n - 1) * 7;
}

function lastWeekdayOfMonth(year: number, month: number, weekday: number): number {
  const last = new Date(year, month, 0); // last day of the month
  const offset = (last.getDay() - weekday + 7) % 7;
  return last.getDate() - offset;
}

function pad2(n: number): string {
  return n < 10 ? `0${n}` : `${n}`;
}

/** Movable feasts, keyed by full YYYY-MM-DD. */
function getMovableHoliday(dateString: string): KhaosHoliday | null {
  const year = Number(dateString.slice(0, 4));
  if (!Number.isFinite(year)) return null;
  const mk = (mmdd: string, entry: RealHoliday): KhaosHoliday => {
    const [month, day] = mmdd.split("-").map(Number);
    return { dateKey: mmdd, month, day, ...entry };
  };
  const movable: Record<string, RealHoliday> = {
    [`${year}-06-${pad2(nthWeekdayOfMonth(year, 6, 5, 1))}`]: {
      title: "National Donut Day",
      tagline: "Donuts. Free ones. The Salvation Army started it.",
      meaning: "National Donut Day, the first Friday in June. Started by the Salvation Army in 1938 to honor the women who served donuts to soldiers in World War I. It means donuts are not just donuts — they are gratitude with frosting. The free ones taste best.",
      anchorQuestion: "What donut would you serve a soldier?",
      whoIsThisSoul: ["What is your donut — the thing you serve with love?", "When did a donut last feel like gratitude?"],
      adventures: ["Eat a donut today. A free one if you can find it.", "Give a donut to someone. The giving is the holiday."],
    },
    [`${year}-07-${pad2(nthWeekdayOfMonth(year, 7, 0, 3))}`]: {
      title: "National Ice Cream Day",
      tagline: "Ice cream. The whole day. Presidentially decreed.",
      meaning: "National Ice Cream Day, the third Sunday in July. Proclaimed by President Reagan in 1984, because America loves ice cream enough to need a presidential decree. It means ice cream is not a treat. Ice cream is policy.",
      anchorQuestion: "What flavor would you decree?",
      whoIsThisSoul: ["What is your ice cream — the flavor that is also a policy?", "When did ice cream last feel presidential?"],
      adventures: ["Eat ice cream today. Any flavor. All flavors.", "Eat it outside. The sun is part of the recipe."],
    },
    [`${year}-08-${pad2(nthWeekdayOfMonth(year, 8, 0, 1))}`]: {
      title: "National Friendship Day",
      tagline: "Friends. The family you picked. Again.",
      meaning: "National Friendship Day, the first Sunday in August. Friends are the family you chose — the ones who know the stories, the passwords, and the version of you from before you were cool. It means chosen family is real family.",
      anchorQuestion: "Who is your friend — the one who knows everything?",
      whoIsThisSoul: ["What do your friends know that nobody else does?", "When did a friend last save you?"],
      adventures: ["Contact a friend today. Tell them they matter.", "Do something with a friend. Anything. Even nothing."],
    },
    [`${year}-12-${pad2(nthWeekdayOfMonth(year, 12, 5, 3))}`]: {
      title: "National Ugly Christmas Sweater Day",
      tagline: "The uglier the sweater, the better the day.",
      meaning: "National Ugly Christmas Sweater Day, the third Friday in December. The uglier the sweater, the better — jingle bells, reindeer, lights, all of it. It means ugly is a style. The sweater is proof.",
      anchorQuestion: "How ugly is your sweater?",
      whoIsThisSoul: ["What is your ugly sweater — the thing that is ugly and perfect?", "When did ugly last beat pretty?"],
      adventures: ["Wear an ugly Christmas sweater today. The uglier, the better.", "If you have no sweater, wear something ugly on purpose."],
    },
    [`${year}-01-${pad2(lastWeekdayOfMonth(year, 1, 5))}`]: {
      title: "National Fun at Work Day",
      tagline: "Fun at work. The last Friday in January. Mandatory.",
      meaning: "National Fun at Work Day, the last Friday in January. Work is not supposed to be fun — which is exactly why this day exists. It means fun is not the opposite of work. Fun is the fuel.",
      anchorQuestion: "What fun would you bring to work?",
      whoIsThisSoul: ["What is your fun at work — the thing that makes the job bearable?", "When did fun last make work better?"],
      adventures: ["Have fun at work today. Deliberately. With witnesses.", "Prank a coworker. Harmlessly. The harmless part is the rule."],
    },
  };
  const hit = movable[dateString];
  if (!hit) return null;
  const [month, day] = dateString.slice(5).split("-").map(Number);
  return { dateKey: dateString.slice(5), month, day, ...hit };
}

// ---------------------------------------------------------------------------
// LOOKUP — CORE (Off*Script's own) → movable feasts → real fixed table.
// ---------------------------------------------------------------------------
export function getHolidayForDate(dateString: string): KhaosHoliday {
  const mmdd = dateString.slice(5, 10);
  const core = CORE_HOLIDAYS[mmdd];
  if (core) return core;
  const movable = getMovableHoliday(dateString);
  if (movable) return movable;
  const real = REAL_HOLIDAYS[mmdd];
  if (real) {
    const [month, day] = mmdd.split("-").map(Number);
    return { dateKey: mmdd, month, day, ...real };
  }
  // Defensive fallback — should be unreachable now that the real table
  // covers every day of the year (including 02-29), but never return null.
  const [month, day] = mmdd.split("-").map(Number);
  return {
    dateKey: mmdd,
    month: month || 1,
    day: day || 1,
    title: "National Make Something Up Day",
    tagline: "No holiday on the books. Make one up.",
    meaning: "No holiday on the books for today — which means the day is unwritten. It means you get to decide what today means. Make it up. Name it. Celebrate it.",
    anchorQuestion: "What holiday would you invent for today?",
    whoIsThisSoul: ["What would your invented holiday celebrate?", "If today had a name, what would it be?"],
    adventures: ["Invent a holiday for today. Name it. Celebrate it.", "Tell someone about your invented holiday."],
  };
}
